window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["sf"]={"id":"sf","num":3,"name":"Sports & Fitness Nutrition","area":"Performance","lessons":[{"n":1,"title":"Introduction to Sports Nutrition","kicker":"Connect an athlete’s training demands with nutrition, then learn how to judge the evidence behind a recommendation.","steps":[{"id":"sf1-0","chapter":"Training, nutrition, and the athlete","title":"Training, nutrition, and the athlete","html":"<h3>Training and nutrition belong in one plan</h3><p>Exercise physiology explains the body’s acute responses and long-term adaptations to training. Sports nutrition applies that science to energy, macronutrients, micronutrients, fluid, recovery, and performance. Recommendations must match the athlete’s sport, position, training phase, goals, preferences, budget, culture, medical history, and access to food. A strategy used by an elite endurance athlete is not automatically appropriate for a recreational strength athlete.</p><h3>Training principles that change nutrition needs</h3><p>Overload creates an adaptation signal; progression changes that signal over time; specificity means the response reflects the work performed; recovery allows adaptation to occur. Periodization changes volume, intensity, and specificity across the year. Nutrition should follow those changes rather than remain fixed: higher-load phases usually need more total energy and carbohydrate, while recovery phases may need less energy but still require protein and micronutrient adequacy.</p>","visual":{"title":"Training, nutrition, and the athlete","kind":"comparison","items":[{"label":"Progressive overload","detail":"Gradually increase the training stimulus to encourage adaptation."},{"label":"Individuality","detail":"People differ in their needs and responses."},{"label":"Specificity","detail":"Adaptations reflect the type of training performed."},{"label":"Hard/easy","detail":"Balance demanding sessions with recovery or easier work."},{"label":"Periodization","detail":"Organize training into planned phases with changing goals, volume and intensity."},{"label":"Disuse","detail":"Adaptations can diminish when the stimulus stops."}]},"blocksHtml":["<h3>Training principles</h3>","<div class=\"tabblk\"><b>Long-term foundation</b><ul class=\"pl\"><li>Enough energy for training and performance.</li><li>Carbohydrate to replenish muscle and liver glycogen.</li><li>Adequate protein and hydration.</li><li>An overall diet supporting good health.</li><li>Appropriate weight and body composition.</li></ul></div><div class=\"tabblk\"><b>Short-term execution</b><ul class=\"pl\"><li>Food and beverages that delay fatigue.</li><li>Minimize dehydration and hypohydration.</li><li>Appropriate precompetition meals and nutrient timing.</li><li>Where appropriate, planned carbohydrate loading or timed caffeine.</li><li>Nutrients that support recovery.</li></ul></div>"]},{"id":"sf1-0-s0","title":"Sort each example","teach":[],"act":{"type":"sort","prompt":"Sort each example","categories":["Physical activity","Exercise","Sport"],"items":[{"label":"Walking upstairs during a normal day","category":0,"feedback":"Bodily movement that raises energy expenditure above rest, including daily tasks."},{"label":"A planned 45-minute interval run","category":1,"feedback":"Exercise is planned, structured and purposeful."},{"label":"A league soccer match","category":2,"feedback":"Sport is competitive physical activity."},{"label":"Gardening for an afternoon","category":0,"feedback":"Everyday movement above rest, not planned training."},{"label":"A structured weight-training session","category":1,"feedback":"Planned and purposeful, so exercise."},{"label":"A regional track meet","category":2,"feedback":"Competition makes it sport."}]}},{"id":"sf1-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Walking upstairs during a normal day is best categorized as:","options":[{"label":"Physical activity","correct":true,"feedback":"Movement that raises energy expenditure above rest counts as physical activity. Exercise is planned and structured, and sport is competitive."},{"label":"Exercise","correct":false,"feedback":"Movement that raises energy expenditure above rest counts as physical activity. Exercise is planned and structured, and sport is competitive."},{"label":"Sport","correct":false,"feedback":"Movement that raises energy expenditure above rest counts as physical activity. Exercise is planned and structured, and sport is competitive."}]}},{"id":"sf1-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A macrocycle is best described as:","options":[{"label":"The broad training plan","correct":true,"feedback":"A macrocycle is the broad plan, a mesocycle is a phase within it, and a microcycle is a shorter recurring block."},{"label":"A phase within the plan","correct":false,"feedback":"A macrocycle is the broad plan, a mesocycle is a phase within it, and a microcycle is a shorter recurring block."},{"label":"A short recurring training block","correct":false,"feedback":"A macrocycle is the broad plan, a mesocycle is a phase within it, and a microcycle is a shorter recurring block."},{"label":"A single session","correct":false,"feedback":"A macrocycle is the broad plan, a mesocycle is a phase within it, and a microcycle is a shorter recurring block."}]}},{"id":"sf1-1","chapter":"Nutrition standards and labels","title":"Nutrition standards and labels","html":"<h3>Dietary standards and food labels</h3><p>The DRI is an umbrella system. The RDA meets the needs of nearly all healthy people in a life-stage and sex group; the AI is used when evidence is insufficient for an RDA; the EAR meets the estimated need of half a group and helps assess populations; the UL is the highest usual intake unlikely to create harm. On labels, serving size, calories, nutrients, and percent Daily Value help compare foods, but athlete requirements may differ from the general label reference.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>RDA</b><p><b>Recommended Dietary Allowance.</b> Meets the needs of nearly all (97 to 98%) healthy people in a life-stage and sex group. Used for individual planning.</p></div><div class=\"tabblk\"><b>AI</b><p><b>Adequate Intake.</b> An estimate used when evidence is insufficient to determine an RDA.</p></div><div class=\"tabblk\"><b>EAR</b><p><b>Estimated Average Requirement.</b> Meets the needs of about half a group. Supports group assessment and the development of the RDA.</p></div><div class=\"tabblk\"><b>UL</b><p><b>Tolerable Upper Intake Level.</b> The highest daily intake likely to pose no adverse-effect risk for almost all people. Risk rises above it. It is not a target to aim for.</p></div>","<div class=\"mn-html\"><span>Remember it</span><b>Picture a staircase.</b> The <b>EAR</b> sits on the bottom step (meets only half a group). Climb one step to the <b>RDA</b> (meets nearly everyone). The <b>AI</b> is a step used only when there isn’t enough evidence to build the RDA step at all. The <b>UL</b> is the ceiling at the very top, not a step to aim for, it’s the point where risk starts.</div>","<div class=\"callout\">The DRI is the umbrella system, not another name for the RDA.</div>","<dl class=\"facts\"><div><dt>Added sugars</dt><dd>Below 10% of calories</dd></div><div><dt>Saturated fat</dt><dd>Below 10% of calories</dd></div><div><dt>Sodium</dt><dd>Below 2,300 mg/day</dd></div><div><dt>Historical note</dt><dd>These are the 2015 to 2020 guidelines taught in the deck, not a claim about current guidelines.</dd></div></dl>","<p>On the Nutrition Facts label, serving size reflects amounts typically consumed, not an instruction about how much someone should eat. Compare the number of servings you eat with the amounts listed.</p>"]},{"id":"sf1-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which reference answers the question “how much is too much?”","options":[{"label":"RDA","correct":false,"feedback":"The UL marks the highest usual intake unlikely to cause harm. The RDA and AI support adequacy, and the EAR estimates the needs of half a group."},{"label":"AI","correct":false,"feedback":"The UL marks the highest usual intake unlikely to cause harm. The RDA and AI support adequacy, and the EAR estimates the needs of half a group."},{"label":"EAR","correct":false,"feedback":"The UL marks the highest usual intake unlikely to cause harm. The RDA and AI support adequacy, and the EAR estimates the needs of half a group."},{"label":"UL","correct":true,"feedback":"The UL marks the highest usual intake unlikely to cause harm. The RDA and AI support adequacy, and the EAR estimates the needs of half a group."}]}},{"id":"sf1-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The RDA is set to meet the needs of:","options":[{"label":"About half of a group","correct":false,"feedback":"The RDA covers nearly all healthy people in the group, which is why it is used for individual planning."},{"label":"Nearly all (97 to 98%) healthy people in a life-stage and sex group","correct":true,"feedback":"The RDA covers nearly all healthy people in the group, which is why it is used for individual planning."},{"label":"Only elite athletes","correct":false,"feedback":"The RDA covers nearly all healthy people in the group, which is why it is used for individual planning."},{"label":"Anyone regardless of age","correct":false,"feedback":"The RDA covers nearly all healthy people in the group, which is why it is used for individual planning."}]}},{"id":"sf1-2","chapter":"Sports nutrition guidelines and supplements","title":"Sports nutrition guidelines and supplements","html":"<p>The chapter’s ranges are learning benchmarks. Actual needs depend on the athlete and the training phase: the same person might sit near the bottom of the carbohydrate range on an easy or rest day and near the top during a heavy training block. Try the ranges with a body mass.</p><h3>Where a supplement conversation usually starts</h3><p>An ergogenic aid is anything used to try to enhance performance beyond what training and diet alone provide, from food and fluid strategies to pharmacological agents. Most conversations you will have as a practitioner are really about where a product sits on a spectrum of evidence and risk, not a flat yes or no.</p><div class=\"tabblk\"><b>Well-supported examples</b><p>Creatine monohydrate for repeated short high-intensity efforts, caffeine for endurance and alertness, and sports drinks or gels for carbohydrate during prolonged exercise all have a substantial research base at the doses typically studied.</p></div><div class=\"tabblk\"><b>Mixed or context-dependent</b><p>Beta-alanine, sodium bicarbonate, and dietary nitrate (beetroot juice) show benefits for specific effort durations and some individuals but not universally, and often only close to competition-realistic doses and timing.</p></div><div class=\"tabblk\"><b>Weak or unsupported</b><p>Most “fat burner” blends, many amino acid or hormone-precursor products, and most branded proprietary blends lack consistent, independently replicated evidence, whatever the marketing claims.</p></div><h3>Five questions before using an ergogenic aid</h3><div class=\"mn-html\"><span>Remember it</span><b>“Lawyers Examine Pills Super Effectively.”</b> Legality, Ethics, Purity, Safety, Effectiveness, in that order, L-E-P-S-E. Run through the sentence before you answer any ergogenic-aid question.</div><div class=\"callout\">“Standardized” means a consistent specified amount of an active ingredient per unit. It does not on its own establish safety, purity or benefit. Testimonials are not substitutes for research.</div>","visual":{"title":"Sports nutrition guidelines and supplements","kind":"sequence","items":[{"label":"Legality","detail":"Is it permitted by the relevant sport and jurisdiction?"},{"label":"Ethics","detail":"Does its use respect the rules and principles of competition?"},{"label":"Purity","detail":"Does the product contain what it claims, without unwanted ingredients?"},{"label":"Safety","detail":"What are the risks, interactions and uncertainties?"},{"label":"Effectiveness","detail":"Does good research support the claimed benefit?"}]},"blocksHtml":[]},{"id":"sf1-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which of these is NOT one of the five questions for judging an ergogenic aid?","options":[{"label":"Legality","correct":false,"feedback":"The five are legality, ethics, purity, safety and effectiveness."},{"label":"Ethics","correct":false,"feedback":"The five are legality, ethics, purity, safety and effectiveness."},{"label":"Purity","correct":false,"feedback":"The five are legality, ethics, purity, safety and effectiveness."},{"label":"Popularity","correct":true,"feedback":"The five are legality, ethics, purity, safety and effectiveness."}]}},{"id":"sf1-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"“Standardized” on a supplement label means:","options":[{"label":"A consistent specified amount of the active ingredient per unit","correct":true,"feedback":"Standardization alone does not establish safety, purity or performance benefit."},{"label":"The product is proven safe","correct":false,"feedback":"Standardization alone does not establish safety, purity or performance benefit."},{"label":"The product is proven effective","correct":false,"feedback":"Standardization alone does not establish safety, purity or performance benefit."},{"label":"An independent lab approved it","correct":false,"feedback":"Standardization alone does not establish safety, purity or performance benefit."}]}},{"id":"sf1-3","chapter":"Evaluating scientific evidence","title":"Evaluating scientific evidence","html":"<h3>Evidence and professional judgment</h3><p>Case reports can generate questions but do not prove a general effect. Epidemiological research identifies associations but cannot establish causation by itself. Experimental studies are stronger when they include an appropriate comparison, random assignment, blinding, valid measurements, and enough participants. One study rarely settles a question; peer review, replication, consistency, effect size, and relevance to the client all matter.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Case study</b><p>Detailed observation of an individual or small case. Useful for generating questions, weak for general conclusions.</p></div><div class=\"tabblk\"><b>Epidemiological</b><p>Examines patterns and associations in populations. Association alone does not establish causation.</p></div><div class=\"tabblk\"><b>Experimental</b><p>Tests an intervention against a comparison. Design quality determines how confidently it supports a conclusion.</p></div>","<dl class=\"facts\"><div><dt>Control group</dt><dd>Provides the comparison.</dd></div><div><dt>Random assignment</dt><dd>Reduces systematic differences between groups.</dd></div><div><dt>Placebo</dt><dd>Accounts for expectation.</dd></div><div><dt>Double-blind</dt><dd>Participants and relevant researchers are unaware of allocation.</dd></div><div><dt>Crossover</dt><dd>Participants receive different conditions at different times.</dd></div></dl>","<div class=\"mn-html\"><span>Remember it</span><b>Count down, confidence goes down.</b> Grade I is the best evidence you can get (think “I’m #1”); by Grade IV you’re down to someone’s clinical opinion. The number rises as the proof gets weaker.</div>"]},{"id":"sf1-3-s0","title":"Match the grade of evidence","teach":[],"act":{"type":"sort","prompt":"Match the grade of evidence","categories":["Grade I / Level A","Grade II / Level B","Grade III / Level C","Grade IV / Level D"],"items":[{"label":"Good evidence, high confidence","category":0,"feedback":"Grade I is the strongest."},{"label":"Fair evidence, less convincing results","category":1,"feedback":"Grade II."},{"label":"Limited evidence","category":2,"feedback":"Grade III."},{"label":"Expert opinion grounded in clinical experience","category":3,"feedback":"Grade IV."}]}},{"id":"sf1-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A survey finds athletes who take supplement X have faster race times. Does that establish that X caused the faster times?","options":[{"label":"Yes, the difference is clear","correct":false,"feedback":"Training, selection and diet could explain it. Controlled research and the cumulative evidence are needed to judge causation."},{"label":"No, this is an association and other factors could explain it","correct":true,"feedback":"Training, selection and diet could explain it. Controlled research and the cumulative evidence are needed to judge causation."},{"label":"Yes, if the sample is large","correct":false,"feedback":"Training, selection and diet could explain it. Controlled research and the cumulative evidence are needed to judge causation."},{"label":"Only if the athletes were elite","correct":false,"feedback":"Training, selection and diet could explain it. Controlled research and the cumulative evidence are needed to judge causation."}]}},{"id":"sf1-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which safeguard keeps participants and relevant researchers unaware of who receives the treatment?","options":[{"label":"Crossover design","correct":false,"feedback":"Double-blinding hides allocation from participants and the researchers who assess outcomes."},{"label":"Random assignment","correct":false,"feedback":"Double-blinding hides allocation from participants and the researchers who assess outcomes."},{"label":"Double-blinding","correct":true,"feedback":"Double-blinding hides allocation from participants and the researchers who assess outcomes."},{"label":"Peer review","correct":false,"feedback":"Double-blinding hides allocation from participants and the researchers who assess outcomes."}]}},{"id":"sf1-4","chapter":"Credentials and scope of practice","title":"Credentials and scope of practice","html":"<h3>Credentials and scope</h3><p>Credentials differ in education, supervised practice, examination, and legal recognition. A nutrition professional should know what assessment, education, counselling, diagnosis, supplementation, and medical nutrition activities are permitted locally. Good practice includes informed consent, documentation, referral, and collaboration with physicians, dietitians, mental-health professionals, athletic therapists, and coaches when the client’s needs cross professional boundaries.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Credential</th><th>What it is</th></tr></thead><tbody><tr><td>ACSM</td><td>Clinical exercise physiologists, exercise physiologists, group exercise instructors and personal trainers</td></tr><tr><td>CSCS (NSCA)</td><td>Certified Strength and Conditioning Specialist</td></tr><tr><td>ATC</td><td>Certified Athletic Trainer</td></tr><tr><td>RD / RDN</td><td>Registered Dietitian/Nutritionist, with national certification, licensure and Medical Nutrition Therapy (MNT)</td></tr><tr><td>Nutritionist</td><td>A general term with varying academic preparation</td></tr><tr><td>CSSD</td><td>Board Certified Specialist in Sports Dietetics</td></tr><tr><td>CISSN</td><td>Certified Sports Nutritionist (International Society of Sports Nutrition)</td></tr></tbody></table></div>","<div class=\"callout\">Scope of practice defines professional boundaries and protects clients. Recognize the limits of your knowledge, training and expertise.</div>"]},{"id":"sf1-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A job title alone tells you:","options":[{"label":"Exactly what someone is permitted to do","correct":false,"feedback":"Credentials, experience and jurisdiction all matter."},{"label":"Little about the depth of their training","correct":true,"feedback":"Credentials, experience and jurisdiction all matter."},{"label":"Their level of experience","correct":false,"feedback":"Credentials, experience and jurisdiction all matter."},{"label":"Whether they can prescribe supplements","correct":false,"feedback":"Credentials, experience and jurisdiction all matter."}]}},{"id":"sf1-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which credential is a Board Certified Specialist in Sports Dietetics?","options":[{"label":"CSCS","correct":false,"feedback":"CSSD. CSCS is strength and conditioning, CISSN is the ISSN sports nutritionist, and ATC is athletic trainer."},{"label":"CSSD","correct":true,"feedback":"CSSD. CSCS is strength and conditioning, CISSN is the ISSN sports nutritionist, and ATC is athletic trainer."},{"label":"CISSN","correct":false,"feedback":"CSSD. CSCS is strength and conditioning, CISSN is the ISSN sports nutritionist, and ATC is athletic trainer."},{"label":"ATC","correct":false,"feedback":"CSSD. CSCS is strength and conditioning, CISSN is the ISSN sports nutritionist, and ATC is athletic trainer."}]}},{"id":"sf1-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"An athlete moves from a high-volume training phase to a lighter phase. Should the nutrition plan stay identical?","text":"No. Nutrition periodization aligns eating with the phase’s intensity, volume, recovery demands and goals. Consistency in good habits does not require identical intake."}]}}],"flashcards":[{"front":"What is exercise physiology?","back":"The scientific study of the body’s responses and adaptations to movement."},{"front":"Physical activity vs exercise vs sport","back":"Any movement above rest; planned and structured; competitive."},{"front":"Progressive overload","back":"Gradually increasing the training stimulus."},{"front":"Macro-, meso-, microcycle","back":"The broad plan; a phase within it; a shorter recurring block."},{"front":"RDA","back":"Meets the needs of nearly all (97 to 98%) healthy people in a group."},{"front":"AI","back":"Used when evidence is too limited to set an RDA."},{"front":"EAR","back":"Meets the needs of about half a group."},{"front":"UL","back":"Highest daily intake unlikely to cause harm for almost all people. Not a target."},{"front":"Chapter 1 carbohydrate benchmark","back":"3 to 10 g/kg/day, sometimes up to 12 g/kg/day."},{"front":"Chapter 1 protein benchmark","back":"1.2 to 2.0 g/kg/day when energy intake is adequate."},{"front":"Chapter 1 fat benchmark","back":"20 to 35% of total calories."},{"front":"Five questions for an ergogenic aid","back":"Legality, ethics, purity, safety, effectiveness."},{"front":"Epidemiological study","back":"Examines patterns and associations in populations. Association is not causation."},{"front":"Double-blind","back":"Participants and relevant researchers are unaware of allocation."},{"front":"Scope of practice","back":"The professional boundaries defining what you are trained and permitted to do."}],"quiz":[{"q":"Which of the following is the best definition of exercise physiology?","o":["Art and science of training","Laboratory study of mental and physical fatigue","Scientific study of the body’s responses and adaptations to movement","Clinical observations of acute and chronic exercise"],"a":2,"e":"Exercise physiology studies the body’s responses and adaptations to movement."},{"q":"Which of the following is the best definition of sports nutrition?","o":["Ingestion, digestion, absorption, metabolism, and biochemistry of nutrients","Energy needed to train and perform","Science of eating and supplementation","Application of nutritional and physiological principles that support training and performance"],"a":3,"e":"Sports nutrition applies nutrition and physiology to training and performance."},{"q":"The term endurance athlete is generally interpreted to mean that the athlete:","o":["predominantly uses the oxygen-dependent energy system.","trains for many hours","only engages in moderate-intensity activity","does not lift weights as part of training."],"a":0,"e":"Endurance emphasizes oxygen-dependent energy production."},{"q":"The term macronutrients typically refers to:","o":["any nutrient that provides energy","the eight key nutrients needed for good health.","carbohydrates, proteins, and fats.","vitamins and minerals."],"a":2,"e":"The conventional macronutrient grouping here is carbohydrate, protein, and fat."},{"q":"The nutrition goals of each mesocycle are:","o":["always the same to ensure consistency.","a reflection of the intensity and volume of activity.","unplanned and very flexible.","based on each athlete’s aerobic capacity."],"a":1,"e":"Each phase’s intensity and volume inform its nutrition goals."},{"q":"Which of the following best describes the term Dietary Reference Intakes (DRI)?","o":["Minimum amount of nutrients needed by an individual each day","Maximum amount of nutrients that should not be exceeded each day","Current nutrient standard for individuals","Eight key nutrients needed for good health"],"a":2,"e":"DRI is the umbrella nutrient reference standard."},{"q":"The Tolerable Upper Intake Level (UL) helps people to answer which of the following questions regarding vitamins and \nminerals?","o":["Am I deficient?","Am I consuming enough?","Am I taking in too much?","Do I have the right balance between food and supplements?"],"a":2,"e":"UL addresses excessive intake, not an adequacy target."},{"q":"Which of the following best describes the application of the Dietary Reference Intakes (DRI) to trained athletes?","o":["The DRI are not applicable to athletes because they were developed for the general population.","Although they were developed for the general population, athletes can use the DRI to assess the adequacy of their diets.","Athletes should add 10% to DRI values to reflect the increased need for nutrients by trained athletes.","All of the DRI are applicable to both the general and athletic populations."],"a":1,"e":"Athletes can use the general standards as a foundation; no blanket percentage increase is prescribed."},{"q":"What does it mean when an active ingredient in a dietary supplement or over-the-counter medication is standardized?","o":["Strict quality control measures have been followed","Amount consumed needs to be adjusted based on body weight","The same amount is found in each pill or tablet","Only natural extracts are used"],"a":2,"e":"Standardized means a consistent active-ingredient amount, not guaranteed safety or purity."},{"q":"The weakest of all scientific findings are from which of the following types of studies?","o":["Case studies","Epidemiological studies","Correlational studies","Experimental studies"],"a":0,"e":"Case studies are the weakest listed basis for general recommendations."},{"q":"The term level of evidence refers to:","o":["the number of peers who reviewed a research study manuscript.","the number of epidemiological studies conducted on a topic.","the strength of the study with the largest number of subjects.","the relative strength of the collective body of research on a topic."],"a":3,"e":"Evidence strength reflects the collective research, not one study."},{"q":"Extrapolating research results is not recommended because:","o":["only the original population was directly tested.","causation is reduced to correlation.","consensus has not been reached.","it is a Grade I (Level A) conclusion."],"a":0,"e":"Only the original population was directly tested."},{"q":"Much health-related information on the Internet is:","o":["inaccurate","unreliable","scientific based and peer reviewed","A & B are correct"],"a":3,"e":"The chapter warns that online information can be inaccurate and unreliable."},{"q":"Sports nutrition is the integration of scientifically based nutrition and exercise physiology principles developed to support good \nhealth, training, performance, and recovery.","o":["True","False"],"a":0,"e":"This matches the chapter’s integrated definition."},{"q":"Strength athlete is a term that is used to describe an athlete that primarily depends on anaerobic energy systems.","o":["True","False"],"a":0,"e":"Strength efforts have an anaerobic emphasis."},{"q":"Nutrition periodization is the development of an eating plan over a short period of time (i.e. 1-10 days).","o":["True","False"],"a":1,"e":"Periodization aligns nutrition with training phases; short meal planning alone does not define it."},{"q":"Athletes should follow a rigid diet plan because this is the best way to ensure that both the art and science of nutrition are met.","o":["True","False"],"a":1,"e":"Individual application requires flexibility rather than a rigid diet."},{"q":"The Dietary Reference Intakes (DRI) and Recommended Dietary Allowances (RDA) are essentially the same and these terms can \nbe used interchangeably.","o":["True","False"],"a":1,"e":"RDA is one of the DRI reference values."},{"q":"Research studies should be replicated to validate the results.","o":["True","False"],"a":0,"e":"Replication tests reproducibility."},{"q":"Anecdotal evidence refers to data obtained from research studies with less than 10 subjects.","o":["True","False"],"a":1,"e":"Anecdotal evidence is personal accounts, not a sample-size category."},{"q":"A rich body of scientific data is a term used to describe information derived from well-designed, high-quality research studies \nwith many subjects.","o":["True","False"],"a":0,"e":"Suggested course interpretation: a rich evidence base includes high-quality, well-designed studies with substantial participant evidence. Size alone does not establish quality."},{"q":"Evidence-based sports nutrition recommendations are based primarily on observing the dietary intakes of successful athletes in \na given sport.","o":["True","False"],"a":1,"e":"Recommendations rely on cumulative scientific evidence, not primarily successful athletes’ habits."},{"q":"The strength of any scientific recommendation depends on the quality of the research conducted.","o":["True","False"],"a":0,"e":"Research quality affects confidence in recommendations."},{"q":"A scope of practice helps define professional boundaries.","o":["True","False"],"a":0,"e":"Scope of practice defines professional boundaries."},{"q":"Many consumers find nutrition and exercise information on the Internet and studies have shown that this information increases \nknowledge and results in a positive change in health status.","o":["True","False"],"a":1,"e":"Suggested course interpretation: access to online information alone does not establish improved health; the chapter highlights unreliable information."},{"q":"Scope-of-practice definitions help identify professional boundaries and protect consumers from inappropriately trained \npractitioners.","o":["True","False"],"a":0,"e":"Professional boundaries help protect clients."}]},{"n":2,"title":"Defining and Measuring Energy","kicker":"Trace energy from food to ATP, understand how skeletal muscle uses it, and learn how energy intake and expenditure are estimated.","steps":[{"id":"sf2-0","chapter":"Energy, work, and ATP","title":"Energy, work, and ATP","html":"<h3>Energy, work, and power</h3><p>Energy is the capacity to do work. Food energy is stored as chemical energy and can be converted into mechanical work, heat, and other biological processes. Power describes the rate at which work is performed, so two athletes may complete the same work but differ in power. The first law of thermodynamics explains that energy is transformed rather than created or destroyed; the second law explains why every conversion releases some energy as heat.</p><h3>ATP is the immediate energy currency</h3><p>Adenosine triphosphate links energy-releasing reactions to energy-requiring work. Breaking the terminal phosphate bond forms ADP and inorganic phosphate and releases usable energy. Stored ATP is very limited, so it must be continuously resynthesized through the creatine-phosphate system, glycolysis, and oxidative phosphorylation. Food does not directly power a muscle contraction; nutrients supply the pathways that rebuild ATP.</p>","visual":{"title":"Energy, work, and ATP","kind":"sequence","items":[{"label":"Calcium binds troponin","detail":"Calcium released in the muscle cell binds to troponin."},{"label":"Tropomyosin moves","detail":"Troponin shifts tropomyosin away from actin’s binding sites."},{"label":"Crossbridge forms","detail":"Myosin attaches to actin and forms a crossbridge."},{"label":"Power stroke","detail":"Myosin performs a power stroke that pulls actin and produces force."},{"label":"ATP allows detachment","detail":"ATP lets myosin detach so the muscle can relax or cycle again. Muscle stores only a small ATP supply, so it must be resynthesized continually."}]},"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Type of work</th><th>Example</th></tr></thead><tbody><tr><td>Chemical</td><td>Storing carbohydrate as glycogen</td></tr><tr><td>Electrical</td><td>Maintaining ion concentrations across membranes</td></tr><tr><td>Mechanical</td><td>Skeletal muscle producing force</td></tr><tr><td>Transportation</td><td>Blood delivering oxygen and nutrients</td></tr></tbody></table></div>","<p><b>Potential</b> energy is stored, like water behind a dam. <b>Kinetic</b> energy is released from storage to perform work. <b>Endergonic</b> reactions require and store energy. <b>Exergonic</b> reactions release it. Rephosphorylating ADP to ATP is endergonic, and ATP breakdown is exergonic.</p>","<h3>How ATP powers a contraction</h3>"]},{"id":"sf2-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Rephosphorylating ADP to ATP is:","options":[{"label":"Exergonic","correct":false,"feedback":"Joining a phosphate to ADP needs an energy input, so it is endergonic. ATP breakdown releases energy and is exergonic."},{"label":"Endergonic","correct":true,"feedback":"Joining a phosphate to ADP needs an energy input, so it is endergonic. ATP breakdown releases energy and is exergonic."},{"label":"Kinetic","correct":false,"feedback":"Joining a phosphate to ADP needs an energy input, so it is endergonic. ATP breakdown releases energy and is exergonic."},{"label":"A release of energy","correct":false,"feedback":"Joining a phosphate to ADP needs an energy input, so it is endergonic. ATP breakdown releases energy and is exergonic."}]}},{"id":"sf2-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The first law of thermodynamics states that:","options":[{"label":"Every conversion releases some heat","correct":false,"feedback":"The second law explains why conversions release heat. The first is about conservation."},{"label":"Energy is neither created nor destroyed in a closed system, it changes form","correct":true,"feedback":"The second law explains why conversions release heat. The first is about conservation."},{"label":"Energy always flows toward heat","correct":false,"feedback":"The second law explains why conversions release heat. The first is about conservation."},{"label":"Work is always 100% efficient","correct":false,"feedback":"The second law explains why conversions release heat. The first is about conservation."}]}},{"id":"sf2-1","chapter":"Units and measuring energy","title":"Units and measuring energy","html":"<h3>Calories, kilocalories, and kilojoules</h3><p>In nutrition, one Calorie with a capital C is one kilocalorie, the energy needed to raise one kilogram of water by one degree Celsius. One kilocalorie equals about 4.184 kilojoules. Carbohydrate and protein provide about 4 kcal per gram, fat about 9 kcal per gram, and alcohol about 7 kcal per gram. These are physiological estimates rather than proof that every consumed calorie is absorbed and used identically.</p><h3>Measuring energy expenditure</h3><p>Direct calorimetry measures heat released by the body but is expensive and impractical for most sport settings. Indirect calorimetry estimates energy expenditure from oxygen consumption and carbon-dioxide production. The respiratory exchange ratio helps estimate the mix of carbohydrate and fat being oxidized: values near 0.70 indicate mostly fat and values near 1.00 indicate mostly carbohydrate, although non-steady-state exercise complicates interpretation.</p>","visual":null,"blocksHtml":["<div class=\"mn-html\"><span>Remember it</span><b>4, 9, 4, 7.</b> Carbohydrate and protein tie at 4. Fat is more than double either, at 9. Alcohol sits in between at 7, closer to fat than to the other two, which is exactly why alcohol calories add up fast without registering as “food.”</div>","<div class=\"tbl\"><table><thead><tr><th>Nutrient</th><th>Bomb calorimeter (kcal/g)</th><th>Human (kcal/g)</th></tr></thead><tbody><tr><td>Carbohydrate</td><td>4.2</td><td>4.2</td></tr><tr><td>Fat</td><td>9.4</td><td>9.4</td></tr><tr><td>Protein</td><td>5.7</td><td>4.2</td></tr><tr><td>Alcohol</td><td>7.0</td><td>7.0 under normal circumstances</td></tr></tbody></table></div>"]},{"id":"sf2-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Indirect calorimetry estimates energy expenditure from:","options":[{"label":"Heat released by the body","correct":false,"feedback":"Direct calorimetry measures heat. Indirect calorimetry uses gas exchange, with about 5 kcal per litre of oxygen."},{"label":"Oxygen consumption and carbon dioxide production","correct":true,"feedback":"Direct calorimetry measures heat. Indirect calorimetry uses gas exchange, with about 5 kcal per litre of oxygen."},{"label":"Body temperature","correct":false,"feedback":"Direct calorimetry measures heat. Indirect calorimetry uses gas exchange, with about 5 kcal per litre of oxygen."},{"label":"Food records","correct":false,"feedback":"Direct calorimetry measures heat. Indirect calorimetry uses gas exchange, with about 5 kcal per litre of oxygen."}]}},{"id":"sf2-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Why does protein give 5.7 kcal/g in a bomb calorimeter but 4.2 kcal/g in the human?","options":[{"label":"The human digests it more slowly","correct":false,"feedback":"Nitrogen is excreted (mainly as urea) rather than burned, so the body captures less energy from protein."},{"label":"The body cannot fully oxidize protein, so nitrogen leaves as waste","correct":true,"feedback":"Nitrogen is excreted (mainly as urea) rather than burned, so the body captures less energy from protein."},{"label":"The calorimeter adds heat","correct":false,"feedback":"Nitrogen is excreted (mainly as urea) rather than burned, so the body captures less energy from protein."},{"label":"Protein is not absorbed at all","correct":false,"feedback":"Nitrogen is excreted (mainly as urea) rather than burned, so the body captures less energy from protein."}]}},{"id":"sf2-2","chapter":"Daily energy expenditure","title":"Daily energy expenditure","html":"<h3>Components of daily energy expenditure</h3><p>Basal or resting metabolism supports essential functions and is usually the largest component. The thermic effect of food reflects digestion, absorption, and processing. Physical activity includes planned exercise and non-exercise movement. Growth, tissue repair, temperature, illness, pregnancy, and training adaptation can also influence needs. Body size and fat-free mass are major determinants of resting expenditure.</p>","visual":null,"blocksHtml":["<h3>The four pieces of TDEE</h3>","<dl class=\"facts\"><div><dt>Resting/basal metabolism</dt><dd>Energy for essential functions at rest: circulation, breathing, cell maintenance, organ function. Usually the largest single share.</dd></div><div><dt>Thermic effect of food (TEF)</dt><dd>Energy spent digesting, absorbing and processing what you eat. Protein has the highest TEF of the three macronutrients, which is one reason higher-protein diets can modestly raise total expenditure.</dd></div><div><dt>Exercise activity thermogenesis (EAT)</dt><dd>Energy from planned training. The most variable piece across people, and the piece a nutritionist can quantify most directly from a training log.</dd></div><div><dt>Non-exercise activity thermogenesis (NEAT)</dt><dd>Fidgeting, posture, walking, and all movement outside planned exercise. It can vary by hundreds of kcal/day between individuals and tends to fall first when someone diets or feels fatigued, which quietly undercuts a calorie deficit.</dd></div></dl>","<div class=\"mn-html\"><span>Remember it</span><b>Think of it as rent.</b> Resting metabolism is the rent you pay no matter what (the biggest, fixed bill). TEF is the small service fee for every meal. EAT is the planned trip you chose to take. NEAT is all the little errands you run without thinking about them, small individually, but they add up over a month.</div>","<div class=\"tbl\"><table><thead><tr><th>Measure</th><th>Conditions</th></tr></thead><tbody><tr><td>BMR</td><td>Strict: morning, fasting, complete rest</td></tr><tr><td>RMR</td><td>Less strict; about 10% higher than BMR in this chapter</td></tr></tbody></table></div>","<dl class=\"facts\"><div><dt>Genetics</dt><dd>Sets part of the baseline rate.</dd></div><div><dt>Body size and fat-free mass</dt><dd>Major determinants of resting expenditure.</dd></div><div><dt>Age and thyroid hormones</dt><dd>Shift metabolic rate.</dd></div><div><dt>Restricted intake</dt><dd>Lowers metabolic rate.</dd></div><div><dt>Environment</dt><dd>Temperature, altitude and caffeine can change it.</dd></div></dl>","<div class=\"callout\"><b class=\"k\">Why this matters in practice.</b> A client who plateaus on a diet has often lost weight partly through falling NEAT and a modestly reduced RMR (adaptive thermogenesis), not through poor adherence alone. Reviewing daily movement, not just training sessions, is often the more useful lever.</div>"]},{"id":"sf2-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"For a sedentary person, resting metabolism is roughly what share of daily expenditure?","options":[{"label":"10%","correct":false,"feedback":"The slides approximate 70% resting metabolism, 10% thermic effect of food and 20% activity."},{"label":"20%","correct":false,"feedback":"The slides approximate 70% resting metabolism, 10% thermic effect of food and 20% activity."},{"label":"50%","correct":false,"feedback":"The slides approximate 70% resting metabolism, 10% thermic effect of food and 20% activity."},{"label":"70%","correct":true,"feedback":"The slides approximate 70% resting metabolism, 10% thermic effect of food and 20% activity."}]}},{"id":"sf2-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Compared with BMR, RMR is:","options":[{"label":"About 10% lower","correct":false,"feedback":"RMR is measured under less strict conditions and comes out about 10% higher in this chapter."},{"label":"About 10% higher","correct":true,"feedback":"RMR is measured under less strict conditions and comes out about 10% higher in this chapter."},{"label":"Identical","correct":false,"feedback":"RMR is measured under less strict conditions and comes out about 10% higher in this chapter."},{"label":"About 50% higher","correct":false,"feedback":"RMR is measured under less strict conditions and comes out about 10% higher in this chapter."}]}},{"id":"sf2-3","chapter":"Estimating requirements","title":"Estimating requirements","html":"<h3>Estimating requirements in practice</h3><p>Equations, activity factors, food records, and wearable devices all contain error. Start with an estimate, then monitor performance, recovery, hunger, mood, menstrual function, injuries, sleep, and weight trends. Adjust gradually. Large unexplained changes, persistent fatigue, or suspected low energy availability deserve assessment and, when indicated, medical referral.</p>","visual":{"title":"Estimating requirements","kind":"sequence","items":[{"label":"Estimate a baseline","detail":"Use an equation such as Mifflin–St Jeor or Cunningham to get a starting RMR, choosing the one that fits the information you have (Cunningham needs a measured or estimated fat-free mass, which suits leaner or more muscular athletes better)."},{"label":"Apply an activity factor or add training energy","detail":"Either multiply RMR by an activity factor, or add estimated exercise energy expenditure on top of RMR and NEAT separately. The second approach is usually more accurate for athletes with variable training loads."},{"label":"Treat the result as a starting point","detail":"Give the client a number to start from, not a verdict."},{"label":"Monitor and adjust","detail":"Track weight trend, performance, hunger, sleep and, where relevant, menstrual function over two to four weeks, then adjust the target based on what actually happened rather than defending the original estimate."}]},"blocksHtml":["<h3>A practical sequence, not a single number</h3>","<div class=\"tbl\"><table><thead><tr><th>Activity</th><th>Female kcal/kg/day</th><th>Male kcal/kg/day</th></tr></thead><tbody><tr><td>Sedentary</td><td>30</td><td>31</td></tr><tr><td>Light</td><td>35</td><td>38</td></tr><tr><td>Moderate</td><td>37</td><td>41</td></tr><tr><td>Heavy</td><td>44</td><td>50</td></tr><tr><td>Exceptional</td><td>51</td><td>58</td></tr></tbody></table></div>"]},{"id":"sf2-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"In the Mifflin–St Jeor equation, which constant is used for women?","options":[{"label":"+5","correct":false,"feedback":"Men add 5 and women subtract 161."},{"label":"−161","correct":true,"feedback":"Men add 5 and women subtract 161."},{"label":"+161","correct":false,"feedback":"Men add 5 and women subtract 161."},{"label":"−5","correct":false,"feedback":"Men add 5 and women subtract 161."}]}},{"id":"sf2-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Food records typically:","options":[{"label":"Overestimate intake by about 15%","correct":false,"feedback":"Estimates carry error, so start with a number and then monitor performance, recovery and weight trends."},{"label":"Are highly accurate","correct":false,"feedback":"Estimates carry error, so start with a number and then monitor performance, recovery and weight trends."},{"label":"Underestimate intake, by 12 to 16% or more","correct":true,"feedback":"Estimates carry error, so start with a number and then monitor performance, recovery and weight trends."},{"label":"Match wearable devices exactly","correct":false,"feedback":"Estimates carry error, so start with a number and then monitor performance, recovery and weight trends."}]}},{"id":"sf2-4","chapter":"Energy balance and availability","title":"Energy balance and availability","html":"<h3>Energy balance and availability</h3><p>Energy balance compares intake with total expenditure over time. A persistent positive balance supports tissue gain; a persistent negative balance supports loss. Energy availability asks how much dietary energy remains for normal physiology after exercise expenditure. An athlete can maintain a stable scale weight while under-fuelling because the body reduces reproductive, skeletal, immune, and metabolic functions.</p>","visual":null,"blocksHtml":["<h3>Two related but different ideas</h3>","<div class=\"tabblk\"><b>Energy balance</b><p>Intake compared with total expenditure. Positive balance over time supports weight gain, negative balance supports weight loss, and the scale is the usual way people track it.</p></div><div class=\"tabblk\"><b>Energy availability</b><p>Dietary energy left for normal body functions once exercise energy expenditure is subtracted, scaled to fat-free mass: EA = (energy intake − exercise energy expenditure) ÷ fat-free mass. It is possible to sit in energy balance (stable weight) while availability is low, because the body can quietly downshift reproductive, bone, immune and metabolic function to cope.</p></div>","<div class=\"callout\"><b>Efficiency example from the slides.</b> A 68.2 kg cyclist at 180 W does external work of 2.574 kcal/min while using 11.08 kcal/min of oxygen above rest: 2.574 ÷ 11.08 × 100 = 23.2%. Much of the rest becomes heat.</div>"]},{"id":"sf2-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"An athlete can hold a steady scale weight while under-fuelling because:","options":[{"label":"The scale is inaccurate","correct":false,"feedback":"Low energy availability can hide behind a stable weight."},{"label":"The body reduces reproductive, skeletal, immune and metabolic functions to save energy","correct":true,"feedback":"Low energy availability can hide behind a stable weight."},{"label":"Muscle mass always rises","correct":false,"feedback":"Low energy availability can hide behind a stable weight."},{"label":"Water weight hides everything","correct":false,"feedback":"Low energy availability can hide behind a stable weight."}]}},{"id":"sf2-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Energy availability is:","options":[{"label":"Energy intake divided by body weight","correct":false,"feedback":"It is what remains for normal body functions once exercise costs are subtracted."},{"label":"Dietary energy left for normal physiology after exercise expenditure","correct":true,"feedback":"It is what remains for normal body functions once exercise costs are subtracted."},{"label":"Total daily expenditure","correct":false,"feedback":"It is what remains for normal body functions once exercise costs are subtracted."},{"label":"Resting metabolic rate","correct":false,"feedback":"It is what remains for normal body functions once exercise costs are subtracted."}]}},{"id":"sf2-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A 68.2 kg cyclist holds 180 W. Work output is 2.574 kcal/min and oxygen use above rest represents 11.08 kcal/min. What is the efficiency?","text":"2.574 ÷ 11.08 × 100 = 23.2%. The remaining energy is released as heat."}]}}],"flashcards":[{"front":"Bioenergetics","back":"The conversion of food into biologically useful energy."},{"front":"First law of thermodynamics","back":"Energy is neither created nor destroyed in a closed system. It changes form."},{"front":"Endergonic vs exergonic","back":"Endergonic needs and stores energy. Exergonic releases energy."},{"front":"ATP breakdown","back":"Exergonic. ATP → ADP + Pi + energy."},{"front":"1 kcal in kJ","back":"4.184 kJ (1,000 calories)."},{"front":"kcal per gram: carbohydrate, protein, fat, alcohol","back":"About 4, 4, 9 and 7."},{"front":"Direct vs indirect calorimetry","back":"Heat measured directly; energy inferred from oxygen use and CO₂ output."},{"front":"Energy per litre of oxygen","back":"About 5 kcal."},{"front":"Sedentary expenditure split","back":"About 70% RMR, 10% thermic effect of food, 20% activity."},{"front":"BMR vs RMR","back":"BMR is strict. RMR is less strict and about 10% higher."},{"front":"Mifflin–St Jeor constants","back":"+5 for men, −161 for women."},{"front":"Cunningham equation","back":"RMR = 500 + 22 × fat-free mass (kg)."},{"front":"Energy availability","back":"Dietary energy remaining for normal physiology after exercise expenditure."},{"front":"Food record error","back":"Underestimation of about 12 to 16%, sometimes 20%."}],"quiz":[{"q":"The best definition of bioenergetics is:","o":["the study of metabolism.","the physiological processes associated with exercise.","the process of converting food into biological energy.","the transformation of energy to heat."],"a":2,"e":"Bioenergetics converts food into biologically useful energy."},{"q":"The best definition of energy is the:","o":["absence of physical or mental fatigue.","ability to perform work.","generation of tension by contracting muscle.","thermic effect of movement."],"a":1,"e":"Energy is the ability to perform work."},{"q":"Which of the following is true regarding the First Law of Thermodynamics?","o":["Energy is not created or destroyed.","Energy is created but not destroyed.","Energy is destroyed but not created.","Energy is both created and destroyed."],"a":0,"e":"The first law states that energy is neither created nor destroyed, only transformed."},{"q":"Kinetic energy refers to:","o":["energy that is stored to be used later.","energy used for skeletal muscle contraction.","the release of stored energy to perform work.","all of the above"],"a":2,"e":"Kinetic energy is released from storage to perform work."},{"q":"ATP is an example of:","o":["chemical energy.","electrical energy.","mechanical energy.","thermal energy."],"a":0,"e":"ATP stores chemical energy."},{"q":"Which of the following is a type of chemical reaction that results in energy being absorbed or stored?","o":["Endergonic","Exergonic","Enderthermic","Excitation"],"a":0,"e":"Endergonic reactions require and store energy."},{"q":"Which of the following is a type of chemical reaction that results in energy being released?","o":["Endergonic","Exergonic","Enderthermic","Excitation"],"a":1,"e":"Exergonic reactions release energy."},{"q":"Which of the following is an endergonic reaction?","o":["The releasing (triggering) of a mouse trap","The release of water from behind a dam","The breakdown of ATP to ADP","The rephosphorylation of ADP"],"a":3,"e":"Rephosphorylating ADP requires an energy input."},{"q":"The two most common factors that influence enzyme activity are:","o":["time and temperature.","temperature and pH.","pH and oxygen availability.","oxygen availability and time."],"a":1,"e":"Temperature and pH commonly affect enzyme activity."},{"q":"Under the most demanding conditions (e.g., very high-intensity exercise), ATP concentrations in skeletal muscles are not likely to drop more than:","o":["5-10%.","10-20%.","20-30%.","40-50%."],"a":2,"e":"The course describes ATP concentration as unlikely to fall by more than 20–30%."},{"q":"If a food contains 350 Calories, how many kilocalories does it contain?","o":["148","350","1,480","3,250"],"a":1,"e":"A food Calorie is one kilocalorie."},{"q":"The International System of Units (SI units) unit for energy is the:","o":["calorie (lowercase c).","Calorie (uppercase c).","kilocalorie.","joule."],"a":3,"e":"The SI unit of energy is the joule."},{"q":"6,300 kJ is equivalent to how many kilocalories?","o":["812","1,500","2,625","6,300"],"a":1,"e":"6,300 ÷ 4.184 is about 1,506 kcal, closest to 1,500."},{"q":"On a kcal/g basis, the caloric content of carbohydrate is approximately the same as that of:","o":["alcohol.","fat.","protein.","a and c"],"a":2,"e":"The chapter’s human-calorimeter values list carbohydrate and protein at about 4.2 kcal/g."},{"q":"On average, 1 liter of oxygen consumed is equivalent to _____ kcal of energy expended.","o":["1","3","5","7"],"a":2,"e":"The chapter uses about 5 kcal per litre of oxygen."},{"q":"Which of the following macronutrients has the greatest influence on the thermic effect of food?","o":["Carbohydrate","Protein","Fat"],"a":1,"e":"Protein produces the greatest thermic effect of the macronutrients."},{"q":"The “energy out” factor that that can be increased to the greatest degree is:","o":["resting metabolism.","thermic effect of food.","physical activity."],"a":2,"e":"Physical activity is the most variable and most readily increased component."},{"q":"One MET is equal to:","o":["energy expenditure at rest.","energy expenditure during the first 10 minutes of exercise.","energy expenditure prior to the point of fatigue.","55 kcal/hour."],"a":0,"e":"One MET represents resting energy expenditure."},{"q":"To maintain energy balance, it is estimated that a sedentary individual requires approximately _____ kcal/kg of body weight daily.","o":["20","25","30","35"],"a":2,"e":"The chapter’s sedentary estimate begins around 30 kcal/kg/day."},{"q":"If an athlete’s estimated energy need is above 50 kcal/kg of body weight daily, then this athlete is likely engaging in activity described as:","o":["normal.","moderate.","heavy.","exceptional."],"a":3,"e":"Above 50 kcal/kg/day corresponds to exceptional activity in the table."},{"q":"The terms calorie and Calorie can be used interchangeably in scientific writing.","o":["True","False"],"a":1,"e":"Lowercase calorie and food Calorie differ by a factor of 1,000 in scientific writing."},{"q":"The law of Conservation of Energy states that energy is neither created nor destroyed but that it can be transformed.","o":["True","False"],"a":0,"e":"This restates conservation of energy."},{"q":"One liter (1 L) of oxygen is equal to 9 kcal/g.","o":["True","False"],"a":1,"e":"One litre of oxygen is approximately 5 kcal, not 9 kcal/g."},{"q":"When compared to machines, humans are relatively efficient at converting energy.","o":["True","False"],"a":1,"e":"The cycling example shows only about 23% efficiency."},{"q":"Reactions in which energy is released are referred to as endergonic reactions.","o":["True","False"],"a":1,"e":"Energy-releasing reactions are exergonic."},{"q":"ATP is critical for muscle contraction, but is not involved in muscle relaxation.","o":["True","False"],"a":1,"e":"ATP also supports detachment, ion pumping, and relaxation."},{"q":"In the excitation-contraction process of generating tension or force in skeletal muscle, ATP is needed only for the \"power stroke\" part of the process.","o":["True","False"],"a":1,"e":"ATP is required at more than the power-stroke moment."},{"q":"ATP is the known as the energy currency because it is the primary source of energy in the body.","o":["True","False"],"a":0,"e":"The course identifies ATP as the body’s immediate energy currency."},{"q":"ATP is the direct source of energy for the body to perform work. The energy contained in food must be biochemically transformed to ATP.","o":["True","False"],"a":0,"e":"Food energy must be transformed into ATP before work occurs."},{"q":"The majority of ATP stored in skeletal muscle cannot be used for force production, even during very high intensity exercise.","o":["True","False"],"a":1,"e":"Stored ATP can support force production, although the supply is small and continually resynthesized."}]},{"n":3,"title":"Energy Systems and Exercise","kicker":"Muscle spends ATP faster than it can store it. Three systems rebuild it, and all three are running at all times. Pick an effort and see which one turns up.","steps":[{"id":"sf3-0","chapter":"ATP and the three energy systems","title":"ATP and the three energy systems","html":"<h3>The three ATP-producing systems</h3><p>The phosphagen system uses stored ATP and creatine phosphate to supply very rapid energy for a few seconds. Anaerobic glycolysis breaks glucose or glycogen into pyruvate and can rapidly form ATP; when oxidation cannot keep pace, lactate production helps regenerate NAD+ so glycolysis can continue. Oxidative metabolism in mitochondria uses carbohydrate, fat, and sometimes amino acids to produce much more ATP, but at a slower rate.</p><h3>Systems overlap rather than switch</h3><p>All three systems contribute from the start of exercise. Their relative contribution changes with intensity, duration, training status, oxygen delivery, and fuel availability. A maximal jump relies heavily on phosphagen energy; a hard one-minute effort relies strongly on glycolysis; a long steady session relies mainly on oxidative metabolism. Team sports repeatedly move among these demands.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Spend ATP</b><p class=\"eq\">ATP &rarr; ADP + P<sub>i</sub> + energy</p><p><b>Hydrolysis.</b> The enzyme ATPase (myosin ATPase in muscle) splits off a phosphate. The reaction is <b>exergonic</b>: it releases the energy the muscle uses to make force.</p></div><div class=\"tabblk\"><b>Rebuild ATP</b><p class=\"eq\">ADP + P<sub>i</sub> + energy &rarr; ATP</p><p><b>Rephosphorylation.</b> A phosphate is joined back onto ADP. The reaction is <b>endergonic</b>: it needs energy in, which is then stored in the new phosphate bond. Supplying that energy is the job of the three energy systems.</p></div>","<h3>The three systems side by side</h3>","<div class=\"tbl\"><table><thead><tr><th>System</th><th>Speed of action</th><th>ATP replenished</th><th>Duration</th></tr></thead><tbody><tr><td><span class=\"tag crp\">Creatine phosphate</span></td><td>Very fast</td><td>Very small</td><td>Very short</td></tr><tr><td><span class=\"tag gly\">Anaerobic glycolysis</span></td><td>Fast</td><td>Small</td><td>Short</td></tr><tr><td><span class=\"tag oxy\">Oxidative phosphorylation</span></td><td>Very slow</td><td>Large</td><td>Very long</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>“Please Give Oxygen.”</b> That’s the order they take over as effort continues: <b>P</b>hosphagen (creatine phosphate) first, then <b>G</b>lycolysis, then <b>O</b>xidative phosphorylation. It also happens to be the order from fastest-and-smallest to slowest-and-biggest.</div>","<div class=\"callout\"><b class=\"k\">Dimmer switches, not on/off switches.</b> Every system is on all the time. During a given activity one is turned up and the others sit lower. Scroll to the top and try the effort chips again.</div>"]},{"id":"sf3-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The reaction ATP → ADP + P<sub>i</sub> + energy is best described as:","options":[{"label":"The rephosphorylation of ATP","correct":false,"feedback":"ATP is split, releasing energy, so it is hydrolysis and it is exergonic."},{"label":"An endergonic reaction","correct":false,"feedback":"ATP is split, releasing energy, so it is hydrolysis and it is exergonic."},{"label":"The hydrolysis of ATP","correct":true,"feedback":"ATP is split, releasing energy, so it is hydrolysis and it is exergonic."},{"label":"The rephosphorylation of creatine","correct":false,"feedback":"ATP is split, releasing energy, so it is hydrolysis and it is exergonic."}]}},{"id":"sf3-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Select the incorrect statement about the energy systems.","options":[{"label":"All three systems are working at the same time.","correct":false,"feedback":"The dimmer switch picture is the accurate one. All systems are on, and one is turned up."},{"label":"The systems operate one at a time: when one is on, the others are off.","correct":true,"feedback":"The dimmer switch picture is the accurate one. All systems are on, and one is turned up."},{"label":"One system may be predominant during a given activity.","correct":false,"feedback":"The dimmer switch picture is the accurate one. All systems are on, and one is turned up."}]}},{"id":"sf3-1","chapter":"The creatine phosphate system","title":"The creatine phosphate system","html":"<h3>Key facts</h3><h3>Watching CrP get used</h3><p>Well-trained sprinters had muscle sampled before and immediately after sprints of different lengths. Look at which store drops furthest.</p><p><span class=\"cap\">Values are approximate readings from Figure 3.7, in millimoles per kilogram of muscle.</span></p><div class=\"callout\">ATP fell by roughly 30% while CrP fell by roughly 70%. CrP is spent so that ATP does not have to fall further.</div><h3>Recovering CrP: the creatine shuttle</h3>","visual":{"title":"The creatine phosphate system","kind":"sequence","items":[{"label":"Muscle spends ATP","detail":"A contraction splits ATP into ADP and P<sub>i</sub>, releasing energy for force."},{"label":"ATP runs low, ADP builds up","detail":"The ATP store is small. In an all-out effort it would run out almost immediately without a very fast refill."},{"label":"CrP donates its phosphate","detail":"The enzyme creatine kinase (CK) moves the phosphate from CrP onto ADP: CrP + ADP &rarr; ATP + creatine."},{"label":"ATP is back in one step","detail":"Each CrP gives one ATP. No oxygen is needed and the reaction is very fast, which is why this system leads in power events."},{"label":"CrP depletion ends the run","detail":"The system carries about 5 to 10 seconds of maximal effort. Fatigue here is associated with CrP running out."}]},"blocksHtml":[]},{"id":"sf3-1-x0","title":"Explore: The creatine phosphate system","teach":[],"act":{"type":"explore","prompt":"Open each question.","panels":[{"label":"Where does creatine come from?","text":"Creatine comes from the diet (meat and fish) and is also made by the liver and other tissues. Without supplements, about 2 g per day is taken in or made. In muscle, about two-thirds is held as creatine phosphate and about one-third stays as free creatine. About 2 g per day leaves in the urine as creatinine."}]}},{"id":"sf3-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which best describes the creatine phosphate system?","options":[{"label":"It powers muscle contraction directly, the way ATP does","correct":false,"feedback":"Breaking the CrP phosphate bond releases energy that phosphorylates ADP to ATP. Contraction itself is still powered by ATP."},{"label":"It is another name for anaerobic glycolysis","correct":false,"feedback":"Breaking the CrP phosphate bond releases energy that phosphorylates ADP to ATP. Contraction itself is still powered by ATP."},{"label":"It releases stored phosphate energy to turn ADP back into ATP","correct":true,"feedback":"Breaking the CrP phosphate bond releases energy that phosphorylates ADP to ATP. Contraction itself is still powered by ATP."},{"label":"It needs oxygen to make its ATP","correct":false,"feedback":"Breaking the CrP phosphate bond releases energy that phosphorylates ADP to ATP. Contraction itself is still powered by ATP."}]}},{"id":"sf3-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"True or false: the creatine phosphate system is completely anaerobic.","options":[{"label":"True","correct":false,"feedback":"Using CrP is anaerobic, but rebuilding CrP through the creatine shuttle depends on aerobic metabolism in the mitochondria."},{"label":"False","correct":true,"feedback":"Using CrP is anaerobic, but rebuilding CrP through the creatine shuttle depends on aerobic metabolism in the mitochondria."}]}},{"id":"sf3-1-q2","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Over a 100 m sprint, muscle ATP fell about 30% and CrP about 70%. What does this show?","options":[{"label":"CrP was used up first so that ATP could be held up","correct":true,"feedback":"CrP rephosphorylates ADP, so its store takes the biggest hit while ATP is defended."},{"label":"ATP was used while CrP stayed untouched","correct":false,"feedback":"CrP rephosphorylates ADP, so its store takes the biggest hit while ATP is defended."},{"label":"Glycolysis alone protected ATP","correct":false,"feedback":"CrP rephosphorylates ADP, so its store takes the biggest hit while ATP is defended."},{"label":"Creatine was excreted during the sprint","correct":false,"feedback":"CrP rephosphorylates ADP, so its store takes the biggest hit while ATP is defended."}]}},{"id":"sf3-2","chapter":"Anaerobic glycolysis and the fate of lactate","title":"Anaerobic glycolysis and the fate of lactate","html":"<h3>Glycolysis and lactate</h3><p>Glycolysis occurs in the cytosol and can begin with blood glucose or muscle glycogen. Glycogen yields a small energetic advantage because it enters after the first phosphorylation step. Lactate is not simply metabolic waste: it can be transported, oxidized by other tissues, or converted back to glucose in the liver. Fatigue during intense exercise reflects several interacting changes, not lactate alone.</p>","visual":{"title":"Anaerobic glycolysis and the fate of lactate","kind":"sequence","items":[{"label":"Glycolysis makes pyruvate","detail":"Glycolysis ends at pyruvate. Pyruvate and lactate convert back and forth, so it is a two-way reaction."},{"label":"Lactate leaves the muscle","detail":"When lactate builds up it moves out of the muscle into the venous blood and is distributed through the arteries."},{"label":"Aerobic tissues take it up","detail":"Heart, liver and kidney remove lactate from the blood, convert it to pyruvate, and take it into their mitochondria. There it is metabolized aerobically."},{"label":"Or the liver rebuilds glucose","detail":"In the liver, lactate can also be converted back to glucose through the Cori cycle."}]},"blocksHtml":["<h3>The ATP arithmetic</h3>","<div class=\"tabblk\"><b>Start from glucose</b><div class=\"glc\"><div><strong>2</strong><span>ATP invested to get started</span></div><div><strong>4</strong><span>ATP produced in total</span></div><div><strong>2</strong><span>Net ATP gained</span></div></div><p class=\"small\" style=\"margin-top:12px\">Starting from blood glucose: 4 produced minus 2 invested leaves a net of 2.</p></div><div class=\"tabblk\"><b>Start from glycogen</b><div class=\"glc\"><div><strong>1</strong><span>ATP invested to get started</span></div><div><strong>4</strong><span>ATP produced in total</span></div><div><strong>3</strong><span>Net ATP gained</span></div></div><p class=\"small\" style=\"margin-top:12px\">Starting from stored glycogen (glycogenolysis): 4 produced minus 1 invested leaves a net of 3.</p></div>","<div class=\"callout\">The rate-limiting enzyme of glycolysis is <b>phosphofructokinase (PFK)</b>. Glycogen is the more energy-efficient starting point because it costs one ATP to get going instead of two.</div>","<h3>What happens to lactate</h3>","<div class=\"callout\"><b class=\"k\">Lactate is not a waste product.</b> The pyruvate to lactate reaction runs in both directions, and lactate is a fuel that other tissues collect and burn.</div>"]},{"id":"sf3-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"How many net ATP does glycolysis yield from one glucose, and from one glycogen unit?","options":[{"label":"4 from glucose, 3 from glycogen","correct":false,"feedback":"Glucose costs 2 ATP to start and 4 are made, so net 2. Glycogen costs 1, so net 3."},{"label":"2 from glucose, 3 from glycogen","correct":true,"feedback":"Glucose costs 2 ATP to start and 4 are made, so net 2. Glycogen costs 1, so net 3."},{"label":"2 from both","correct":false,"feedback":"Glucose costs 2 ATP to start and 4 are made, so net 2. Glycogen costs 1, so net 3."},{"label":"3 from glucose, 2 from glycogen","correct":false,"feedback":"Glucose costs 2 ATP to start and 4 are made, so net 2. Glycogen costs 1, so net 3."}]}},{"id":"sf3-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which statement about lactate is correct?","options":[{"label":"It is a waste product that can only be excreted","correct":false,"feedback":"Pyruvate and lactate interconvert. Aerobic tissues take lactate up, convert it to pyruvate and burn it in their mitochondria."},{"label":"It forms only when no oxygen is present at all","correct":false,"feedback":"Pyruvate and lactate interconvert. Aerobic tissues take lactate up, convert it to pyruvate and burn it in their mitochondria."},{"label":"It can never leave the muscle","correct":false,"feedback":"Pyruvate and lactate interconvert. Aerobic tissues take lactate up, convert it to pyruvate and burn it in their mitochondria."},{"label":"It can be converted back to pyruvate and used aerobically","correct":true,"feedback":"Pyruvate and lactate interconvert. Aerobic tissues take lactate up, convert it to pyruvate and burn it in their mitochondria."}]}},{"id":"sf3-2-q2","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which enzyme is the rate-limiting enzyme of glycolysis?","options":[{"label":"Creatine kinase","correct":false,"feedback":"PFK sets the pace of glycolysis. Creatine kinase belongs to the CrP system."},{"label":"Myosin ATPase","correct":false,"feedback":"PFK sets the pace of glycolysis. Creatine kinase belongs to the CrP system."},{"label":"Phosphofructokinase (PFK)","correct":true,"feedback":"PFK sets the pace of glycolysis. Creatine kinase belongs to the CrP system."},{"label":"Cytochrome oxidase","correct":false,"feedback":"PFK sets the pace of glycolysis. Creatine kinase belongs to the CrP system."}]}},{"id":"sf3-3","chapter":"The oxidative phosphorylation system","title":"The oxidative phosphorylation system","html":"<h3>Mitochondrial oxidation</h3><p>Pyruvate can become acetyl-CoA and enter the Krebs cycle. Fatty acids undergo beta-oxidation to form acetyl-CoA. The Krebs cycle transfers high-energy electrons to NADH and FADH2, and the electron transport chain uses those electrons and oxygen to drive ATP synthesis. Oxygen is the final electron acceptor, which is why sustained oxidative ATP production depends on adequate oxygen delivery.</p>","visual":{"title":"The oxidative phosphorylation system","kind":"sequence","items":[{"label":"Glycolysis","detail":"One glucose is split into two pyruvate, with a net gain of 2 ATP. NADH is also produced."},{"label":"Pyruvate becomes acetyl CoA","detail":"Pyruvate is taken into the mitochondria and converted to acetyl CoA. CO<sub>2</sub> is released and NAD picks up electrons."},{"label":"Krebs cycle","detail":"Acetyl CoA is oxidized around the cycle. Its main job is to strip electrons onto NAD and FAD for the next stage. CO<sub>2</sub> is released and 2 ATP are made directly."},{"label":"Electron transport chain","detail":"Electrons pass along the chain and the energy released rebuilds ATP from ADP. This stage makes most of the ATP."},{"label":"Oxygen accepts the electrons","detail":"Oxygen is the final electron acceptor and forms water. Without oxygen the chain backs up, which is why this system is called aerobic."}]},"blocksHtml":["<dl class=\"facts\"><div><dt>124 steps</dt><dd>30 compounds and 27 enzymes are involved.</dd></div><div><dt>PFK, IDH, COX</dt><dd>The rate-limiting enzymes.</dd></div><div><dt>Slow, near-limitless</dt><dd>Aerobic, so it can keep going as long as fuel lasts.</dd></div><div><dt>Fuel depletion</dt><dd>Fatigue is linked to running low on fuel, such as muscle glycogen.</dd></div><div><dt>Endurance</dt><dd>Predominant system in events like long-distance running.</dd></div></dl>","<h3>Three fuels, one pathway</h3>","<div class=\"callout\"><b class=\"k\">Oxidation and reduction.</b> When pyruvate becomes acetyl CoA, it gives up electrons and is oxidized, while NAD picks them up and is reduced to NADH. The Krebs cycle repeats this trade so the electron transport chain has electrons to work with.</div>"]},{"id":"sf3-3-x0","title":"Explore: The oxidative phosphorylation system","teach":[],"act":{"type":"explore","prompt":"Open each question.","panels":[{"label":"Why do textbooks disagree on the total?","text":"This chapter uses 30 ATP per glucose (31 from glycogen), reflecting newer evidence that older figures were too high. Older textbooks quote 36 to 38. If you apply the conversion values in the deck’s figure (2.5 ATP per NADH, 1.5 per FADH2) to every NADH and FADH2 produced, you land nearer 32, which is why current sources give a range of roughly 30 to 32. For this course, answer 30."}]}},{"id":"sf3-3-x1","title":"Explore: The oxidative phosphorylation system","teach":[],"act":{"type":"explore","prompt":"Open each question.","panels":[{"label":"Carbohydrate","text":"Glucose goes through glycolysis to pyruvate. Pyruvate enters the mitochondria and is converted to acetyl CoA."},{"label":"Fat","text":"Triglycerides are broken down by lipolysis into fatty acids and glycerol. Fatty acids are carried into the mitochondria, where beta-oxidation clips them into 2-carbon segments and converts each to acetyl CoA. A 16-carbon fatty acid such as palmitate can therefore give 8 acetyl CoA."},{"label":"Protein","text":"Amino acids are metabolized aerobically once the amino (nitrogen) group has been removed."}]}},{"id":"sf3-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Where does the electron transport chain operate, and what is the final electron acceptor?","options":[{"label":"Cytosol; pyruvate","correct":false,"feedback":"Electrons finish on oxygen, which forms water."},{"label":"Inner mitochondrial membrane; oxygen","correct":true,"feedback":"Electrons finish on oxygen, which forms water."},{"label":"Mitochondrial matrix; NAD","correct":false,"feedback":"Electrons finish on oxygen, which forms water."},{"label":"Inner mitochondrial membrane; carbon dioxide","correct":false,"feedback":"Electrons finish on oxygen, which forms water."}]}},{"id":"sf3-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What is the major function of the Krebs cycle in ATP production?","options":[{"label":"Making most of the ATP directly","correct":false,"feedback":"The cycle makes only a little ATP itself. Its main job is to oxidize compounds and hand the electrons onward."},{"label":"Removing electrons from compounds so the electron transport chain can use them","correct":true,"feedback":"The cycle makes only a little ATP itself. Its main job is to oxidize compounds and hand the electrons onward."},{"label":"Turning lactate into glucose","correct":false,"feedback":"The cycle makes only a little ATP itself. Its main job is to oxidize compounds and hand the electrons onward."},{"label":"Splitting creatine phosphate","correct":false,"feedback":"The cycle makes only a little ATP itself. Its main job is to oxidize compounds and hand the electrons onward."}]}},{"id":"sf3-3-q2","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"When pyruvate becomes acetyl CoA, NAD picks up electrons. NAD is therefore:","options":[{"label":"Oxidized","correct":false,"feedback":"Gaining electrons is reduction. Pyruvate, which lost them, is the one oxidized."},{"label":"Reduced","correct":true,"feedback":"Gaining electrons is reduction. Pyruvate, which lost them, is the one oxidized."},{"label":"Hydrolyzed","correct":false,"feedback":"Gaining electrons is reduction. Pyruvate, which lost them, is the one oxidized."},{"label":"Phosphorylated","correct":false,"feedback":"Gaining electrons is reduction. Pyruvate, which lost them, is the one oxidized."}]}},{"id":"sf3-4","chapter":"Fuel use and the respiratory exchange ratio","title":"Fuel use and the respiratory exchange ratio","html":"<h3>Fuel selection and RER</h3><p>Lower-intensity exercise uses a larger percentage of fat, while increasing intensity shifts reliance toward carbohydrate because carbohydrate can supply ATP more rapidly. Absolute fat oxidation may rise from rest to moderate intensity before falling at high intensity. RER is useful during steady-state exercise but becomes less precise during very hard work, recovery, or conditions that alter ventilation.</p>","visual":null,"blocksHtml":["<div class=\"mn-html\"><span>Remember it</span><b>1.00 is a perfect score, and carbohydrate “wins” it.</b> Pure carbohydrate gives the clean, whole number RER of 1.00. Fat, the slower-burning fuel, sits well below it at 0.70. The closer the number is to 1.00, the more carbohydrate is being burned.</div>","<p>As intensity rises above moderate, carbohydrate becomes the predominant fuel, which is why the RER climbs toward 1.00 during hard work.</p>","<h3>What each tissue does in each metabolic state</h3>","<div class=\"tabblk\"><b>Fed</b><div class=\"tissues\"><div class=\"tissue\"><h4>Liver</h4><p>Uses glucose for energy, stores glycogen, and converts any surplus to fatty acids. Amino acids are metabolized. Fatty acids are sent to adipose tissue.</p></div><div class=\"tissue\"><h4>Muscle</h4><p>Uses glucose for energy or stores it as glycogen.</p></div><div class=\"tissue\"><h4>Adipose tissue</h4><p>Stores fatty acids as triglycerides (three fatty acids plus glycerol).</p></div><div class=\"tissue\"><h4>Central nervous system</h4><p>Runs on glucose from the meal.</p></div></div></div><div class=\"tabblk\"><b>Postabsorptive</b><div class=\"tissues\"><div class=\"tissue\"><h4>Liver</h4><p>Breaks down glycogen to release glucose. Starts making glucose from lactate and alanine (from muscle) and glycerol (from fat).</p></div><div class=\"tissue\"><h4>Muscle</h4><p>Uses glucose, still storing some glycogen. Sends lactate and alanine to the liver. Takes up fatty acids from adipose tissue for fuel.</p></div><div class=\"tissue\"><h4>Adipose tissue</h4><p>Breaks down triglycerides, sending fatty acids to muscle and liver and glycerol to the liver.</p></div><div class=\"tissue\"><h4>Central nervous system</h4><p>Gets glucose mainly from liver glycogen.</p></div></div></div><div class=\"tabblk\"><b>Fasting (18 to 48 h)</b><div class=\"tissues\"><div class=\"tissue\"><h4>Liver</h4><p>Glycogen is used up. Makes glucose from lactate and from amino acids supplied by muscle. Red blood cells also supply some lactate.</p></div><div class=\"tissue\"><h4>Muscle</h4><p>Muscle protein is degraded to send amino acids to the liver. Lactate goes to the liver for glucose making.</p></div><div class=\"tissue\"><h4>Adipose tissue</h4><p>Continues to break down triglycerides for fatty acids and glycerol.</p></div><div class=\"tissue\"><h4>Central nervous system</h4><p>Glucose comes from the liver, built from lactate and amino acids.</p></div></div></div><div class=\"tabblk\"><b>Starvation (over 48 h)</b><div class=\"tissues\"><div class=\"tissue\"><h4>Liver</h4><p>Keeps making glucose, mostly from glycerol, so muscle does not have to supply amino acids and lactate. Turns fatty acids into ketones for the CNS and muscle.</p></div><div class=\"tissue\"><h4>Muscle</h4><p>Depends mainly on fatty acids and ketones.</p></div><div class=\"tissue\"><h4>Adipose tissue</h4><p>Continues to break down triglycerides for fatty acids and glycerol.</p></div><div class=\"tissue\"><h4>Central nervous system</h4><p>Depends mainly on ketones made by the liver.</p></div></div></div>"]},{"id":"sf3-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A nonprotein respiratory exchange ratio of 0.70 indicates energy coming from:","options":[{"label":"Carbohydrate only","correct":false,"feedback":"Palmitate uses 23 O₂ for 16 CO₂, which is 0.70."},{"label":"Fat only","correct":true,"feedback":"Palmitate uses 23 O₂ for 16 CO₂, which is 0.70."},{"label":"Half carbohydrate, half fat","correct":false,"feedback":"Palmitate uses 23 O₂ for 16 CO₂, which is 0.70."},{"label":"Protein only","correct":false,"feedback":"Palmitate uses 23 O₂ for 16 CO₂, which is 0.70."}]}},{"id":"sf3-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"VO₂ is 2.00 L/min and VCO₂ is 1.70 L/min. What are the RER and the approximate fuel mix?","options":[{"label":"1.18, mostly carbohydrate","correct":false,"feedback":"1.70 divided by 2.00 is 0.85, and Table 3.2 gives 49% carbohydrate and 51% fat."},{"label":"0.85, about 15% carbohydrate and 85% fat","correct":false,"feedback":"1.70 divided by 2.00 is 0.85, and Table 3.2 gives 49% carbohydrate and 51% fat."},{"label":"0.85, about 49% carbohydrate and 51% fat","correct":true,"feedback":"1.70 divided by 2.00 is 0.85, and Table 3.2 gives 49% carbohydrate and 51% fat."},{"label":"1.00, all carbohydrate","correct":false,"feedback":"1.70 divided by 2.00 is 0.85, and Table 3.2 gives 49% carbohydrate and 51% fat."}]}},{"id":"sf3-4-q2","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"After more than 48 hours without food, the central nervous system depends mainly on:","options":[{"label":"Glucose from the last meal","correct":false,"feedback":"Liver glycogen is long gone. The liver turns fatty acids into ketones, and the CNS relies mainly on them."},{"label":"Glucose from liver glycogen","correct":false,"feedback":"Liver glycogen is long gone. The liver turns fatty acids into ketones, and the CNS relies mainly on them."},{"label":"Ketones made by the liver","correct":true,"feedback":"Liver glycogen is long gone. The liver turns fatty acids into ketones, and the CNS relies mainly on them."},{"label":"Lactate from red blood cells","correct":false,"feedback":"Liver glycogen is long gone. The liver turns fatty acids into ketones, and the CNS relies mainly on them."}]}},{"id":"sf3-5","chapter":"Oxygen use, EPOC and VO₂max","title":"Oxygen use, EPOC and VO₂max","html":"<h3>Oxygen deficit, VO2, and recovery</h3><p>At exercise onset, oxygen consumption takes time to meet demand, producing an oxygen deficit covered by anaerobic systems. After exercise, oxygen consumption remains elevated during EPOC as ATP and phosphagen stores recover, lactate is processed, temperature and hormones normalize, and circulation and ventilation remain elevated. VO2max reflects maximal oxygen uptake and depends on delivery, utilization, genetics, and training.</p><h3>Training adaptations and nutrition</h3><p>Endurance training increases mitochondria, oxidative enzymes, capillaries, and the ability to use fat at a given workload, which can spare glycogen. Sprint and strength training improve phosphagen capacity, glycolytic enzymes, buffering, and neuromuscular output. Nutrition supports these adaptations through sufficient energy, carbohydrate for quality work, protein for repair, fluid, and micronutrients.</p>","visual":null,"blocksHtml":["<p><span class=\"cap\">Approximate readings from Figure 3.26, in mL of oxygen per kg of body weight per minute.</span></p>","<h3>One steady bout of exercise</h3>","<p>Oxygen uptake does not jump the moment you start, and it does not drop the moment you stop.</p>","<p><span class=\"cap\">Schematic based on Figure 3.27. Exercise starts at minute 5 and stops at minute 10.</span></p>","<dl class=\"facts\"><div><dt>Oxygen deficit</dt><dd>At the start, oxygen use lags behind demand. The gap is covered by ATP “borrowed” from the anaerobic systems.</dd></div><div><dt>Steady state</dt><dd>Oxygen consumption levels off at the amount the intensity needs.</dd></div><div><dt>EPOC</dt><dd>Excess postexercise oxygen consumption: oxygen use stays above resting for several minutes after stopping.</dd></div></dl>"]},{"id":"sf3-5-x0","title":"Explore: Oxygen use, EPOC and VO₂max","teach":[],"act":{"type":"explore","prompt":"During EPOC, what is happening to creatine phosphate and lactate?","panels":[{"label":"Show the answer","text":"The creatine shuttle uses oxygen and the aerobic system to turn creatine back into creatine phosphate. Lactate from glycolysis is taken up by aerobic tissues, converted to pyruvate and metabolized aerobically. Both jobs need oxygen, which is part of why uptake stays elevated."}]}},{"id":"sf3-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"At the start of steady exercise, oxygen uptake climbs gradually. In that gap, ATP is mostly supplied by:","options":[{"label":"Oxygen stored in the mitochondria","correct":false,"feedback":"ATP is “borrowed” from the anaerobic systems, and the lag in oxygen consumption is the oxygen deficit."},{"label":"The anaerobic energy systems","correct":true,"feedback":"ATP is “borrowed” from the anaerobic systems, and the lag in oxygen consumption is the oxygen deficit."},{"label":"Protein breakdown","correct":false,"feedback":"ATP is “borrowed” from the anaerobic systems, and the lag in oxygen consumption is the oxygen deficit."},{"label":"Fat only","correct":false,"feedback":"ATP is “borrowed” from the anaerobic systems, and the lag in oxygen consumption is the oxygen deficit."}]}},{"id":"sf3-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"After exercise stops, oxygen consumption stays above resting for a while. This is called:","options":[{"label":"Oxygen deficit","correct":false,"feedback":"EPOC is excess postexercise oxygen consumption. It reflects work such as the creatine shuttle and lactate clearance."},{"label":"VO₂max","correct":false,"feedback":"EPOC is excess postexercise oxygen consumption. It reflects work such as the creatine shuttle and lactate clearance."},{"label":"EPOC","correct":true,"feedback":"EPOC is excess postexercise oxygen consumption. It reflects work such as the creatine shuttle and lactate clearance."},{"label":"Respiratory exchange ratio","correct":false,"feedback":"EPOC is excess postexercise oxygen consumption. It reflects work such as the creatine shuttle and lactate clearance."}]}},{"id":"sf3-5-q2","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"VO₂max is reached when:","options":[{"label":"Oxygen consumption plateaus even though intensity keeps rising","correct":true,"feedback":"In a graded test, oxygen use rises with intensity and then levels off. That plateau is VO₂max."},{"label":"Exercise intensity plateaus","correct":false,"feedback":"In a graded test, oxygen use rises with intensity and then levels off. That plateau is VO₂max."},{"label":"RER falls to 0.70","correct":false,"feedback":"In a graded test, oxygen use rises with intensity and then levels off. That plateau is VO₂max."},{"label":"The oxygen deficit disappears","correct":false,"feedback":"In a graded test, oxygen use rises with intensity and then levels off. That plateau is VO₂max."}]}},{"id":"sf3-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A 100 m sprinter is 10 to 12 seconds into a race. Which system led at the start, why does it fade, and what takes over?","text":"Creatine phosphate led. It is one chemical step, very fast, and gives one ATP per CrP, but it carries only about 5 to 10 seconds because CrP runs out. Anaerobic glycolysis, also fast but small, backs it up, while oxidative phosphorylation is still ramping up because it is very slow to start."},{"label":"Two riders hold the same power. Rider A has an RER of 0.78 and rider B has 0.92. Estimate each fuel mix and say who is leaning harder on carbohydrate.","text":"Interpolating Table 3.2, rider A is at about 25% carbohydrate and 75% fat, and rider B is at about 73% carbohydrate and 27% fat. Rider B leans harder on carbohydrate. The RER alone does not say why: relative intensity, training status and recent carbohydrate intake could all play a part."},{"label":"A client has fasted for 36 hours. Liver glycogen is gone. Where does glucose for the brain come from, and what is the cost?","text":"In the 18 to 48 hour range the liver makes glucose from lactate and from amino acids sent by muscle, with red blood cells supplying some lactate. The cost is muscle protein. Past 48 hours the liver shifts to glycerol from fat to spare muscle, and makes ketones that the CNS and muscle can use."},{"label":"Compare why a 60 m sprinter and a marathoner each stop being able to hold pace.","text":"The sprinter is linked to CrP depletion within seconds, a capacity limit in the fastest system. The marathoner is linked to fuel depletion in the oxidative system, such as muscle glycogen, after a long time. One runs out of a tiny, fast reservoir. The other runs out of supply."},{"label":"Someone jogs steadily for 10 minutes, then stops and keeps breathing hard for several minutes. Explain using oxygen deficit and EPOC.","text":"At the start, oxygen uptake lagged behind demand, so ATP was borrowed from the anaerobic systems: that is the oxygen deficit. After stopping, oxygen uptake stays elevated (EPOC) because the creatine shuttle needs aerobic ATP to restore CrP and aerobic tissues are clearing lactate."},{"label":"A runner starts glycolysis from muscle glycogen. How many net ATP does glycolysis give, and how many does complete oxidation give in this chapter?","text":"Glycolysis from glycogen nets 3 ATP, since it costs 1 and makes 4. Complete oxidation of glycogen gives 31 ATP in this chapter (30 from glucose)."}]}}],"flashcards":[{"front":"ATP → ADP + P<sub>i</sub> + energy: exergonic or endergonic?","back":"Exergonic. It releases energy (hydrolysis)."},{"front":"ADP + P<sub>i</sub> → ATP: exergonic or endergonic?","back":"Endergonic. It needs energy in (rephosphorylation)."},{"front":"Enzyme that splits ATP in muscle","back":"Myosin ATPase"},{"front":"Enzyme of the CrP reaction","back":"Creatine kinase (CK)"},{"front":"ATP made per CrP","back":"One"},{"front":"Duration of the CrP system","back":"About 5 to 10 seconds"},{"front":"Fatigue with the CrP system is linked to","back":"CrP depletion"},{"front":"Daily creatine intake plus synthesis, without supplements","back":"About 2 g, with about 2 g per day lost as creatinine"},{"front":"Share of muscle creatine held as CrP","back":"About two-thirds. One-third is free creatine."},{"front":"The creatine shuttle","back":"Aerobic rephosphorylation of creatine to CrP in the mitochondria, restoring CrP within a minute or two"},{"front":"Net ATP of glycolysis from glucose","back":"2 (4 made, 2 invested)"},{"front":"Net ATP of glycolysis from glycogen","back":"3 (4 made, 1 invested)"},{"front":"Rate-limiting enzyme of glycolysis","back":"Phosphofructokinase (PFK)"},{"front":"Macronutrient anaerobic glycolysis uses","back":"Carbohydrate only"},{"front":"Pyruvate and lactate: one-way or two-way?","back":"Two-way"},{"front":"Cori cycle","back":"Lactate is converted back to glucose in the liver"},{"front":"Where the oxidative system operates","back":"Mitochondria"},{"front":"Pyruvate is converted to","back":"Acetyl CoA"},{"front":"Main job of the Krebs cycle","back":"Oxidize compounds and strip electrons for the electron transport chain"},{"front":"Where the electron transport chain sits","back":"Inner mitochondrial membrane"},{"front":"Final electron acceptor, and what forms","back":"Oxygen, forming water"},{"front":"ATP from complete oxidation of glucose, and glycogen (this chapter)","back":"30 from glucose, 31 from glycogen"},{"front":"Rate-limiting enzymes of oxidative phosphorylation","back":"PFK, IDH and COX"},{"front":"Breakdown of triglycerides","back":"Lipolysis"},{"front":"Clipping 2-carbon segments off a fatty acid to make acetyl CoA","back":"Beta-oxidation"},{"front":"Protein is used aerobically after","back":"The amino (nitrogen) group is removed"},{"front":"RER formula","back":"VCO<sub>2</sub> divided by VO<sub>2</sub>"},{"front":"RER of pure carbohydrate and pure fat","back":"1.00 and 0.70"},{"front":"Lag in oxygen use at the start of exercise","back":"Oxygen deficit"},{"front":"Elevated oxygen use after exercise","back":"EPOC (excess postexercise oxygen consumption)"},{"front":"VO<sub>2</sub>max","back":"The plateau in oxygen consumption even as intensity keeps rising"}],"quiz":[{"q":"What is creatine?","o":["An amino acid","A nitrogen-containing compound made from amino acids","A phosphate-containing protein","A byproduct of the breakdown of creatinine"],"a":1,"e":"Creatine is a nitrogen-containing compound synthesized from amino acids."},{"q":"Based on dietary intake only, whom would you expect to have the lowest amount of muscle creatine?","o":["Vegetarians","Red meat eaters","Fish eaters","No differences would be expected based on dietary intake"],"a":0,"e":"Meat and fish provide dietary creatine, so vegetarians generally start with lower muscle creatine stores."},{"q":"Which of the following is a true statement regarding creatine supplementation?","o":["Has been shown to be beneficial for both strength and endurance athletes","Has a direct effect on improving strength, speed, and power for strength athletes","Causes dehydration and muscle cramping in strength athletes","Allows strength and power athletes to sustain high-intensity training"],"a":3,"e":"Creatine can help sustain repeated high-intensity training; it does not directly guarantee greater maximal power."},{"q":"In a well-designed study, a statistically significant increase in maximal strength with creatine supplementation was detected at 12 weeks but not at 1 week. What is the likely explanation?","o":["Creatine supplementation allowed athletes to complete more weight lifting repetitions and sets, but the effects of the training are not seen immediately.","It takes time (about three months) for the body to increase the total amount of ATP stored in muscle.","Time was needed to maximize carbohydrate stores because creatine storage and function are directly related to the size of muscle glycogen stores.","Hormonal balance is altered, but the changes are slow and subtle and not detectable for approximately 12 weeks."],"a":0,"e":"The supplement can support more training work, while strength adaptation takes time."},{"q":"Anaerobic glycolysis is an energy system that uses:","o":["carbohydrate only.","carbohydrate preferentially, but fat or protein if necessary.","carbohydrate, protein, or fat based on availability.","carbohydrate, protein, fat, or alcohol."],"a":0,"e":"Anaerobic glycolysis uses carbohydrate only."},{"q":"The rate of glycolysis in muscle is controlled primarily by:","o":["lactate dehydrogenase (LDH).","myosin ATPase.","creatine kinase (CK).","phosphofructokinase (PFK)."],"a":3,"e":"PFK is the main rate-limiting enzyme identified for glycolysis."},{"q":"The net (final) ATP production from anaerobic glycolysis is:","o":["2 ATPs if beginning with glycogen.","3 ATPs if beginning with glucose.","3 ATPs if beginning with glycogen.","38 ATPs if beginning with glucose."],"a":2,"e":"Starting from glycogen yields a net three ATP in the chapter."},{"q":"If creatine phosphate is nearly depleted in skeletal muscle by high-intensity exercise, approximately how long does it take to restore creatine phosphate levels?","o":["1 – 2 seconds","1 – 2 minutes","1 – 2 hours","1 – 2 days"],"a":1,"e":"The course gives about 1–2 minutes for substantial creatine phosphate restoration."},{"q":"The energy source preferred by exercising muscle for the process of anaerobic glycolysis is:","o":["glucose.","glycogen.","glycerol.","creatine."],"a":1,"e":"Muscle glycogen avoids the first ATP cost and is preferred during anaerobic glycolysis."},{"q":"The primary function of the Krebs cycle is to:","o":["degrade glucose or glycogen to lactate and produce ATP.","oxidize carbohydrates, fats, and proteins and ready them for ATP production.","generate large amounts of ATP and related compounds.","produce carbon dioxide and water for use in other energy-yielding systems."],"a":1,"e":"The Krebs cycle oxidizes fuel intermediates and transfers electrons for later ATP production."},{"q":"The rate-limiting enzyme associated with the Krebs cycle is:","o":["lactate dehydrogenase (LDH).","creatine kinase (CK).","phosphofructokinase (PFK).","isocitrate dehydrogenase (IDH)."],"a":3,"e":"IDH is the rate-limiting enzyme associated with the Krebs cycle in the chapter."},{"q":"It is biochemically impossible to convert carbohydrate to fatty acids.","o":["True","False"],"a":1,"e":"Excess carbohydrate can be converted to fatty acids."},{"q":"As exercise intensity increases, the percentage of energy from carbohydrate metabolism decreases.","o":["True","False"],"a":1,"e":"Carbohydrate contribution rises as exercise intensity increases."},{"q":"At rest, the preferred fuel source is carbohydrate.","o":["True","False"],"a":1,"e":"At rest, fat generally supplies the greater share of energy."},{"q":"Anaerobic glycolysis is a process that begins with glucose and ends with lactate.","o":["True","False"],"a":0,"e":"In the course model, anaerobic glycolysis converts glucose or glycogen through pyruvate toward lactate."},{"q":"Once pyruvate is converted to lactate in the muscle it cannot be converted back.","o":["True","False"],"a":1,"e":"The pyruvate–lactate reaction is reversible."},{"q":"Most research has shown that short-term creatine “loading” results in an immediate increase in absolute, maximal power.","o":["True","False"],"a":1,"e":"Research more often supports maintaining repeated power rather than an immediate rise in absolute maximal power."},{"q":"Creatine supplements are effective for both strength and endurance athletes.","o":["True","False"],"a":1,"e":"Creatine is most relevant to repeated high-intensity strength and power work, not endurance performance in general."},{"q":"An all-out sprint lasting 10 seconds would depend primarily on anaerobic glycolysis as a source of ATP.","o":["True","False"],"a":1,"e":"A 10-second maximal effort depends strongly on the faster creatine phosphate system, while all systems contribute."},{"q":"The purpose of the three energy systems is to use chemical energy to re-form ATP.","o":["True","False"],"a":0,"e":"All three systems provide chemical energy to re-form ATP."},{"q":"ATP and CrP are both high-energy phosphate compounds.","o":["True","False"],"a":0,"e":"ATP and creatine phosphate both contain high-energy phosphate bonds."},{"q":"Most research has shown that creatine supplementation results in the maintenance of exercise power output rather than an immediate increase in absolute, maximal power.","o":["True","False"],"a":0,"e":"This matches the research interpretation emphasized in the course."},{"q":"Highly aerobic muscle fibers and other tissues can use lactate as an energy source.","o":["True","False"],"a":0,"e":"Aerobic tissues can convert lactate to pyruvate and oxidize it."},{"q":"The respiratory exchange ratio (RER) uses the amount of carbon dioxide produced and the amount of oxygen consumed to determine the percentage of energy derived from carbohydrate and fat.","o":["True","False"],"a":0,"e":"RER uses VCO₂ divided by VO₂ to estimate carbohydrate and fat oxidation."},{"q":"The energy system that has the fastest rate of ATP replenishment is anaerobic glycolysis.","o":["True","False"],"a":1,"e":"Creatine phosphate replenishes ATP faster than anaerobic glycolysis."},{"q":"Those who eat beef or fish consume about 5 g of creatine daily.","o":["True","False"],"a":1,"e":"Typical dietary creatine from meat or fish is well below 5 g/day in the course context."},{"q":"The terms Krebs cycle and the tricarboxylic acid (TCA) cycle are interchangeable.","o":["True","False"],"a":0,"e":"Krebs, citric acid, and TCA cycle refer to the same pathway."},{"q":"The major function of the Krebs cycle portion of oxidative phosphorylation is to produce moderate to large amounts of ATP.","o":["True","False"],"a":1,"e":"Its primary role is removing electrons for the electron transport chain, not directly producing large amounts of ATP."},{"q":"The branched chain amino acids can be relatively easily metabolized by skeletal muscle but they are considered the least preferred fuel source when compared to carbohydrates and fats.","o":["True","False"],"a":0,"e":"BCAAs can be oxidized by muscle but remain a less preferred fuel than carbohydrate or fat."},{"q":"An exceptionally well-trained male endurance athlete will likely have a VO2 max greater than 100 ml/kg/min.","o":["True","False"],"a":1,"e":"Values above 100 ml/kg/min are beyond the likely range stated for exceptionally trained male endurance athletes."}]},{"n":4,"title":"Carbohydrates","kicker":"Learn how carbohydrate structure, digestion, blood-glucose control, exercise intensity and meal timing shape fuel availability and recovery.","steps":[{"id":"sf4-0","chapter":"Carbohydrate structure","title":"Carbohydrate structure","html":"<h3>Carbohydrate structure</h3><p>Monosaccharides include glucose, fructose, and galactose. Disaccharides include sucrose, lactose, and maltose. Starches are digestible glucose polymers, while fibre includes carbohydrate structures that resist digestion in the small intestine. “Simple” and “complex” describe structure, not automatically nutritional quality; the food matrix, fibre, processing, and total diet matter.</p>","visual":{"title":"Carbohydrate structure","kind":"comparison","items":[{"label":"Sucrose =","detail":"Glucose + fructose"},{"label":"Lactose =","detail":"Glucose + galactose"},{"label":"Maltose =","detail":"Glucose + glucose"}]},"blocksHtml":["<p>All carbohydrates are built from the same handful of sugar units strung together in different lengths. A <b>monosaccharide</b> is one sugar unit; a <b>disaccharide</b> is two joined together; and a <b>polysaccharide</b> is a long chain of many sugar units, whether digestible (starch, glycogen) or not (most dietary fibre). Chain length, branching, and the type of chemical bond between units are what decide how quickly, or whether, human digestive enzymes can break a carbohydrate apart.</p>","<dl class=\"facts\"><div><dt>Starch</dt><dd>A plant storage polysaccharide, mostly straight (amylose) or branched (amylopectin) chains of glucose. Human enzymes digest it readily.</dd></div><div><dt>Glycogen</dt><dd>The animal storage polysaccharide, more heavily branched than starch, which speeds up how fast it can be broken down and mobilized when muscle or liver need glucose quickly.</dd></div><div><dt>Dietary fibre</dt><dd>Plant polysaccharides (such as cellulose and pectin) joined by bonds human enzymes cannot cleave, so they pass largely intact into the large intestine, where some are fermented by gut bacteria.</dd></div></dl>","<div class=\"mn-html\"><span>Remember it</span><b>Lactose sounds like “galactose.”</b> That’s the tell: lactose (milk sugar) is the one made of glucose + galactose. Maltose is “malt” which is grain-derived from starch, i.e. two linked glucose units, so it’s simply glucose + glucose. Sucrose (table sugar) is what’s left: glucose + fructose.</div>"]},{"id":"sf4-0-s0","title":"Which class is it?","teach":[],"act":{"type":"sort","prompt":"Which class is it?","categories":["Monosaccharide","Disaccharide","Polysaccharide"],"items":[{"label":"Glucose","category":0,"feedback":"A single sugar unit."},{"label":"Fructose","category":0,"feedback":"A single sugar unit, largely processed by the liver."},{"label":"Sucrose","category":1,"feedback":"Glucose + fructose."},{"label":"Lactose","category":1,"feedback":"Glucose + galactose."},{"label":"Maltose","category":1,"feedback":"Glucose + glucose."},{"label":"Starch","category":2,"feedback":"A digestible glucose polymer."},{"label":"Glycogen","category":2,"feedback":"The branched storage polysaccharide in muscle and liver."},{"label":"Dietary fibre","category":2,"feedback":"Plant polysaccharides that resist digestion in the small intestine."}]}},{"id":"sf4-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Lactose is made of:","options":[{"label":"Glucose + fructose","correct":false,"feedback":"Lactose contains one glucose and one galactose."},{"label":"Glucose + galactose","correct":true,"feedback":"Lactose contains one glucose and one galactose."},{"label":"Glucose + glucose","correct":false,"feedback":"Lactose contains one glucose and one galactose."},{"label":"Two fructose units","correct":false,"feedback":"Lactose contains one glucose and one galactose."}]}},{"id":"sf4-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Muscle glycogen is a:","options":[{"label":"Monosaccharide","correct":false,"feedback":"Glycogen is a branched polysaccharide used to store glucose."},{"label":"Disaccharide","correct":false,"feedback":"Glycogen is a branched polysaccharide used to store glucose."},{"label":"Polysaccharide","correct":true,"feedback":"Glycogen is a branched polysaccharide used to store glucose."}]}},{"id":"sf4-1","chapter":"Digestion, absorption, and blood glucose","title":"Digestion, absorption, and blood glucose","html":"<h3>Digestion, absorption, and blood glucose</h3><p>Digestion begins in the mouth with salivary amylase, pauses in the acidic stomach, and continues in the small intestine with pancreatic amylase and brush-border enzymes. Glucose and galactose use sodium-dependent transport; fructose uses a different transporter. Monosaccharides enter portal blood and travel to the liver. Insulin promotes glucose uptake and storage after eating, while glucagon supports blood glucose between meals and during exercise.</p>","visual":{"title":"Digestion, absorption, and blood glucose","kind":"sequence","items":[{"label":"Blood glucose rises","detail":"After a carbohydrate-containing meal, glucose enters portal blood and travels to the liver."},{"label":"Beta cells release insulin","detail":"High blood glucose stimulates the pancreatic beta cells to secrete insulin."},{"label":"Insulin promotes uptake and storage","detail":"Glucose moves into cells and is stored as liver and muscle glycogen. Insulin also supports amino-acid uptake."},{"label":"Blood glucose falls","detail":"Between meals or during exercise, glucose drops."},{"label":"Glucagon raises it again","detail":"Glucagon stimulates liver glycogen breakdown and glucose release. Insulin and glucagon act in opposite directions to keep glucose steady."}]},"blocksHtml":["<dl class=\"facts\"><div><dt>Glucose and galactose</dt><dd>Sodium-dependent active transport.</dd></div><div><dt>Fructose</dt><dd>Depends on a concentration gradient. The liver takes it up and converts it.</dd></div><div><dt>Lactose intolerance</dt><dd>Lactase is insufficient for the lactose eaten.</dd></div><div><dt>FODMAPs</dt><dd>Fermentable short-chain carbohydrates that can trigger GI symptoms in susceptible people.</dd></div></dl>"]},{"id":"sf4-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which hormone stimulates breakdown of liver glycogen and release of glucose?","options":[{"label":"Glucagon","correct":true,"feedback":"Glucagon raises blood glucose. Insulin lowers it by promoting uptake and storage."},{"label":"Insulin","correct":false,"feedback":"Glucagon raises blood glucose. Insulin lowers it by promoting uptake and storage."},{"label":"Thyroid-stimulating hormone","correct":false,"feedback":"Glucagon raises blood glucose. Insulin lowers it by promoting uptake and storage."},{"label":"Pancreatic lipase","correct":false,"feedback":"Glucagon raises blood glucose. Insulin lowers it by promoting uptake and storage."}]}},{"id":"sf4-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"After absorption, fructose is largely:","options":[{"label":"Circulated unchanged to muscle","correct":false,"feedback":"Fructose is trapped by the liver and converted to glucose or other metabolites."},{"label":"Taken up by the liver and converted","correct":true,"feedback":"Fructose is trapped by the liver and converted to glucose or other metabolites."},{"label":"Excreted in urine","correct":false,"feedback":"Fructose is trapped by the liver and converted to glucose or other metabolites."},{"label":"Stored as fructose","correct":false,"feedback":"Fructose is trapped by the liver and converted to glucose or other metabolites."}]}},{"id":"sf4-2","chapter":"Glycogen storage and exercise fuel","title":"Glycogen storage and exercise fuel","html":"<h3>Glycogen storage and limits</h3><p>The liver stores glycogen to help maintain blood glucose. Skeletal muscle stores glycogen for its own contractions because muscle cannot release free glucose into the blood. Total stores are limited and vary with body size, muscle mass, diet, and training. Depletion contributes to fatigue during prolonged or repeated high-intensity exercise.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Liver glycogen</b><p>Roughly 80 to 110 g in a typical adult. Helps maintain blood glucose between meals and overnight. The liver has the enzyme (glucose-6-phosphatase) needed to break glycogen down into free glucose and release it into the blood.</p></div><div class=\"tabblk\"><b>Muscle glycogen</b><p>Roughly 300 to 400 g across all skeletal muscle in a typical untrained adult, more in well-trained muscle. Stored for the muscle’s own contractions. Muscle lacks glucose-6-phosphatase, so it cannot release free glucose into the blood, it can only use its own glycogen locally.</p></div>","<p>Contracting muscle can also take up blood glucose through an insulin-like effect of exercise, independent of insulin itself. Epinephrine and norepinephrine stimulate glycogen breakdown during stress and hard exercise. Stores are limited, and depletion contributes to fatigue in prolonged or repeated high-intensity exercise, which is the physiological basis for carbohydrate loading and in-session fuelling covered later in this unit.</p>","<div class=\"callout\"><b class=\"k\">Practical read.</b> Because muscle glycogen cannot rescue blood glucose, a hard training session can leave someone with severely depleted leg muscles while blood glucose stays perfectly normal. Fatigue from local glycogen depletion and fatigue from low blood glucose are two different problems that call for different fixes.</div>"]},{"id":"sf4-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Exercising muscle prefers to use carbohydrate from:","options":[{"label":"Blood glucose","correct":false,"feedback":"Muscle glycogen is stored at the site of use and is immediately available."},{"label":"Liver glycogen","correct":false,"feedback":"Muscle glycogen is stored at the site of use and is immediately available."},{"label":"Muscle glycogen","correct":true,"feedback":"Muscle glycogen is stored at the site of use and is immediately available."},{"label":"Any source with no preference","correct":false,"feedback":"Muscle glycogen is stored at the site of use and is immediately available."}]}},{"id":"sf4-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Why can muscle glycogen not be used to raise blood glucose?","options":[{"label":"It is too slow to break down","correct":false,"feedback":"Only the liver can release glucose from glycogen into the circulation."},{"label":"Muscle cannot release free glucose into the blood","correct":true,"feedback":"Only the liver can release glucose from glycogen into the circulation."},{"label":"It is not a carbohydrate","correct":false,"feedback":"Only the liver can release glucose from glycogen into the circulation."},{"label":"Insulin blocks it","correct":false,"feedback":"Only the liver can release glucose from glycogen into the circulation."}]}},{"id":"sf4-3","chapter":"Daily carbohydrate targets","title":"Daily carbohydrate targets","html":"<h3>Daily carbohydrate needs</h3><p>Requirements rise with training volume and intensity. A general sports range is roughly 3–10 g/kg/day, with very high-volume endurance work sometimes reaching about 12 g/kg/day. The target should reflect the actual session, not the athlete’s identity alone. Lower-load days may require less; long or intense days require more.</p>","visual":null,"blocksHtml":[]},{"id":"sf4-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The recommended daily carbohydrate for high-intensity, short-duration exercise is:","options":[{"label":"3 to 5 g/kg","correct":false,"feedback":"The course table gives 5 to 7 g/kg/day for high-intensity, short-duration exercise."},{"label":"5 to 7 g/kg","correct":true,"feedback":"The course table gives 5 to 7 g/kg/day for high-intensity, short-duration exercise."},{"label":"8 to 12 g/kg","correct":false,"feedback":"The course table gives 5 to 7 g/kg/day for high-intensity, short-duration exercise."},{"label":"1 g/kg","correct":false,"feedback":"The course table gives 5 to 7 g/kg/day for high-intensity, short-duration exercise."}]}},{"id":"sf4-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A diet can be “high carbohydrate” by percentage yet still supply too few grams when:","options":[{"label":"Fibre is high","correct":false,"feedback":"Grams per kilogram matter more than percentage of energy."},{"label":"Total calorie intake is low","correct":true,"feedback":"Grams per kilogram matter more than percentage of energy."},{"label":"Protein is high","correct":false,"feedback":"Grams per kilogram matter more than percentage of energy."},{"label":"Fluid is low","correct":false,"feedback":"Grams per kilogram matter more than percentage of energy."}]}},{"id":"sf4-4","chapter":"Before, during, and after exercise","title":"Before, during, and after exercise","html":"<h3>Before and during exercise</h3><p>One to four hours before activity, a familiar carbohydrate-rich meal or snack can support liver and muscle glycogen. Portion size usually increases when more time is available. During sustained high-intensity, endurance, or intermittent exercise, about 30–60 g/hour is common; ultraendurance events may use up to about 90 g/hour from multiple transportable carbohydrates. Fluid, concentration, flavour, and GI tolerance must be practised.</p><h3>Recovery and glycogen restoration</h3><p>When recovery time is short, begin carbohydrate soon after exercise. The chapter uses about 1.5 g/kg in the first hour and additional carbohydrate over the next several hours. Medium- to high-glycemic foods can accelerate insulin response and glycogen synthesis. Protein supports repair and can help when carbohydrate intake is suboptimal, but it does not replace carbohydrate for glycogen.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Soon after exercise</dt><dd>Starts glycogen restoration sooner.</dd></div><div><dt>Frequent feedings</dt><dd>Small, regular carbohydrate intake supports replenishment.</dd></div><div><dt>Rapidly digested carbohydrate</dt><dd>Useful when fast recovery is needed.</dd></div><div><dt>Add protein</dt><dd>Helpful, especially when carbohydrate is below the optimal amount. It does not replace carbohydrate.</dd></div></dl>"]},{"id":"sf4-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"As a rule of thumb, how much carbohydrate should be eaten two hours before exercise?","options":[{"label":"1 g/kg","correct":false,"feedback":"About 1 g/kg one hour before, 2 g/kg two hours before, and 3 g/kg three hours before, adjusted for tolerance."},{"label":"2 g/kg","correct":true,"feedback":"About 1 g/kg one hour before, 2 g/kg two hours before, and 3 g/kg three hours before, adjusted for tolerance."},{"label":"3 g/kg","correct":false,"feedback":"About 1 g/kg one hour before, 2 g/kg two hours before, and 3 g/kg three hours before, adjusted for tolerance."},{"label":"10 g/kg","correct":false,"feedback":"About 1 g/kg one hour before, 2 g/kg two hours before, and 3 g/kg three hours before, adjusted for tolerance."}]}},{"id":"sf4-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which approach best supports fast muscle glycogen replenishment?","options":[{"label":"Wait two hours, then one large meal","correct":false,"feedback":"Start early, feed often, and choose rapidly digested carbohydrate when recovery time is short."},{"label":"Carbohydrate soon after exercise in small, frequent feedings","correct":true,"feedback":"Start early, feed often, and choose rapidly digested carbohydrate when recovery time is short."},{"label":"Fructose only","correct":false,"feedback":"Start early, feed often, and choose rapidly digested carbohydrate when recovery time is short."},{"label":"Protein only","correct":false,"feedback":"Start early, feed often, and choose rapidly digested carbohydrate when recovery time is short."}]}},{"id":"sf4-5","chapter":"Fibre, glycemic index, and carbohydrate loading","title":"Fibre, glycemic index, and carbohydrate loading","html":"<h3>Fibre, glycemic index, and carbohydrate loading</h3><p>Fibre supports bowel health, cholesterol management, and microbiota, but a large high-fibre meal close to intense exercise can cause distress. Glycemic index compares blood-glucose response to a fixed amount of available carbohydrate; glycemic load also considers portion size. Carbohydrate loading combines tapering with high carbohydrate intake before long endurance events and is unnecessary for brief activity.</p>","visual":{"title":"Fibre, glycemic index, and carbohydrate loading","kind":"sequence","items":[{"label":"Taper training","detail":"Carbohydrate loading combines a taper with high carbohydrate intake before long endurance events. It is unnecessary for brief activity."},{"label":"Depletion phase","detail":"The modified protocol uses roughly 5 g/kg/day carbohydrate."},{"label":"Repletion phase","detail":"Then about 10 g/kg/day to maximize muscle glycogen."},{"label":"Practise it","detail":"Choose familiar, lower-fibre foods close to competition and rehearse the plan in training."}]},"blocksHtml":["<dl class=\"facts\"><div><dt>Glycemic index</dt><dd>Compares blood-glucose response to a fixed amount of available carbohydrate.</dd></div><div><dt>Glycemic load</dt><dd>Also accounts for portion size.</dd></div><div><dt>Fibre</dt><dd>Supports bowel health and cholesterol management, but a big high-fibre meal before hard exercise can cause distress.</dd></div></dl>"]},{"id":"sf4-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What does the glycemic index measure?","options":[{"label":"Sweetness","correct":false,"feedback":"GI ranks carbohydrate foods by their effect on blood glucose, driven largely by digestion and absorption rate."},{"label":"Extent of blood-glucose elevation","correct":true,"feedback":"GI ranks carbohydrate foods by their effect on blood glucose, driven largely by digestion and absorption rate."},{"label":"Fibre content","correct":false,"feedback":"GI ranks carbohydrate foods by their effect on blood glucose, driven largely by digestion and absorption rate."},{"label":"Potential for oxidation","correct":false,"feedback":"GI ranks carbohydrate foods by their effect on blood glucose, driven largely by digestion and absorption rate."}]}},{"id":"sf4-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"In the modified carbohydrate-loading protocol, the repletion phase uses about:","options":[{"label":"3 g/kg","correct":false,"feedback":"Roughly 5 g/kg during depletion followed by about 10 g/kg during repletion."},{"label":"5 g/kg","correct":false,"feedback":"Roughly 5 g/kg during depletion followed by about 10 g/kg during repletion."},{"label":"10 g/kg","correct":true,"feedback":"Roughly 5 g/kg during depletion followed by about 10 g/kg during repletion."},{"label":"20 g/kg","correct":false,"feedback":"Roughly 5 g/kg during depletion followed by about 10 g/kg during repletion."}]}},{"id":"sf4-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A 70 kg athlete eats a pre-event meal three hours before the start. How much carbohydrate does the rule of thumb suggest?","text":"3 g/kg × 70 kg = about 210 g, adjusted for tolerance and familiar foods."},{"label":"A 60 kg cyclist finishes a hard session and has a second session in five hours. What is the first move?","text":"Start carbohydrate soon after finishing, about 1.5 g/kg (90 g) in the first hour, then continue frequent feedings. Adding protein can help, but it does not replace carbohydrate."}]}}],"flashcards":[{"front":"Carbohydrate energy","back":"4 kcal per gram."},{"front":"Sucrose, lactose, maltose","back":"Glucose + fructose; glucose + galactose; glucose + glucose."},{"front":"Glucose transport vs fructose","back":"Glucose: active transport. Fructose: concentration gradient, then the liver."},{"front":"Insulin","back":"From beta cells. Promotes glucose uptake and storage."},{"front":"Glucagon","back":"Stimulates liver glycogen breakdown and glucose release."},{"front":"Muscle vs liver glycogen","back":"Muscle fuels itself and cannot release free glucose. Liver maintains blood glucose."},{"front":"Glycemic index","back":"How much a food raises blood glucose, mainly set by digestion and absorption rate."},{"front":"Low-intensity daily carbohydrate","back":"3 to 5 g/kg/day."},{"front":"High-intensity, short-duration daily carbohydrate","back":"5 to 7 g/kg/day."},{"front":"Long endurance daily carbohydrate","back":"6 to 10 g/kg/day."},{"front":"Ultraendurance daily carbohydrate","back":"8 to 12 g/kg/day."},{"front":"Pre-exercise rule of thumb","back":"1 g/kg at 1 h, 2 g/kg at 2 h, 3 g/kg at 3 h."},{"front":"Carbohydrate during long events","back":"About 30 to 60 g/hour; up to about 90 g/hour in ultraendurance events."},{"front":"First recovery hour","back":"About 1.5 g/kg carbohydrate when recovery time is short."},{"front":"Modified carbohydrate loading","back":"About 5 g/kg depletion then about 10 g/kg repletion."}],"quiz":[{"q":"Complex carbohydrate is a:","o":["monosaccharide.","disaccharide.","polysaccharide."],"a":2,"e":"Complex carbohydrates are polysaccharides made from many linked sugar units."},{"q":"Fructose is a:","o":["monosaccharide.","disaccharide.","polysaccharide."],"a":0,"e":"Fructose is one of the three dietary monosaccharides."},{"q":"Muscle glycogen is a:","o":["monosaccharide.","disaccharide.","polysaccharide."],"a":2,"e":"Glycogen is a branched polysaccharide used to store glucose."},{"q":"Lactose is a:","o":["monosaccharide","disaccharide made up of 2 glucose molecules","disaccharide made up of galactose and glycogen","none of the above"],"a":3,"e":"Lactose is a disaccharide made from glucose and galactose, which none of the first three options states."},{"q":"What is the primary benefit to consuming a high-carbohydrate meal 3 hours prior to competition?","o":["Enhanced liver glycogen","Enhanced muscle glycogen","Enhanced fat oxidation","Enhanced fat mobilization"],"a":0,"e":"A pre-event carbohydrate meal helps restore liver glycogen and supports blood glucose availability."},{"q":"As a “rule of thumb,” which of the following best describes pre-event carbohydrate recommendations?","o":["100 g 2 hours prior","1 g/kg 1 hour prior, 2 g/kg 2 hours prior, 3 g/kg 3 hours prior","50% of the athlete’s usual carbohydrate intake","No “rule of thumb” as pre-event carbohydrate intake must be calculated precisely"],"a":1,"e":"The course presents the 1 g/kg per hour-before-exercise rule as a practical starting point."},{"q":"Glucose is a:","o":["monosaccharide.","disaccharide.","polysaccharide."],"a":0,"e":"Glucose is a single sugar unit and therefore a monosaccharide."},{"q":"Fiber is a:","o":["monosaccharide.","disaccharide.","polysaccharide."],"a":2,"e":"Dietary fibre consists largely of plant polysaccharides."},{"q":"What is the composition of sucrose?","o":["Two fructose units","One glucose and one fructose unit","One glucose and one galactose unit","One galactose and one fructose unit"],"a":1,"e":"Sucrose contains one glucose and one fructose."},{"q":"What is the composition of lactose?","o":["Two fructose units","One glucose and one fructose unit","One glucose and one galactose unit","One galactose and one fructose unit"],"a":2,"e":"Lactose contains one glucose and one galactose."},{"q":"_____ is an example of a sugar alcohol.","o":["Cellulose","Maltose","Guar gum","Glycerol"],"a":3,"e":"Glycerol is an alcohol derived from sugar chemistry."},{"q":"Why is the caloric value of some sugar alcohols less than 4 kcal/g?","o":["They are not completely absorbed","They are not completely metabolized by cells for energy","They cannot be transported into the mitochondria","All of the above"],"a":0,"e":"Some sugar alcohols provide less energy because the intestine does not completely absorb them."},{"q":"What is the intended meaning of the marketing term “low-impact carbs”?","o":["Carbohydrate foods that are burned for energy rather than stored as fat.","Carbohydrate foods with fewer kilocalories than similar products.","Carbohydrate foods that result in a slow rise in blood glucose and insulin.","Carbohydrate foods that contain both simple and complex carbohydrates."],"a":2,"e":"The term is intended to suggest a slower rise in blood glucose and insulin."},{"q":"What is an end product of carbohydrate digestion?","o":["Sucrose","Glucose","Lactose","Maltose"],"a":1,"e":"Digestible carbohydrate must be reduced to monosaccharides such as glucose for absorption."},{"q":"Why are many people unable to digest milk sugar?","o":["They lack pancreatic amylase","They lack the proper intestinal bacteria","They were not breast-fed","They have a lactase deficiency"],"a":3,"e":"Lactase splits lactose; insufficient lactase causes lactose malabsorption."},{"q":"Why does fructose not appear in circulating blood after absorption?","o":["It is used immediately by the intestinal cells for energy","It is transported via the lymphatic system and taken up by cells immediately","It is immediately trapped by the liver and converted to glucose","All of the above"],"a":2,"e":"Absorbed fructose travels to the liver, where it is taken up and converted."},{"q":"How do fructose and glucose absorption and uptake differ?","o":["The carrier is the same but absorption is slower when loaded with fructose.","Glucose appears in the blood rapidly but fructose appears in the blood slowly.","Fructose absorption depends on a concentration gradient while glucose absorption requires active transport.","There are no differences between fructose and glucose absorption."],"a":2,"e":"Fructose uses facilitated transport down a gradient; glucose uses sodium-dependent active transport."},{"q":"Of the following, the only characteristic shared by sugars and starches is their:","o":["kilocalories per gram.","rate of appearance in the blood.","nutrient content.","sweetness level."],"a":0,"e":"Digestible sugars and starches both provide about 4 kcal per gram."},{"q":"Blood glucose of 80 mg/dl is considered:","o":["hypoglycemia.","hyperglycemia.","within the normal range."],"a":2,"e":"80 mg/dL falls within the normal fasting range."},{"q":"Under normal circumstances, _____ is used to restore fallen blood glucose levels.","o":["muscle glycogen","liver glycogen","glucose provided by the oxidation of fat","glucose provided by the oxidation of muscle protein"],"a":1,"e":"The liver can break down its glycogen and release glucose into circulation."},{"q":"The physiological response to hyperglycemia resulting from the consumption of carbohydrate-containing foods is:","o":["stimulation of alpha cells in the pancreas and secretion of insulin.","stimulation of beta cells in the pancreas and the secretion of insulin.","stimulation of alpha cells in the pancreas and secretion of glucagon.","stimulation of beta cells in the pancreas and secretion of glucagon."],"a":1,"e":"High blood glucose stimulates pancreatic beta cells to secrete insulin."},{"q":"The release of insulin results in the:","o":["uptake of glucose into cells.","uptake of amino acids into muscle cells.","storage of glucose as glycogen in liver and muscle.","all of the above"],"a":3,"e":"Insulin supports glucose uptake, amino-acid uptake, and glycogen storage."},{"q":"What hormone is responsible for stimulating the breakdown of liver glycogen and its release as glucose?","o":["Glucagon","Insulin","Thyroid-stimulating hormone","Pancreatic lipase"],"a":0,"e":"Glucagon raises blood glucose by stimulating liver glycogen breakdown."},{"q":"What does the glycemic index (GI) measure?","o":["Degree of sweetness","Potential for oxidation as a fuel source","Level of gastrointestinal distress","Extent of blood glucose elevation"],"a":3,"e":"GI ranks carbohydrate foods by their effect on blood glucose."},{"q":"The glycemic index (GI) is primarily determined by:","o":["whether a carbohydrate is a sugar or a starch.","the rate of digestion and absorption.","the level of liver and muscle glycogen stores.","the need for an immediate source of glucose by the muscle."],"a":1,"e":"How quickly carbohydrate is digested and absorbed largely determines its blood-glucose effect."},{"q":"Exercising muscle prefers to use carbohydrate from:","o":["blood glucose.","liver glycogen.","muscle glycogen.","any carbohydrate source available (no preference)."],"a":2,"e":"Muscle glycogen is stored at the site of use and can fuel contraction quickly."},{"q":"How does regular aerobic exercise training affect carbohydrate (CHO) usage?","o":["Increases the enzymatic activity associated with glycolysis","Increases the number and size of mitochondria","Decreases liver glycogen storage so more CHO is stored as muscle glycogen","All of the above"],"a":1,"e":"Aerobic training increases mitochondrial number and size, improving oxidative capacity."},{"q":"How do epinephrine and norepinephrine raise blood glucose concentration?","o":["Stimulate the conversion of glycogen to glucose","Stimulate amino acid transport to the liver","Mobilize fat stores","All of the above"],"a":0,"e":"These stress hormones stimulate glycogenolysis, increasing available glucose."},{"q":"Ten grams of carbohydrate yields approximately how many kcal?","o":["40","50","70","90"],"a":0,"e":"Carbohydrate provides about 4 kcal/g, so 10 g provides about 40 kcal."},{"q":"What type of exercise training was used in the majority of studies conducted on muscle glycogen depletion and carbohydrate replenishment?","o":["High intensity, short duration","Intermittent, high intensity","Endurance","No one type predominates"],"a":2,"e":"Most of this research used endurance exercise protocols."},{"q":"The recommended amount of daily carbohydrate for athletes engaged in high-intensity, short-duration exercise is:","o":["5 g/kg of body weight.","5-7 g/kg of body weight.","6-8 g/kg of body weight.","8+ g/kg of body weight."],"a":1,"e":"The course table gives 5–7 g/kg/day for high-intensity, short-duration exercise."},{"q":"Timing — Select the strategy likely to lead to optimal muscle glycogen replenishment.","o":["Consuming carbohydrate immediately after exercise","Consuming carbohydrate 2 hours after exercise"],"a":0,"e":"Starting carbohydrate intake immediately takes advantage of a faster early replenishment rate."},{"q":"Meal size — Select the strategy likely to lead to optimal muscle glycogen replenishment.","o":["Consuming carbohydrate in small, frequent meals","Consuming carbohydrate in a large, single meal"],"a":0,"e":"Small, frequent feedings provide carbohydrate repeatedly during recovery."},{"q":"Type of carbohydrate — Select the strategy likely to lead to optimal muscle glycogen replenishment.","o":["Consuming fructose","Consuming sucrose"],"a":1,"e":"Sucrose supplies glucose as well as fructose and supports muscle glycogen better than fructose alone."},{"q":"Type of carbohydrate — Select the strategy likely to lead to optimal muscle glycogen replenishment.","o":["Consuming low-glycemic carbohydrates","Consuming high-glycemic carbohydrates"],"a":1,"e":"High-GI carbohydrate is digested and absorbed rapidly when fast glycogen replenishment is needed."},{"q":"Other nutrients — Select the strategy likely to lead to optimal muscle glycogen replenishment.","o":["Carbohydrate + protein","Carbohydrate only"],"a":0,"e":"Adding protein can support the insulin response and replenishment, especially when carbohydrate intake is not optimal."}]},{"n":5,"title":"Proteins","kicker":"Connect amino acid structure and protein quality with digestion, metabolism, muscle protein balance, athlete recommendations, food planning and supplement evidence.","steps":[{"id":"sf5-0","chapter":"Amino acids and protein quality","title":"Amino acids and protein quality","html":"<h3>Amino acids and protein structure</h3><p>Proteins are chains of amino acids folded into specific shapes. Nine amino acids are essential because the body cannot synthesize enough of them. Nonessential amino acids can be produced, while conditionally essential amino acids may become limited during illness, injury, or other stress. Protein function depends on both amino-acid sequence and three-dimensional structure.</p><h3>Protein quality</h3><p>High-quality proteins provide all essential amino acids in digestible proportions. Animal foods generally score highly, but plant-based diets can meet needs through adequate total intake and variety. Legumes, soy foods, grains, nuts, seeds, and fortified foods contribute. Complementary proteins do not have to be eaten in the same mouthful when the overall diet is adequate.</p>","visual":{"title":"Amino acids and protein quality","kind":"sequence","items":[{"label":"Amino acid","detail":"The basic building block: amino group, carboxyl group and a unique side chain."},{"label":"Peptide bond","detail":"A bond forms between the carboxyl group of one amino acid and the amino group of the next, releasing a water molecule."},{"label":"Dipeptide, tripeptide","detail":"Two amino acids joined make a dipeptide; three make a tripeptide."},{"label":"Polypeptide","detail":"A longer chain, roughly 10 to 50 amino acids, is called a polypeptide."},{"label":"Protein","detail":"A protein is one or more polypeptide chains, typically 50 or more amino acids, folded into a specific shape. That shape, not just the sequence, determines what the protein can do."}]},"blocksHtml":["<h3>What makes an amino acid an amino acid</h3>","<p>Every amino acid shares the same basic frame: a central carbon holding an <b>amino group</b> (–NH<sub>2</sub>), a <b>carboxyl group</b> (–COOH), a hydrogen, and a <b>side chain</b> (the “R group”) that is different for each one. The side chain is what makes leucine leucine and glutamine glutamine: it sets the amino acid’s size, shape, charge and chemistry, which in turn decides what job that amino acid can do in a protein.</p>","<dl class=\"facts\"><div><dt>Structure sets function</dt><dd>Change the sequence or unfold the shape (denature it) and the protein usually stops working, even though every amino acid is still present.</dd></div><div><dt>Roughly 20 amino acids</dt><dd>Build essentially all human protein. They are strung together in different orders and lengths to make thousands of different proteins.</dd></div><div><dt>Why 9 are indispensable</dt><dd>Human cells lack the enzymes to build these particular side chains from scratch, so diet is the only source.</dd></div></dl>","<h3>The three groups, in full</h3>","<div class=\"tabblk\"><b>9 indispensable</b><p>Histidine, isoleucine, leucine, lysine, methionine, phenylalanine, threonine, tryptophan, valine.</p><p class=\"small\">Leucine, isoleucine and valine are also called the branched-chain amino acids (BCAAs), named for the branched shape of their side chains.</p></div><div class=\"tabblk\"><b>Dispensable</b><p>Alanine, asparagine, aspartic acid, glutamic acid, serine, and others the body builds routinely from other compounds when the diet supplies enough total nitrogen and energy.</p></div><div class=\"tabblk\"><b>Conditionally indispensable</b><p>Arginine, cysteine, glutamine, glycine, proline, tyrosine. Normally dispensable, but illness, injury, prematurity or heavy training can push demand above what the body can synthesize, so diet needs to help out.</p></div>","<div class=\"mn-html\"><span>Remember it</span><b>HILL + MTV + PT = the 9 indispensable amino acids.</b> <b>H</b>istidine, <b>I</b>soleucine, <b>L</b>eucine, <b>L</b>ysine; <b>M</b>ethionine, <b>T</b>hreonine, <b>V</b>aline; <b>P</b>henylalanine, <b>T</b>ryptophan. The three branched-chain amino acids are <b>LIV</b>: Leucine, Isoleucine and Valine.</div>","<h3>Four levels of protein structure</h3>","<div class=\"tabblk\"><b>Primary</b><p>The specific sequence of amino acids, linked end to end by peptide bonds. Change one amino acid in the sequence and the protein can fold incorrectly or stop working, as in sickle cell hemoglobin.</p></div><div class=\"tabblk\"><b>Secondary</b><p>Short, repeating local shapes the chain folds into, such as a coiled alpha helix or a pleated beta sheet, held together by hydrogen bonds along the chain’s backbone.</p></div><div class=\"tabblk\"><b>Tertiary</b><p>The overall three-dimensional folded shape of a single polypeptide chain, driven by how its side chains attract, repel, or bond with each other and with water.</p></div><div class=\"tabblk\"><b>Quaternary</b><p>How two or more folded polypeptide chains assemble into one functional unit. Hemoglobin, for example, is four polypeptide chains working as one oxygen-carrying protein.</p></div>","<div class=\"callout\"><b class=\"k\">Denaturation.</b> Heat, acid, or agitation can unfold a protein’s secondary, tertiary and quaternary structure without breaking its peptide bonds, the way heat firms up egg white. The primary sequence survives, but the original shape and function are usually lost.</div>","<h3>Now classify each one</h3>","<h3>Judging protein quality</h3>","<p>A protein’s quality depends on two things: whether it supplies every indispensable amino acid in the proportions the body needs, and how well it is digested and absorbed. A protein can be “complete” on paper but still score lower if the body cannot break it down and absorb its amino acids efficiently.</p>","<div class=\"callout\">A <b>complete</b> protein supplies every indispensable amino acid in amounts that support growth. Egg white is a high-quality complete protein. Complementary plant proteins combine limiting amino acid patterns, such as beans with rice.</div>"]},{"id":"sf5-0-s0","title":"Classify each amino acid","teach":[],"act":{"type":"sort","prompt":"Classify each amino acid","categories":["Indispensable","Dispensable","Conditionally indispensable"],"items":[{"label":"Leucine","category":0,"feedback":"The body cannot make enough. Food must supply it. It is also a branched-chain amino acid."},{"label":"Lysine","category":0,"feedback":"Indispensable."},{"label":"Valine","category":0,"feedback":"Indispensable, and a branched-chain amino acid."},{"label":"Alanine","category":1,"feedback":"The body can manufacture it."},{"label":"Serine","category":1,"feedback":"The body can manufacture it."},{"label":"Asparagine","category":1,"feedback":"The body can manufacture it."},{"label":"Glutamine","category":2,"feedback":"Normally dispensable, but needs may exceed production during illness, injury or severe stress."},{"label":"Arginine","category":2,"feedback":"Normally dispensable, but conditionally indispensable under stress."}]}},{"id":"sf5-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"How does an indispensable amino acid differ from an essential one?","options":[{"label":"Caloric content","correct":false,"feedback":"They are alternate terms for amino acids the body cannot make in sufficient amounts."},{"label":"Nitrogen content","correct":false,"feedback":"They are alternate terms for amino acids the body cannot make in sufficient amounts."},{"label":"Rate of absorption","correct":false,"feedback":"They are alternate terms for amino acids the body cannot make in sufficient amounts."},{"label":"No difference other than terminology","correct":true,"feedback":"They are alternate terms for amino acids the body cannot make in sufficient amounts."}]}},{"id":"sf5-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A protein containing all indispensable amino acids in the proper amounts is termed:","options":[{"label":"Complete","correct":true,"feedback":"A complete protein supports growth without needing another source."},{"label":"Complementary","correct":false,"feedback":"A complete protein supports growth without needing another source."},{"label":"Incomplete","correct":false,"feedback":"A complete protein supports growth without needing another source."},{"label":"Dispensable","correct":false,"feedback":"A complete protein supports growth without needing another source."}]}},{"id":"sf5-1","chapter":"Digestion and the amino acid pool","title":"Digestion and the amino acid pool","html":"<h3>Digestion and the amino-acid pool</h3><p>Stomach acid denatures protein and activates pepsin. Pancreatic proteases and intestinal peptidases produce amino acids and small peptides for absorption. The amino-acid pool supplies tissue synthesis, enzymes, hormones, transport proteins, immune molecules, and other compounds. The body has no dedicated protein-storage depot, so excess amino acids are deaminated and their carbon skeletons are oxidized or stored.</p>","visual":{"title":"Digestion and the amino acid pool","kind":"sequence","items":[{"label":"Stomach","detail":"Acid denatures protein and activates pepsin."},{"label":"Small intestine","detail":"Pancreatic proteases and intestinal peptidases produce amino acids and small peptides."},{"label":"Absorption","detail":"Amino acids and small peptides are absorbed mainly here."},{"label":"Liver clearinghouse","detail":"The liver monitors the supply and directs much of amino acid metabolism. Branched-chain amino acids circulate more directly to tissues."},{"label":"Amino acid pool","detail":"Free amino acids in blood and fluid around cells, about 150 g on average, with glutamine the largest share. It is replenished by diet, protein turnover and synthesis of dispensable amino acids."}]},"blocksHtml":[]},{"id":"sf5-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Absorption of food proteins takes place primarily in the:","options":[{"label":"Stomach and jejunum","correct":false,"feedback":"Amino acids and small peptides are absorbed mainly in the jejunum and ileum."},{"label":"Jejunum and ileum","correct":true,"feedback":"Amino acids and small peptides are absorbed mainly in the jejunum and ileum."},{"label":"Ileum and colon","correct":false,"feedback":"Amino acids and small peptides are absorbed mainly in the jejunum and ileum."},{"label":"Colon and rectum","correct":false,"feedback":"Amino acids and small peptides are absorbed mainly in the jejunum and ileum."}]}},{"id":"sf5-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The organ considered the clearinghouse for most amino acids is the:","options":[{"label":"Liver","correct":true,"feedback":"The liver directs much of amino acid metabolism."},{"label":"Kidney","correct":false,"feedback":"The liver directs much of amino acid metabolism."},{"label":"Heart","correct":false,"feedback":"The liver directs much of amino acid metabolism."},{"label":"Brain","correct":false,"feedback":"The liver directs much of amino acid metabolism."}]}},{"id":"sf5-2","chapter":"Metabolism, turnover, and nitrogen balance","title":"Metabolism, turnover, and nitrogen balance","html":"<h3>Protein turnover and nitrogen balance</h3><p>Muscle and other proteins are continually synthesized and broken down. Positive nitrogen balance occurs when synthesis and retention exceed loss, as during growth or well-supported hypertrophy. Negative balance can occur with severe energy restriction, illness, injury, or inadequate protein. Exercise stimulates turnover; training adaptation depends on both the stimulus and recovery nutrition.</p>","visual":{"title":"Metabolism, turnover, and nitrogen balance","kind":"sequence","items":[{"label":"Transamination","detail":"Transfers an amino group from one compound to another."},{"label":"Deamination","detail":"Removes the amino group, producing ammonia."},{"label":"Urea","detail":"The liver converts ammonia to urea for excretion."},{"label":"Carbon skeleton","detail":"The remaining skeleton enters aerobic metabolism at a point set by its structure. Excess amino acids are not stored as a separate reserve."}]},"blocksHtml":[]},{"id":"sf5-2-x0","title":"Explore: Metabolism, turnover, and nitrogen balance","teach":[],"act":{"type":"explore","prompt":"Open each question.","panels":[{"label":"Nitrogen balance versus muscle protein balance","text":"Nitrogen balance compares nitrogen intake with loss. Net muscle protein balance compares muscle protein synthesis with breakdown. Growth, pregnancy and muscle-building give positive balance. Starvation, illness and inadequate energy can give negative balance."},{"label":"Glucose–alanine cycle","text":"Muscle converts pyruvate to alanine, which travels to the liver. There the carbon skeleton can help form glucose, useful in prolonged exercise or low glycogen."}]}},{"id":"sf5-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What is nitrogen balance?","options":[{"label":"Muscle protein synthesized compared with degraded","correct":false,"feedback":"It compares total nitrogen intake with total nitrogen loss."},{"label":"The rate of protein turnover","correct":false,"feedback":"It compares total nitrogen intake with total nitrogen loss."},{"label":"The difference between nitrogen intake and loss","correct":true,"feedback":"It compares total nitrogen intake with total nitrogen loss."},{"label":"Protein absorbed minus protein stored in muscle","correct":false,"feedback":"It compares total nitrogen intake with total nitrogen loss."}]}},{"id":"sf5-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which correctly describes the glucose–alanine cycle?","options":[{"label":"Muscle converts alanine directly to energy","correct":false,"feedback":"Alanine carries carbon and nitrogen from muscle to liver, where the skeleton can support gluconeogenesis."},{"label":"Muscle converts pyruvate to alanine, which goes to the liver for potential conversion to glucose","correct":true,"feedback":"Alanine carries carbon and nitrogen from muscle to liver, where the skeleton can support gluconeogenesis."},{"label":"Glucose is converted to alanine after exercise","correct":false,"feedback":"Alanine carries carbon and nitrogen from muscle to liver, where the skeleton can support gluconeogenesis."},{"label":"The liver sends alanine to fat","correct":false,"feedback":"Alanine carries carbon and nitrogen from muscle to liver, where the skeleton can support gluconeogenesis."}]}},{"id":"sf5-3","chapter":"Protein recommendations and timing","title":"Protein recommendations and timing","html":"<h3>Athlete requirements and distribution</h3><p>The course uses about 1.2–2.0 g/kg/day for many athletes when energy intake is adequate. Needs vary with sport, training phase, age, energy deficit, injury, and goal. Distribution across three to five eating occasions usually provides repeated opportunities for muscle protein synthesis. A practical serving often supplies about 20–40 g of high-quality protein, depending on body size and context.</p><h3>Endurance, strength, and recovery</h3><p>Endurance athletes need protein for mitochondrial, enzyme, and structural adaptation and may oxidize more amino acids during long or glycogen-depleted exercise. Strength athletes need sufficient protein and energy to support hypertrophy, but progressive resistance training is the central stimulus. After training, protein supports repair; adding carbohydrate helps restore glycogen and total energy.</p>","visual":null,"blocksHtml":["<h3>Why distribution matters</h3>","<p>Muscle protein synthesis responds to a meal in a pulse: it rises for a few hours after eating enough high-quality protein, then returns toward baseline even if more protein is eaten right away. This “muscle-full” effect is why spreading protein across three to five meals of roughly 20 to 40 g each tends to stimulate more total protein synthesis over a day than the same total protein compressed into one or two large meals, even though the daily gram total is identical.</p>","<dl class=\"facts\"><div><dt>Leucine threshold</dt><dd>A meal needs roughly 2 to 3 g of leucine (found in about 20 to 40 g of most high-quality proteins) to strongly trigger muscle protein synthesis.</dd></div><div><dt>Before sleep</dt><dd>A slower-digesting protein (such as casein) before bed can extend overnight amino acid availability, which may help support overnight recovery in some athletes.</dd></div><div><dt>Energy first</dt><dd>If energy intake is inadequate, extra amino acids are increasingly used for energy rather than tissue repair, which is why a protein target means little without also checking total calories.</dd></div></dl>"]},{"id":"sf5-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The daily protein recommendation for sedentary adults is:","options":[{"label":"0.5 g/kg","correct":false,"feedback":"The adult RDA is 0.8 g/kg/day."},{"label":"0.8 g/kg","correct":true,"feedback":"The adult RDA is 0.8 g/kg/day."},{"label":"1.2 g/kg","correct":false,"feedback":"The adult RDA is 0.8 g/kg/day."},{"label":"2.0 g/kg","correct":false,"feedback":"The adult RDA is 0.8 g/kg/day."}]}},{"id":"sf5-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Strength athletes advised to eat 1 g of protein per pound of body weight are being advised:","options":[{"label":"1 g/kg","correct":false,"feedback":"One kilogram is about 2.2 pounds, so 1 g/lb is about 2.2 g/kg."},{"label":"1.5 g/kg","correct":false,"feedback":"One kilogram is about 2.2 pounds, so 1 g/lb is about 2.2 g/kg."},{"label":"2.2 g/kg","correct":true,"feedback":"One kilogram is about 2.2 pounds, so 1 g/lb is about 2.2 g/kg."},{"label":"4 g/kg","correct":false,"feedback":"One kilogram is about 2.2 pounds, so 1 g/lb is about 2.2 g/kg."}]}},{"id":"sf5-4","chapter":"Supplements and misconceptions","title":"Supplements and misconceptions","html":"<h3>Supplements and common misconceptions</h3><p>Protein powder can be convenient but is not inherently more anabolic than an equivalent food protein. Branched-chain amino acids provide only part of the essential-amino-acid pattern and are less useful than a complete protein when the diet is inadequate. Very high intake does not guarantee more muscle and may displace carbohydrate, fat, fibre, and micronutrient-rich foods.</p>","visual":{"title":"Supplements and misconceptions","kind":"comparison","items":[{"label":"Whey vs casein","detail":"Whey is faster digesting. Casein digests more slowly."},{"label":"“Pre-digested” protein","detail":"Enzymes hydrolyzed part of the protein during processing. It may absorb faster."},{"label":"BCAA supplements","detail":"Little or no evidence of improved endurance performance in trained athletes."},{"label":"Beta-alanine","detail":"Can help repeated high-intensity efforts lasting roughly 1 to 4 minutes."},{"label":"HMB","detail":"Evidence depends on training status and is weak in trained athletes."},{"label":"Protein powder","detail":"Convenient, but not inherently more anabolic than an equal food protein."}]},"blocksHtml":[]},{"id":"sf5-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A protein supplement labelled “fast-acting” most likely contains:","options":[{"label":"Whey","correct":true,"feedback":"Whey is digested and absorbed faster than casein."},{"label":"Casein","correct":false,"feedback":"Whey is digested and absorbed faster than casein."},{"label":"Glucose","correct":false,"feedback":"Whey is digested and absorbed faster than casein."},{"label":"Insulin","correct":false,"feedback":"Whey is digested and absorbed faster than casein."}]}},{"id":"sf5-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Is a BCAA supplement effective for improving endurance in trained athletes?","options":[{"label":"Strong evidence of effectiveness","correct":false,"feedback":"BCAAs supply only part of the essential-amino-acid pattern and add little when the diet is adequate."},{"label":"Little or no evidence of effectiveness","correct":true,"feedback":"BCAAs supply only part of the essential-amino-acid pattern and add little when the diet is adequate."}]}},{"id":"sf5-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A 75 kg athlete in a muscle-building phase asks how much protein to eat per day and per meal.","text":"About 1.8 to 2.0 g/kg is roughly 135 to 150 g/day, spread over three to five meals. A postexercise dose of 0.25 to 0.3 g/kg is about 19 to 23 g. Keep energy intake adequate so protein is not burned for fuel."},{"label":"Why can a calorie deficit raise protein needs?","text":"Low energy availability increases amino acid oxidation and reduces the protein-sparing effect of carbohydrate and fat."}]}}],"flashcards":[{"front":"Indispensable amino acid","back":"The body cannot make enough. Same as essential."},{"front":"Dispensable amino acid","back":"The body can manufacture it."},{"front":"Conditionally indispensable","back":"Needs may exceed production in illness, injury or severe stress."},{"front":"Complete protein","back":"All indispensable amino acids in proportions that support growth."},{"front":"Complementary proteins","back":"Plant proteins combined so limiting amino acids cover each other."},{"front":"Where protein is absorbed","back":"Mainly jejunum and ileum."},{"front":"Amino acid pool","back":"Free amino acids in blood and interstitial fluid, about 150 g. Glutamine is the largest share."},{"front":"Transamination vs deamination","back":"Transfer of an amino group; removal of an amino group."},{"front":"Ammonia to urea","back":"Done by the liver."},{"front":"Glucose–alanine cycle","back":"Muscle sends alanine to the liver, which can make glucose from its carbon skeleton."},{"front":"Nitrogen balance","back":"Nitrogen intake minus nitrogen loss."},{"front":"Protein RDA","back":"0.8 g/kg/day for sedentary adults."},{"front":"Athlete protein range","back":"About 1.2 to 2.0 g/kg/day with adequate energy."},{"front":"Postexercise protein dose","back":"About 0.25 to 0.3 g/kg, commonly 15 to 25 g."},{"front":"Protein energy","back":"About 4 kcal per gram."}],"quiz":[{"q":"The basic component of all proteins is:","o":["creatine.","amino acids.","purines.","glucose."],"a":1,"e":"Proteins are chains of amino acids linked by peptide bonds."},{"q":"The chemical composition of proteins differs from carbohydrate or fat because of the presence of:","o":["sodium.","carbon.","nitrogen.","hydrogen."],"a":2,"e":"Amino acids contain nitrogen in their amino group."},{"q":"Amino acids that can be manufactured by the body are best described as:","o":["essential.","dispensable.","indispensable.","complete."],"a":1,"e":"The body can synthesize dispensable amino acids."},{"q":"How does an indispensable amino acid differ from an essential amino acid?","o":["Caloric content","Nitrogen content","Rate of absorption","No difference other than terminology"],"a":3,"e":"Indispensable and essential are alternate terms for amino acids the body cannot make in sufficient amounts."},{"q":"Which athlete is most likely to be at risk for low protein intake?","o":["Male recreational athlete","Female body builder","Athlete in a “stop and go” sport","Athlete with disordered eating"],"a":3,"e":"Restrictive intake associated with disordered eating raises the risk of inadequate protein and energy."},{"q":"The factors that determine protein quality include:","o":["amount and rate of absorption.","rate and degree of metabolism/oxidation.","amount and type of amino acids.","digestibility and rate of turnover."],"a":2,"e":"Protein quality depends on its amino acid pattern and how well it is digested and absorbed."},{"q":"A food protein that contains all of the indispensable amino acids in the proper amounts and proportions to support growth is termed a(n):","o":["complete protein.","complementary protein.","incomplete protein.","indispensable protein."],"a":0,"e":"A complete protein supplies every indispensable amino acid in adequate proportions."},{"q":"Which of the following is an example of a complete protein?","o":["Egg whites","Legumes","Whole grains","Vegetables"],"a":0,"e":"Egg white is a high-quality complete protein."},{"q":"The primary (1st level) structure of the protein determines its:","o":["function.","shape.","rigidity or stability.","ability to bind with other compounds."],"a":0,"e":"The amino acid sequence drives later folding and ultimately the protein’s function."},{"q":"Absorption of food proteins takes place primarily in the:","o":["stomach and jejunum.","jejunum and ileum.","ileum and colon.","colon and rectum."],"a":1,"e":"Amino acids and small peptides are absorbed mainly in the small intestine."},{"q":"The amino acids that are most rapidly absorbed from the intestine are:","o":["dispensable amino acids.","indispensable amino acids.","dietary supplements containing pre-digested proteins.","dietary supplements containing casein."],"a":1,"e":"The course-confirmed answer is indispensable amino acids. Pre-digested (hydrolyzed) protein supplements can absorb quickly too, but as a category of food product, not an amino acid classification, so they are not the keyed answer to a question asking which amino acids absorb fastest."},{"q":"On a protein supplement label, what does the term pre-digested mean?","o":["A carrier is not needed for absorption","Absorption will be faster when compared to food proteins","Proteins have been exposed to enzymes during processing","Caloric content is lower than food proteins"],"a":2,"e":"Pre-digested means enzymes have hydrolyzed part of the protein during processing."},{"q":"The organ considered the clearinghouse for most amino acids is the:","o":["liver.","kidney.","heart.","brain."],"a":0,"e":"The liver monitors amino acid supply and directs much of their metabolism."},{"q":"What is the amino acid pool?","o":["Total amount of amino acids in the body","Total amount of amino acids in the skeletal muscles","Amino acids recently absorbed that are in need of transport","Amino acids circulating in the blood or fluid between cells"],"a":3,"e":"The amino acid pool consists of free amino acids in blood and extracellular fluid."},{"q":"Which amino acid is found in the greatest concentration in the amino acid pool?","o":["Alanine","Glutamine","Leucine","No one amino acid predominates"],"a":1,"e":"Glutamine accounts for about half of the amino acid pool in the course slides."},{"q":"How are amino acids supplied to the amino acid pool?","o":["Skeletal muscle catabolism","De novo synthesis","Dietary protein","All of the above"],"a":3,"e":"Diet, protein turnover, and synthesis of dispensable amino acids all contribute."},{"q":"To provide a protein-sparing effect, the athlete needs to consume sufficient:","o":["complementary proteins.","energy from carbohydrate and fat.","fluid.","animal proteins."],"a":1,"e":"Adequate carbohydrate and fat reduce the need to oxidize amino acids for energy."},{"q":"Protein is best used:","o":["as a source of glucose.","as a concentrated source of energy.","for growth and repair of tissue.","for metabolic regulation of fat."],"a":2,"e":"Protein’s primary role is structural and functional, including tissue growth and repair."},{"q":"An increase in the size of skeletal muscle tissue is referred to as:","o":["proteolysis.","proteoneogenesis.","hypertrophy.","protein-sparing effect."],"a":2,"e":"Hypertrophy means an increase in muscle fibre size."},{"q":"One gram of protein yields approximately how many kcal?","o":["1","4","7","9"],"a":1,"e":"Protein provides about 4 kcal per gram."},{"q":"On a gram for gram basis, protein has approximately the same amount of energy as:","o":["carbohydrate.","fat.","alcohol","minerals."],"a":0,"e":"Both protein and carbohydrate provide about 4 kcal per gram."},{"q":"The point of entry for an amino acid into the Krebs cycle is determined by its:","o":["nitrogen content.","caloric content.","potential to produce ammonia.","structure."],"a":3,"e":"Different carbon skeletons enter aerobic metabolism at different points."},{"q":"Which athlete would use protein as an energy source to the greatest extent?","o":["Recreational athlete","Strength athlete","Endurance athlete","All of the above would use about the same amount"],"a":2,"e":"Prolonged endurance work can increase amino acid oxidation, especially as glycogen falls."},{"q":"Which athlete would likely use protein as an energy source during competition?","o":["Marathon runner","800 meter runner","Body builder","Rower"],"a":0,"e":"A marathon’s long duration creates the greatest opportunity for amino acid oxidation."},{"q":"Which of the following correctly describes the glucose-alanine cycle?","o":["Muscle converts alanine to glucose for use as immediate energy.","Muscle converts alanine to pyruvate or lactate and converts them to glucose when muscle glycogen stores are low.","Glucose is converted to alanine in the muscle in the post-exercise period.","Muscle converts pyruvate to alanine, which is transported to the liver for potential conversion to glucose."],"a":3,"e":"Alanine carries carbon and nitrogen from muscle to liver, where its carbon skeleton can support gluconeogenesis."},{"q":"What is nitrogen balance?","o":["The amount of muscle protein synthesized compared to the amount degraded.","The amount and rate of protein turnover.","The difference between nitrogen intake and loss.","The difference between the amount of protein absorbed and the amount incorporated into skeletal muscle."],"a":2,"e":"Nitrogen balance compares total nitrogen intake with total nitrogen loss."},{"q":"What effect does insufficient energy (kcal) intake have on protein need?","o":["Increases protein need","Decreases protein need","No effect on protein need"],"a":0,"e":"Energy deficit increases reliance on amino acids and can raise protein needs."},{"q":"_____ is the production of glucose from a non-carbohydrate source, such as amino acids.","o":["Glycolysis","Gluconeogenesis","Lipolysis","Ketosis"],"a":1,"e":"Gluconeogenesis forms glucose from substrates such as amino acids, lactate, and glycerol."},{"q":"In the post-absorptive state (e.g. 10 hours after a meal), which is NOT likely to occur?","o":["Breakdown of liver glycogen","Gluconeogenesis","Lipolysis","Synthesis of skeletal muscle"],"a":3,"e":"The post-absorptive state emphasizes fuel mobilization rather than net muscle synthesis."},{"q":"With a 24-hour fast, the body is nearly depleted of liver glycogen. Where does the liver predominantly get the material it needs to manufacture glucose?","o":["Continued breakdown of liver glycogen until complete depletion","Breakdown of skeletal muscle","Breakdown of red blood cells","Manufacture of ketone bodies"],"a":1,"e":"Muscle amino acids become important gluconeogenic substrates as liver glycogen is depleted."},{"q":"The amount of protein recommended daily for sedentary adult males and non-pregnant females is:","o":["0.5 g/kg of body weight.","0.8 g/kg of body weight.","1.2 g/kg of body weight.","1.4 g/kg of body weight."],"a":1,"e":"The adult RDA is 0.8 g/kg/day."},{"q":"The amount of protein recommended daily for sedentary adult males and non-pregnant females expressed as a percentage of total caloric intake is:","o":["5-15%.","10-35%.","20-35%.","35-45%"],"a":1,"e":"The adult acceptable macronutrient distribution range for protein is 10–35% of energy."},{"q":"The amount of protein recommended daily for strength athletes is _____ per kg of body weight.","o":["0.8 g","1.2 g","1.4 g","2.0 g"],"a":1,"e":"The course-confirmed answer here is 1.2 g/kg/day for strength athletes in this specific question. Note this course elsewhere teaches a broader range (up to about 2.0 g/kg/day) for an active muscle-building phase, so treat 1.2 g/kg as this question's keyed baseline figure rather than a hard ceiling on strength-athlete protein intake."},{"q":"The amount of protein recommended daily for endurance athletes is _____ per kg of body weight.","o":["0.8 g","1.4 g","1.7 g","2.0 g"],"a":1,"e":"The paper’s best answer is 1.4 g/kg/day within the broader athlete range."},{"q":"The amount of protein recommended daily for recreational athletes who do not train is:","o":["0.8 to 1.0 g per kg of body weight.","1.2 to 1.4 g per kg of body weight.","1.2 to 1.7 g per kg of body weight.","more than 2.0 g per kg of body weight."],"a":0,"e":"Recreational activity may raise intake slightly above the sedentary recommendation."},{"q":"According to the current body of scientific research, is a branched chain amino acid supplement effective for improving endurance performance in trained endurance athletes?","o":["There is strong evidence of effectiveness.","There is little or no evidence of effectiveness."],"a":1,"e":"The course notes little evidence that supplemental BCAAs improve endurance performance."},{"q":"The label of a protein supplement states that it contains a “fast-acting” protein. This terminology suggests that the supplement contains:","o":["whey.","casein.","glucose.","insulin."],"a":0,"e":"Whey is digested and absorbed faster than casein."},{"q":"β-hydroxy-β-methylbutyrate (HMB) supplements have been shown to be safe and effective for increasing muscle size and strength in trained male athletes.","o":["True","False"],"a":1,"e":"The course reports little benefit in resistance-trained athletes."},{"q":"Strength athletes who are advised to consume 1 g of protein per pound of body weight are being advised to consume 2.2 g/kg body weight.","o":["True","False"],"a":0,"e":"One kilogram equals about 2.2 pounds, so 1 g/lb converts to about 2.2 g/kg."},{"q":"Short-term high-protein diets have been shown to have a harmful effect on renal (kidney) function in healthy adults.","o":["True","False"],"a":1,"e":"The course does not report demonstrated short-term renal harm in healthy adults."}]},{"n":6,"title":"Fats","kicker":"Learn how fatty acid structure influences food properties, then follow fat through digestion, transport, storage, exercise metabolism, intake planning and supplement claims.","steps":[{"id":"sf6-0","chapter":"Fatty acids, sterols, and phospholipids","title":"Fatty acids, sterols, and phospholipids","html":"<h3>Fatty-acid structure</h3><p>Saturated fatty acids contain no carbon-carbon double bonds. Monounsaturated fats contain one; polyunsaturated fats contain two or more. Cis double bonds bend the chain, while trans bonds keep it straighter. Chain length and saturation influence melting point, digestion, transport, and oxidation. Omega-3 and omega-6 fatty acids are essential families because humans cannot create the first double bond in those positions.</p><h3>Triglycerides, phospholipids, and sterols</h3><p>Most dietary fat is triglyceride: glycerol plus three fatty acids. Phospholipids contain a phosphate group and form cell membranes and emulsifiers. Sterols have a ring structure; cholesterol supports membranes, bile acids, vitamin D, and steroid hormones. Cholesterol occurs in animal foods, but blood cholesterol is also strongly influenced by genetics and the overall dietary-fat pattern.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Type</th><th>Structure</th><th>Cue</th></tr></thead><tbody><tr><td>Saturated</td><td>No carbon-carbon double bonds</td><td>Straighter chain; butter and many animal fats</td></tr><tr><td>Monounsaturated</td><td>One double bond</td><td>Olive oil and avocado</td></tr><tr><td>Polyunsaturated</td><td>Two or more double bonds</td><td>Includes omega-3 and omega-6</td></tr><tr><td>Cis / trans</td><td>Hydrogens on the same / opposite side</td><td>Cis bends the chain; trans keeps it straighter</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>Cis curls, trans stays straight.</b> Picture the letter “C” for cis, it’s curved, bending the fatty acid chain. “Trans” means “across,” like a straight train track running across the country. That bend is also why cis fats (most natural oils) are liquid at room temperature, while straighter trans and saturated fats pack tightly and turn solid.</div>"]},{"id":"sf6-0-s0","title":"Which fat predominates?","teach":[],"act":{"type":"sort","prompt":"Which fat predominates?","categories":["Saturated","Monounsaturated","Polyunsaturated"],"items":[{"label":"Butter","category":0,"feedback":"Rich in saturated fatty acids."},{"label":"Olive oil","category":1,"feedback":"Rich in monounsaturated fatty acids."},{"label":"Avocado","category":1,"feedback":"Monounsaturated."},{"label":"Corn oil","category":2,"feedback":"Predominantly polyunsaturated."},{"label":"Flaxseed","category":2,"feedback":"A source of omega-3 polyunsaturated fat (ALA)."}]}},{"id":"sf6-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Name the three major lipids in human nutrition.","options":[{"label":"Glycerol, cholesterol, ketones","correct":false,"feedback":"Triglycerides, sterols such as cholesterol, and phospholipids are the major classes."},{"label":"Triglycerides, cholesterol, phospholipids","correct":true,"feedback":"Triglycerides, sterols such as cholesterol, and phospholipids are the major classes."},{"label":"Carnitine, MCTs, cholesterol","correct":false,"feedback":"Triglycerides, sterols such as cholesterol, and phospholipids are the major classes."},{"label":"Lecithin, glycerol, phospholipids","correct":false,"feedback":"Triglycerides, sterols such as cholesterol, and phospholipids are the major classes."}]}},{"id":"sf6-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Trans double bonds, compared with cis bonds:","options":[{"label":"Bend the chain more","correct":false,"feedback":"Cis bends the chain. Trans keeps it straighter."},{"label":"Keep the chain straighter","correct":true,"feedback":"Cis bends the chain. Trans keeps it straighter."},{"label":"Add oxygen","correct":false,"feedback":"Cis bends the chain. Trans keeps it straighter."},{"label":"Make fat water-soluble","correct":false,"feedback":"Cis bends the chain. Trans keeps it straighter."}]}},{"id":"sf6-1","chapter":"Digestion, lipoproteins, and storage","title":"Digestion, lipoproteins, and storage","html":"<h3>Digestion and transport</h3><p>Lingual and gastric lipases make a small contribution, while most digestion occurs in the small intestine. Bile emulsifies fat and pancreatic lipase releases fatty acids and monoglycerides. These form micelles, enter intestinal cells, are rebuilt into triglycerides, and travel in chylomicrons through lymph to blood. Shorter-chain fatty acids can reach portal blood more directly.</p><h3>Lipoproteins and storage</h3><p>Lipoprotein lipase helps tissues remove fatty acids from circulating triglycerides. Chylomicrons carry dietary fat; VLDL carries triglyceride made or packaged by the liver; LDL delivers cholesterol to tissues; HDL participates in reverse cholesterol transport. Excess energy can be stored efficiently in adipose tissue, while intramuscular triglyceride provides a local fuel source.</p>","visual":{"title":"Digestion, lipoproteins, and storage","kind":"sequence","items":[{"label":"Bile emulsifies","detail":"Most fat digestion happens in the small intestine, where bile breaks fat into smaller droplets."},{"label":"Pancreatic lipase","detail":"Releases fatty acids and monoglycerides, which form micelles."},{"label":"Rebuilt in the cell","detail":"Intestinal cells rebuild long-chain triglycerides."},{"label":"Chylomicrons","detail":"Triglycerides are packaged in chylomicrons that enter lymph before blood. Short- and medium-chain fatty acids reach portal blood more directly."},{"label":"Lipoprotein lipase","detail":"Releases fatty acids from circulating triglycerides for uptake by muscle or adipose tissue. Insulin promotes storage."}]},"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Lipoprotein</th><th>Main job</th></tr></thead><tbody><tr><td>Chylomicron</td><td>Carries dietary fat</td></tr><tr><td>VLDL</td><td>Carries triglyceride made or packaged by the liver</td></tr><tr><td>LDL</td><td>Delivers cholesterol to tissues</td></tr><tr><td>HDL</td><td>Takes part in reverse cholesterol transport</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>“Chubby Very Large Dudes Hide.”</b> That gives the order from lowest density (mostly fat, biggest, floats) to highest density (mostly protein, smallest, sinks): <b>C</b>hylomicron, <b>V</b>LDL, <b>L</b>DL, <b>H</b>DL. More protein packed in means denser, and HDL, the densest, is the one carrying cholesterol away for disposal, the “good” direction.</div>"]},{"id":"sf6-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which enzyme releases fatty acids from circulating triglycerides so muscle and adipose tissue can take them up?","options":[{"label":"Pancreatic lipase","correct":false,"feedback":"Lipoprotein lipase acts on triglycerides in the blood."},{"label":"Lipoprotein lipase","correct":true,"feedback":"Lipoprotein lipase acts on triglycerides in the blood."},{"label":"Hormone-sensitive lipase","correct":false,"feedback":"Lipoprotein lipase acts on triglycerides in the blood."},{"label":"Carnitine acyl transferase","correct":false,"feedback":"Lipoprotein lipase acts on triglycerides in the blood."}]}},{"id":"sf6-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Chylomicrons mainly carry:","options":[{"label":"Dietary fat","correct":true,"feedback":"They package rebuilt triglycerides from the intestine."},{"label":"Cholesterol back to the liver","correct":false,"feedback":"They package rebuilt triglycerides from the intestine."},{"label":"Fatty acids bound to albumin","correct":false,"feedback":"They package rebuilt triglycerides from the intestine."},{"label":"Ketones","correct":false,"feedback":"They package rebuilt triglycerides from the intestine."}]}},{"id":"sf6-2","chapter":"Mobilization and beta-oxidation","title":"Mobilization and beta-oxidation","html":"<h3>Mobilization and beta-oxidation</h3><p>Hormonal signals activate lipolysis, releasing fatty acids and glycerol from stored triglycerides. Fatty acids travel bound to albumin, enter muscle, and are activated. Long-chain fatty acids use the carnitine shuttle to cross the inner mitochondrial membrane. Beta-oxidation removes two-carbon units as acetyl-CoA, which enters the Krebs cycle and electron transport chain. Fat oxidation is aerobic and relatively slow.</p>","visual":{"title":"Mobilization and beta-oxidation","kind":"sequence","items":[{"label":"Lipolysis","detail":"Hormonal signals activate hormone-sensitive lipase, releasing fatty acids and glycerol from stored triglycerides."},{"label":"Transport on albumin","detail":"Fatty acids circulate bound to albumin. Glycerol goes to the liver."},{"label":"Into muscle","detail":"Fatty acids enter muscle and are activated."},{"label":"Carnitine shuttle","detail":"Long-chain fatty acids cross the membrane using carnitine."},{"label":"Beta-oxidation","detail":"Two-carbon units are removed as acetyl CoA, which feeds the Krebs cycle and electron transport chain. Fat oxidation is aerobic and relatively slow."}]},"blocksHtml":["<div class=\"callout\">When carbohydrate availability is low and acetyl CoA accumulates, the liver produces ketone bodies. Ketosis is a normal pathway, but a carbohydrate-restricted athlete may replenish glycogen poorly and struggle to train well.</div>"]},{"id":"sf6-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What role does carnitine play in fat metabolism?","options":[{"label":"Transports fatty acids into the mitochondria","correct":true,"feedback":"The carnitine shuttle carries long-chain fatty acids across the inner mitochondrial membrane."},{"label":"Cleaves 2-carbon units in beta-oxidation","correct":false,"feedback":"The carnitine shuttle carries long-chain fatty acids across the inner mitochondrial membrane."},{"label":"Activates lipoprotein lipase","correct":false,"feedback":"The carnitine shuttle carries long-chain fatty acids across the inner mitochondrial membrane."},{"label":"Carries fatty acids in the blood","correct":false,"feedback":"The carnitine shuttle carries long-chain fatty acids across the inner mitochondrial membrane."}]}},{"id":"sf6-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The most common transport protein for fatty acids mobilized from adipose tissue is:","options":[{"label":"Albumin","correct":true,"feedback":"Free fatty acids circulate bound to albumin."},{"label":"Chylomicron","correct":false,"feedback":"Free fatty acids circulate bound to albumin."},{"label":"Carnitine","correct":false,"feedback":"Free fatty acids circulate bound to albumin."},{"label":"Glycerol","correct":false,"feedback":"Free fatty acids circulate bound to albumin."}]}},{"id":"sf6-3","chapter":"Exercise intensity and the “fat-burning zone”","title":"Exercise intensity and the “fat-burning zone”","html":"<h3>Exercise intensity and the “fat-burning zone”</h3><p>At rest and low intensity, fat supplies a high percentage of energy, but total expenditure may be low. Absolute fat oxidation often peaks at moderate intensity and drops as intensity rises because carbohydrate can provide ATP faster. The percentage of fat used during one workout does not determine long-term body-fat change; total energy balance and sustainable activity matter more.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Rest and low</b><p><b>High relative share</b> of energy from fat, but total energy expenditure is low.</p></div><div class=\"tabblk\"><b>Moderate steady state</b><p><b>Often the highest absolute fat oxidation.</b> Transport and oxidation remain slow.</p></div><div class=\"tabblk\"><b>High intensity</b><p><b>Lower relative and absolute share.</b> Carbohydrate can deliver ATP faster.</p></div><div class=\"tabblk\"><b>Endurance training</b><p><b>Improved mobilization, uptake and mitochondrial oxidation.</b> Carbohydrate remains important for hard work.</p></div>","<div class=\"callout\">The “fat-burning zone” does not guarantee greater fat loss. Long-term energy balance and total expenditure matter more than the percentage of fat used in one session. An RER near 0.70 reflects mostly fat oxidation.</div>"]},{"id":"sf6-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"As exercise intensity increases:","options":[{"label":"Relative fat oxidation increases","correct":false,"feedback":"Absolute fat oxidation rises to a moderate intensity, then falls as carbohydrate takes over."},{"label":"Absolute fat oxidation decreases","correct":false,"feedback":"Absolute fat oxidation rises to a moderate intensity, then falls as carbohydrate takes over."},{"label":"Absolute fat oxidation increases to a point, then decreases","correct":true,"feedback":"Absolute fat oxidation rises to a moderate intensity, then falls as carbohydrate takes over."},{"label":"Fat use is unchanged","correct":false,"feedback":"Absolute fat oxidation rises to a moderate intensity, then falls as carbohydrate takes over."}]}},{"id":"sf6-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What is the most important factor in fat loss?","options":[{"label":"Exercise intensity","correct":false,"feedback":"Long-term energy balance matters more than the fuel percentage in a single workout."},{"label":"Total caloric expenditure","correct":true,"feedback":"Long-term energy balance matters more than the fuel percentage in a single workout."},{"label":"Fuel source used during exercise","correct":false,"feedback":"Long-term energy balance matters more than the fuel percentage in a single workout."},{"label":"Avoiding alcohol only","correct":false,"feedback":"Long-term energy balance matters more than the fuel percentage in a single workout."}]}},{"id":"sf6-4","chapter":"Intake, timing, and supplements","title":"Intake, timing, and supplements","html":"<h3>Intake, timing, and supplements</h3><p>A practical benchmark is about 1.0 g/kg/day or 20–35% of energy after carbohydrate and protein needs are considered. Emphasize unsaturated fats, nuts, seeds, avocado, oils, and fish while limiting trans fat and excessive saturated fat. Large high-fat meals delay gastric emptying and may be uncomfortable before exercise. Carnitine, MCTs, and most “fat burners” have not shown reliable performance benefits.</p>","visual":{"title":"Intake, timing, and supplements","kind":"comparison","items":[{"label":"Large high-fat meal before competition","detail":"Delays gastric emptying and may be uncomfortable."},{"label":"Caffeine","detail":"Improves performance mainly through the central nervous system and lower perceived effort, not a big rise in fat oxidation."},{"label":"Carnitine supplements","detail":"Required for transport, but supplementing has not consistently improved endurance."},{"label":"MCTs","detail":"Enter blood quickly but have not produced reliable performance benefits."}]},"blocksHtml":["<div class=\"callout\"><b class=\"k\">Don't cut fat too far.</b> Very low fat intake can impair hormone production, reduce fat-soluble vitamin intake (A, D, E, K), lower HDL cholesterol, and limit restoration of intramuscular triglyceride. Fat is usually set last in a plan, once carbohydrate and protein targets are fixed, but it still needs a floor, not just a ceiling.</div>","<dl class=\"facts\"><div><dt>Prioritize</dt><dd>Unsaturated fats from oils, nuts, seeds, avocado and fatty fish.</dd></div><div><dt>Limit</dt><dd>Excessive saturated and trans fat.</dd></div><div><dt>Food labels</dt><dd>List total fat, saturated fat, trans fat and cholesterol.</dd></div><div><dt>Omega-3 supplements</dt><dd>Support health, but are not a substitute for an appropriate diet overall.</dd></div></dl>"]},{"id":"sf6-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Why would an endurance athlete limit fat in a pre-competition meal?","options":[{"label":"It causes dehydration","correct":false,"feedback":"Fat slows gastric emptying and can make a pre-event meal feel heavy."},{"label":"It delays gastric emptying","correct":true,"feedback":"Fat slows gastric emptying and can make a pre-event meal feel heavy."},{"label":"It blocks carbohydrate absorption","correct":false,"feedback":"Fat slows gastric emptying and can make a pre-event meal feel heavy."},{"label":"It raises RER","correct":false,"feedback":"Fat slows gastric emptying and can make a pre-event meal feel heavy."}]}},{"id":"sf6-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which of these is a documented risk of excessive fat restriction?","options":[{"label":"Lower HDL cholesterol and impaired hormone production","correct":true,"feedback":"Very low fat can also reduce fat-soluble vitamin intake and limit restoration of intramuscular triglyceride."},{"label":"Faster glycogen restoration","correct":false,"feedback":"Very low fat can also reduce fat-soluble vitamin intake and limit restoration of intramuscular triglyceride."},{"label":"Improved fat-soluble vitamin status","correct":false,"feedback":"Very low fat can also reduce fat-soluble vitamin intake and limit restoration of intramuscular triglyceride."},{"label":"Increased beta-oxidation capacity","correct":false,"feedback":"Very low fat can also reduce fat-soluble vitamin intake and limit restoration of intramuscular triglyceride."}]}},{"id":"sf6-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A client asks whether to keep exercise in the “fat-burning zone” to lose body fat.","text":"Explain that percentage of fat used in one workout does not decide fat loss. Total energy expenditure and long-term energy balance matter more, and harder sessions can burn more total energy."},{"label":"A 70 kg athlete eats 2,800 kcal/day. What does a 20 to 35% fat intake look like?","text":"20 to 35% of 2,800 kcal is 560 to 980 kcal, or about 62 to 109 g of fat (9 kcal/g). The 1.0 g/kg guideline gives about 70 g."}]}}],"flashcards":[{"front":"Fat energy","back":"9 kcal per gram."},{"front":"Saturated fatty acid","back":"No carbon-carbon double bonds."},{"front":"Cis vs trans","back":"Cis bends the chain. Trans keeps it straighter."},{"front":"Predominant dietary fat","back":"Triglycerides (about 95%)."},{"front":"Three major lipids","back":"Triglycerides, cholesterol (sterols), phospholipids."},{"front":"Chylomicron","back":"Carries dietary fat from the intestine."},{"front":"Lipoprotein lipase","back":"Frees fatty acids from circulating triglycerides."},{"front":"Hormone-sensitive lipase","back":"Breaks down stored triglycerides in adipocytes."},{"front":"Fatty acid transport in blood","back":"Bound to albumin."},{"front":"Carnitine shuttle","back":"Moves long-chain fatty acids into the mitochondria."},{"front":"Beta-oxidation","back":"Removes two-carbon units as acetyl CoA."},{"front":"Ketone bodies","back":"Made by the liver when carbohydrate is low and acetyl CoA accumulates."},{"front":"Absolute fat oxidation vs intensity","back":"Rises to a moderate intensity, then falls."},{"front":"Daily fat guideline","back":"About 1.0 g/kg/day, or roughly 20 to 35% of energy."},{"front":"Caffeine's likely mechanism","back":"Central nervous system effects and reduced perceived effort."},{"front":"Risks of too-low fat intake","back":"Impaired hormone production, lower fat-soluble vitamin intake, lower HDL, poorer intramuscular triglyceride restoration."}],"quiz":[{"q":"Name the three major lipids in human nutrition.","o":["Glycerol, cholesterol, ketones","Medium chain triglycerides, carnitine, cholesterol","Cholesterol, lecithin, phospholipids","Triglycerides, cholesterol, phospholipids"],"a":3,"e":"Triglycerides, sterols such as cholesterol, and phospholipids are the major lipid classes."},{"q":"What type of fat cannot be broken down and used for energy because of its chemical structure?","o":["Cholesterol","Medium-chain triglyceride","16- or 18-carbon fatty acid","Saturated fatty acid"],"a":0,"e":"The fused-ring structure of cholesterol is not oxidized as an energy substrate."},{"q":"The predominant fat in food and in the body is:","o":["cholesterol.","triglycerides.","lipoproteins.","lecithin."],"a":1,"e":"Triglycerides make up most dietary and stored body fat."},{"q":"_____ is an example of a food containing predominantly saturated fat.","o":["Skim milk","Corn oil","Margarine","Butter"],"a":3,"e":"Butter contains a high proportion of saturated fatty acids."},{"q":"_____ is an example of a food containing predominantly monounsaturated fat.","o":["Olive oil","Corn oil","Hamburger","Butter"],"a":0,"e":"Olive oil is rich in monounsaturated fatty acids."},{"q":"The appropriate amount of fat for training and performance depends on:","o":["overall energy need.","macronutrient balance.","proportion of saturated to unsaturated fat.","a and b","all of the above"],"a":3,"e":"The course-confirmed answer is a and b: overall energy need and macronutrient balance. Saturated-to-unsaturated proportion is a separate consideration, which is why the broader \"all of the above\" is not the keyed answer."},{"q":"Why would an endurance athlete limit the amount of fat in a pre-competition meal?","o":["Contributes to faster dehydration","Delays gastric emptying","Slows the metabolism of carbohydrate","All of the above"],"a":1,"e":"Fat slows gastric emptying and may make a pre-event meal feel heavy."},{"q":"How are dietary triglycerides absorbed in the gastrointestinal tract?","o":["Intact since they cross the mucosal cells easily","As long chains of fatty acids because chain length enhances absorption","As small components that will be re-packaged as triglycerides in the mucosal cell","By attaching to lipoprotein carriers"],"a":2,"e":"Digestion yields smaller components that intestinal cells reassemble into triglycerides."},{"q":"_____ absorbed directly into the blood from the intestinal mucosa without being incorporated into a chylomicron.","o":["Medium-chain triglycerides are","Long-chain triglycerides are","Low-density lipoprotein is","Cholesterol is"],"a":0,"e":"Medium-chain fatty acids enter portal blood more directly than long-chain fatty acids."},{"q":"The enzyme _____ stimulates the release of the fatty acids from the triglyceride in the blood so uptake by adipose and muscle cells can take place.","o":["pancreatic lipase","lipoprotein lipase","hormone-sensitive lipase (HSL)","carnitine acyl transferase (CAT)"],"a":1,"e":"Lipoprotein lipase releases fatty acids from circulating triglycerides."},{"q":"What is esterification?","o":["Another term for beta-oxidation","The production of ketones from fat","The utilization of fat by slow-twitch muscle fibers","The process of triglyceride formation"],"a":3,"e":"Esterification joins glycerol and fatty acids to form triglycerides."},{"q":"Fat storage in skeletal muscle primarily occurs in:","o":["slow-twitch muscle fibers.","fast-twitch muscle fibers.","subcutaneous muscle fibers.","visceral muscle fibers."],"a":0,"e":"Highly aerobic slow-twitch fibres contain more intramuscular triglyceride."},{"q":"How many kilocalories are in each gram of fat?","o":["2","4","7","9"],"a":3,"e":"Fat provides about 9 kcal per gram."},{"q":"How does the energy content (kcal/g) of fat compare to the energy content of alcohol?","o":["Fat and alcohol have an equal energy content","Alcohol has a higher energy content than fat","Fat has a higher energy content than alcohol"],"a":2,"e":"Fat provides about 9 kcal/g while alcohol provides about 7 kcal/g."},{"q":"The human body normally stores approximately how much energy as fat?","o":["100 kcal","1,000 kcal","10,000 kcal","100,000 kcal"],"a":3,"e":"Body fat provides a very large energy reserve, commonly estimated near 100,000 kcal."},{"q":"With the onset of moderate-intensity, steady-state exercise, approximately how long does it take for fat oxidation to reach its maximal rate of activity?","o":["1 to 2 minutes","10 to 20 minutes","30 to 45 minutes","At least one hour"],"a":1,"e":"Fat mobilization and oxidation rise more slowly than carbohydrate use."},{"q":"The enzyme that stimulates the breakdown of triglycerides and the release of fatty acids from adipocytes is:","o":["pancreatic lipase.","lipoprotein lipase.","hormone-sensitive lipase.","carnitine acyl transferase."],"a":2,"e":"Hormone-sensitive lipase mobilizes stored triglycerides in adipocytes."},{"q":"When insulin levels are elevated, fat storage is:","o":["inhibited.","enhanced.","unaffected."],"a":1,"e":"Insulin promotes storage and suppresses fat mobilization."},{"q":"When the body is stressed by exercise, fat stored in adipocytes is:","o":["mobilized.","demobilized.","unaffected."],"a":0,"e":"Exercise hormones stimulate lipolysis and release fatty acids."},{"q":"Fat is stored in adipocytes and muscle cells primarily as:","o":["amino acids.","glycogen.","triglycerides.","glucocorticoids."],"a":2,"e":"The primary storage form of fat is triglyceride."},{"q":"After lipolysis, what happens to the glycerol portion of the triglyceride?","o":["Remains in the adipose tissue","Goes to muscle cells to be used as energy","Goes to liver to be used in gluconeogenesis or triglyceride re-synthesis","Goes to the kidney to be excreted in urine"],"a":2,"e":"Glycerol travels to the liver and can support glucose production or triglyceride synthesis."},{"q":"What is the most common transport protein for fatty acids that have been mobilized from adipose tissue?","o":["Albumin","Branched chained amino acids","Carnitine","Glycerol"],"a":0,"e":"Free fatty acids circulate bound to albumin."},{"q":"Why is beta-oxidation important?","o":["Allows excess fatty acids to be dissipated as heat","Activates enzymes and hormones that are needed for fat metabolism","Stimulates the release of glucose from muscle glycogen","Prepares fatty acids for ATP production"],"a":3,"e":"Beta-oxidation removes two-carbon units that form acetyl CoA for aerobic ATP production."},{"q":"What is ketosis?","o":["Medical condition associated with severe obesity","Increased fatty acid oxidation resulting in an abnormal increase in ketone bodies","Alternative term for anaerobic glycolysis","Production of amino acids from fatty acids under stressful conditions"],"a":1,"e":"Ketosis is elevated ketone-body production associated with accelerated fat oxidation and low carbohydrate availability."},{"q":"Ketoacidosis is a condition in which:","o":["blood pH is more acidic than body tissues.","blood pH is more basic than body tissues."],"a":0,"e":"Excess ketone acids can lower blood pH."},{"q":"Why is a carbohydrate-restricted diet that results in ketosis not recommended for non-diabetic athletes?","o":["The risk of developing ketoacidosis is too great and potentially fatal","The majority of weight lost would be lost as water and skeletal muscle","The ability to train would be diminished due to inadequate replenishment of glycogen stores","All of the above"],"a":2,"e":"Low carbohydrate availability limits glycogen restoration and can reduce training quality."},{"q":"As exercise intensity increases:","o":["relative fat oxidation increases.","absolute fat oxidation decreases.","relative fat oxidation increases to a point, then decreases.","absolute fat oxidation increases to a point, then decreases."],"a":3,"e":"Absolute fat oxidation rises to a moderate intensity, then falls as carbohydrate use predominates."},{"q":"The point of highest relative fat metabolism (oxidation) occurs:","o":["at an exercise intensity equal to maximal oxygen consumption (VO2max).","at an exercise intensity equal to the lactate threshold.","at an exercise intensity in the “fat burning zone.”","while taking a nap."],"a":3,"e":"The course-confirmed answer is at rest (\"while taking a nap\"). The percentage of energy from fat is actually highest at rest and low intensities; it is absolute fat oxidation (grams burned per minute) that peaks at a moderate intensity, often around what people call the \"fat burning zone,\" before falling as intensity rises further. Relative share and absolute amount peak at different intensities, and this question is asking about the relative share."},{"q":"What is the most important factor in weight (fat) loss?","o":["Exercise intensity","Total caloric expenditure","Use of fat as a fuel source during exercise","Elimination of calories derived from alcohol"],"a":1,"e":"Long-term energy balance matters more than the percentage of fat oxidized during one session."},{"q":"What is the mechanism by which caffeine most likely improves endurance performance?","o":["Spares muscle glycogen","Enhances the release of muscle and liver glycogen","Increases the oxidation of fatty acids during exercise","Decreases perception of exertion"],"a":3,"e":"Caffeine primarily acts through the central nervous system and can lower perceived effort."},{"q":"What role does carnitine play in fat metabolism?","o":["Transports fatty acids into the mitochondria","Cleaves 2-unit carbons during beta-oxidation","Activates lipoprotein lipase","Carries free fatty acids in the blood"],"a":0,"e":"The carnitine shuttle transports long-chain fatty acids across the inner mitochondrial membrane."},{"q":"Are carnitine supplements at doses of 2-4 g/day considered safe?","o":["No, there are documented side effects at such doses","Yes, such doses are considered safe"],"a":1,"e":"The course describes these doses as generally safe."},{"q":"Given the current body of research, are carnitine supplements effective for improving endurance performance?","o":["No. Evidence of improved endurance performance is lacking.","Yes. There is scientific consensus that endurance performance is improved."],"a":0,"e":"Research has not established an endurance-performance benefit from carnitine supplements."},{"q":"In general, what amount of fat per day is recommended to athletes in training who are not trying to lose weight?","o":["0.5 g/kg","1.0 to 3.0 g/kg","3.0 to 5.0 g/kg","5.0 to 7.0 g/kg"],"a":1,"e":"The course presents a broad range centered near 1 g/kg/day and consistent with 20–35% of energy."},{"q":"Leafy green vegetables, fatty fish, and flaxseed are sources omega-3 fatty acids.","o":["True","False"],"a":0,"e":"These foods can contribute ALA, EPA, or DHA depending on the source."},{"q":"Plants do not contain cholesterol but they do contain other sterols.","o":["True","False"],"a":0,"e":"Cholesterol is animal-derived, while plants contain phytosterols."},{"q":"The digestion, absorption, and transportation of dietary fat is complicated because the molecules are large and do not mix well with water.","o":["True","False"],"a":0,"e":"Fat requires bile, enzymes, micelles, and lipoprotein transport because it is hydrophobic."},{"q":"The majority of energy for low- to moderate-intensity exercise will come from triglycerides stored in adipose and muscle cells.","o":["True","False"],"a":0,"e":"Fat contributes substantially during low- and moderate-intensity aerobic exercise."},{"q":"When triglycerides are mobilized from storage in adipocytes, they must be attached to a carrier before they can be transported throughout the blood to skeletal muscle for use as energy.","o":["True","False"],"a":0,"e":"Mobilized fatty acids travel in blood bound primarily to albumin."},{"q":"Exercise results in a loss of carnitine in the muscle.","o":["True","False"],"a":1,"e":"Exercise shifts carnitine between free and acylated forms but does not cause a meaningful loss from muscle."}]},{"n":7,"title":"Water and Electrolytes","kicker":"Understand body-water compartments, fluid movement, sweat losses, temperature regulation, hydration assessment and individualized replacement before, during and after exercise.","steps":[{"id":"sf7-0","chapter":"Body water and fluid compartments","title":"Body water and fluid compartments","html":"<h3>Body-water compartments</h3><p>Water makes up a large and variable portion of body mass. Intracellular fluid is inside cells; extracellular fluid includes plasma and interstitial fluid. Electrolytes help maintain fluid distribution: potassium is the major intracellular cation, while sodium is the major extracellular cation. Water supports circulation, nutrient transport, waste removal, chemical reactions, lubrication, and temperature control.</p><h3>Water balance and regulation</h3><p>Intake comes from beverages, food, and metabolic water. Loss occurs through urine, sweat, respiration, and feces. Osmolality and blood volume influence thirst and hormones such as antidiuretic hormone and aldosterone. The kidneys adjust water and sodium excretion. Balance is dynamic, so a single urine sample or thirst rating cannot describe every aspect of hydration.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Euhydration</td><td>Adequate water for physiological demands</td></tr><tr><td>Hypohydration</td><td>Insufficient body-water volume</td></tr><tr><td>Dehydration</td><td>The process of losing body water</td></tr><tr><td>Hyperhydration</td><td>Temporary excess body water</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>“SOdium stays OUTside; Potassium stays IN.”</b> Sodium and OUT both have that round “O” shape to picture side by side. Potassium's chemical symbol, K, can stand for “Keeps to the cell” (inside).</div>"]},{"id":"sf7-0-s0","title":"Where is it concentrated?","teach":[],"act":{"type":"sort","prompt":"Where is it concentrated?","categories":["Intracellular","Extracellular"],"items":[{"label":"Potassium (major cation)","category":0,"feedback":"Potassium is the main intracellular cation."},{"label":"Sodium (major cation)","category":1,"feedback":"Sodium is the main extracellular cation."},{"label":"Blood plasma","category":1,"feedback":"Plasma is part of extracellular fluid."},{"label":"Interstitial fluid","category":1,"feedback":"The fluid surrounding cells is extracellular."},{"label":"Most of the body’s water","category":0,"feedback":"Intracellular fluid holds the largest share."}]}},{"id":"sf7-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"What is the primary cation in extracellular fluid?","options":[{"label":"Sodium","correct":true,"feedback":"Sodium is the main extracellular cation. Potassium is the main intracellular cation."},{"label":"Potassium","correct":false,"feedback":"Sodium is the main extracellular cation. Potassium is the main intracellular cation."},{"label":"Calcium","correct":false,"feedback":"Sodium is the main extracellular cation. Potassium is the main intracellular cation."},{"label":"Chloride","correct":false,"feedback":"Sodium is the main extracellular cation. Potassium is the main intracellular cation."}]}},{"id":"sf7-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"If intracellular fluid osmolarity is higher than the blood’s, the blood is:","options":[{"label":"Isotonic to the cells","correct":false,"feedback":"Water moves toward the more concentrated intracellular fluid."},{"label":"Hypotonic to the cells","correct":true,"feedback":"Water moves toward the more concentrated intracellular fluid."},{"label":"Hypertonic to the cells","correct":false,"feedback":"Water moves toward the more concentrated intracellular fluid."},{"label":"Unrelated to the cells","correct":false,"feedback":"Water moves toward the more concentrated intracellular fluid."}]}},{"id":"sf7-1","chapter":"Sweating and thermoregulation","title":"Sweating and thermoregulation","html":"<h3>Sweating and thermoregulation</h3><p>Exercise produces heat. Skin blood flow and sweat evaporation help transfer that heat to the environment. Evaporation, not sweat dripping from the skin, provides cooling. Heat and humidity, clothing, body size, metabolic rate, acclimatization, and airflow change sweat rate and heat strain. High humidity reduces evaporation even when sweating is heavy.</p><h3>Consequences of dehydration</h3><p>A fluid deficit reduces plasma volume, increases cardiovascular strain, impairs heat dissipation, and raises perceived effort. Performance effects become more likely as dehydration grows, especially during endurance activity in heat. Symptoms are not specific, so headache, fatigue, nausea, or poor performance should be interpreted with the full context. Severe heat illness requires urgent medical action.</p>","visual":{"title":"Sweating and thermoregulation","kind":"sequence","items":[{"label":"Exercise makes heat","detail":"Metabolic heat production rises with exercise."},{"label":"Skin blood flow increases","detail":"Blood carries heat to the skin."},{"label":"Sweat is secreted","detail":"Sweat glands release water and electrolytes onto the skin."},{"label":"Evaporation cools","detail":"Evaporation, not dripping, removes heat. High humidity, protective gear and moisture-trapping clothing reduce evaporation."}]},"blocksHtml":["<div class=\"callout\">Hypohydration lowers plasma volume, raises cardiovascular strain and core temperature, and can reduce endurance performance. Severe heat illness requires urgent medical action.</div>"]},{"id":"sf7-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"When environmental conditions are more humid, sweating is:","options":[{"label":"More effective for cooling","correct":false,"feedback":"High humidity reduces evaporation even when sweating is heavy."},{"label":"Less effective for cooling","correct":true,"feedback":"High humidity reduces evaporation even when sweating is heavy."},{"label":"Unaffected","correct":false,"feedback":"High humidity reduces evaporation even when sweating is heavy."},{"label":"Stopped","correct":false,"feedback":"High humidity reduces evaporation even when sweating is heavy."}]}},{"id":"sf7-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which process actually cools the body?","options":[{"label":"Sweat dripping off the skin","correct":false,"feedback":"Evaporation of sweat removes heat."},{"label":"Evaporation of sweat","correct":true,"feedback":"Evaporation of sweat removes heat."},{"label":"Drinking cold fluid only","correct":false,"feedback":"Evaporation of sweat removes heat."},{"label":"Increased breathing rate","correct":false,"feedback":"Evaporation of sweat removes heat."}]}},{"id":"sf7-2","chapter":"Assessing hydration and sweat rate","title":"Assessing hydration and sweat rate","html":"<h3>Assessing hydration and sweat rate</h3><p>Useful field measures include body-mass change, fluid intake, urine output, urine colour, thirst, and environmental conditions. Sweat rate can be estimated from pre- and post-session body mass plus fluid consumed and urine produced. One kilogram of mass change is approximately one litre of water. Repeat testing in different weather and sessions because sweat rate varies.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Urine colour</dt><dd>Practical but least accurate. Use the first void of the day.</dd></div><div><dt>Body-weight change</dt><dd>Useful field estimate of fluid loss.</dd></div><div><dt>Laboratory methods</dt><dd>Plasma osmolarity, isotope dilution, 24-hour urine.</dd></div></dl>"]},{"id":"sf7-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"One litre of water weighs approximately:","options":[{"label":"One pound","correct":false,"feedback":"That is why acute body-weight change estimates fluid loss."},{"label":"One kilogram","correct":true,"feedback":"That is why acute body-weight change estimates fluid loss."},{"label":"Two pounds","correct":false,"feedback":"That is why acute body-weight change estimates fluid loss."},{"label":"Two kilograms","correct":false,"feedback":"That is why acute body-weight change estimates fluid loss."}]}},{"id":"sf7-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"An athlete weighs 163 lb before exercise and 161 lb after. The 2 lb loss represents mostly:","options":[{"label":"Fat","correct":false,"feedback":"Acute weight change during exercise is mainly water."},{"label":"Muscle mass","correct":false,"feedback":"Acute weight change during exercise is mainly water."},{"label":"Fluid","correct":true,"feedback":"Acute weight change during exercise is mainly water."}]}},{"id":"sf7-3","chapter":"Before, during, and after exercise","title":"Before, during, and after exercise","html":"<h3>Before, during, and after exercise</h3><p>Begin activity normally hydrated. The chapter uses about 5–10 mL/kg in the two to four hours before exercise, with additional fluid when urine remains dark or output is low. During exercise, use an individualized plan that limits excessive dehydration without producing weight gain. Afterward, about 1.25–1.5 L per kilogram lost helps replace the deficit and ongoing urine losses.</p>","visual":null,"blocksHtml":[]},{"id":"sf7-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"To rehydrate after exercise, an athlete should drink about how much per kilogram of weight lost?","options":[{"label":"0.5 L","correct":false,"feedback":"More than the measured loss, because urine production continues during recovery."},{"label":"1.25 to 1.5 L","correct":true,"feedback":"More than the measured loss, because urine production continues during recovery."},{"label":"3 L","correct":false,"feedback":"More than the measured loss, because urine production continues during recovery."},{"label":"0.1 L","correct":false,"feedback":"More than the measured loss, because urine production continues during recovery."}]}},{"id":"sf7-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The current ACSM recommendation for fluid intake during exercise is to:","options":[{"label":"Drink 50 to 150 mL every 15 to 20 minutes","correct":false,"feedback":"Plans should reflect sweat rate, duration, clothing and environment."},{"label":"Drink 5 to 10 mL/kg each hour","correct":false,"feedback":"Plans should reflect sweat rate, duration, clothing and environment."},{"label":"Drink as much as possible","correct":false,"feedback":"Plans should reflect sweat rate, duration, clothing and environment."},{"label":"Develop a customized plan based on sweat rate","correct":true,"feedback":"Plans should reflect sweat rate, duration, clothing and environment."}]}},{"id":"sf7-4","chapter":"Sodium and hyponatremia","title":"Sodium and hyponatremia","html":"<h3>Sodium and hyponatremia</h3><p>Sodium losses vary with sweat volume and concentration. Long-duration exercise, heavy salty sweating, and limited recovery may require sodium-containing foods or beverages. Exercise-associated hyponatremia usually involves drinking beyond losses, which dilutes blood sodium; sodium intake alone cannot make unlimited drinking safe. Avoid routine weight gain during endurance events.</p>","visual":{"title":"Sodium and hyponatremia","kind":"sequence","items":[{"label":"Drinking beyond losses","detail":"An endurance athlete drinks more than they sweat."},{"label":"Sodium is diluted","detail":"Blood sodium concentration falls."},{"label":"Hyponatremia","detail":"Exercise-associated hyponatremia becomes especially concerning near or below 130 mmol/L."},{"label":"Prevention","detail":"Avoid fluid overload, avoid routine weight gain during events, and replace sodium when sweat losses are large."}]},"blocksHtml":["<dl class=\"facts\"><div><dt>Sodium rule of thumb</dt><dd>Heavy salty sweaters may need about 0.5 g sodium per hour.</dd></div><div><dt>Cramps</dt><dd>Most exercise-associated muscle cramps are not caused solely by dehydration or electrolyte imbalance.</dd></div><div><dt>Heat cramps</dt><dd>Whole-body cramping in salty sweaters can involve large fluid and sodium losses.</dd></div></dl>"]},{"id":"sf7-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Exercise-associated hyponatremia usually involves:","options":[{"label":"Drinking beyond losses, which dilutes blood sodium","correct":true,"feedback":"Prolonged, excessive drinking dilutes sodium."},{"label":"Eating too much salt","correct":false,"feedback":"Prolonged, excessive drinking dilutes sodium."},{"label":"Too little fluid","correct":false,"feedback":"Prolonged, excessive drinking dilutes sodium."},{"label":"Breathing too fast","correct":false,"feedback":"Prolonged, excessive drinking dilutes sodium."}]}},{"id":"sf7-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"True or false: sodium intake alone makes unlimited drinking safe.","options":[{"label":"True","correct":false,"feedback":"Sodium cannot make overdrinking safe. Avoid drinking beyond losses."},{"label":"False","correct":true,"feedback":"Sodium cannot make overdrinking safe. Avoid drinking beyond losses."}]}},{"id":"sf7-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"An athlete weighs 72.0 kg before a run and 70.9 kg after, drinking 0.4 L and passing no urine in 60 minutes. What is the sweat rate?","text":"72.0 − 70.9 + 0.4 = 1.5 L in 60 minutes, or about 1.5 L/h."},{"label":"A 65 kg athlete lost 1.0 kg in training. How much should they drink to rehydrate?","text":"About 1.25 to 1.5 L, replacing sodium with food or drinks."}]}}],"flashcards":[{"front":"Body water share","back":"About 60% of adult body weight."},{"front":"Largest fluid compartment","back":"Intracellular fluid."},{"front":"Main extracellular cation","back":"Sodium."},{"front":"Main intracellular cation","back":"Potassium."},{"front":"Euhydration","back":"Adequate water for physiological demands."},{"front":"Hypohydration","back":"Insufficient body water."},{"front":"What cools during exercise","back":"Evaporation of sweat."},{"front":"Effect of humidity","back":"Reduces evaporation, so sweating cools less."},{"front":"Sweat rate in heat","back":"Roughly 1 to 2 L/h, sometimes higher."},{"front":"1 kg of weight change","back":"About 1 L of water."},{"front":"Pre-exercise fluid","back":"About 5 to 10 mL/kg in the 2 to 4 hours before."},{"front":"Rehydration","back":"About 1.25 to 1.5 L per kg lost."},{"front":"Hyponatremia","back":"Low plasma sodium; especially concerning near or below 130 mmol/L."},{"front":"Main cause of exercise-associated hyponatremia","back":"Drinking beyond losses."}],"quiz":[{"q":"On average, an adult’s body contains approximately _____% water (by weight):","o":["20","40","60","8"],"a":2,"e":""},{"q":"In which compartment is the largest amount of body fluid stored?","o":["Blood plasma","Interstitial fluid","Extracellular fluid","Intracellular fluid"],"a":3,"e":""},{"q":"The major component of extracellular fluid is:","o":["blood plasma.","interstitial fluid.","lymphatic fluid.","transcellular fluid."],"a":1,"e":""},{"q":"What is interstitial fluid?","o":["Fluid surrounding the cells","Any fluid associated with the cardiovascular system","Any fluid that does not contain cations","All of the above"],"a":0,"e":""},{"q":"Which of the following is an example of water shifting due to hydrostatic pressure?","o":["Loss of plasma volume due to heavy sweating","Swelling of the feet and ankles when standing for a long period of time","Swelling of cells due to high intracellular sodium concentrations","All of the above"],"a":1,"e":""},{"q":"What is the primary cation in extracellular fluid?","o":["Sodium","Potassium","Calcium","Chloride"],"a":0,"e":""},{"q":"If the osmolarity of intracellular fluid (ICF) is higher than that of extracellular fluid (ECF), what is the tonicity of the blood?","o":["The blood is isotonic to the ICF.","The blood is hypotonic to the ICF.","The blood is hypertonic to the ICF.","The blood is hypertonic to the ECF."],"a":1,"e":""},{"q":"When an athlete sweats heavily, what happens to the osmolarity of the blood?","o":["Osmolarity increases","Osmolarity decreases","Osmolarity stays the same"],"a":0,"e":""},{"q":"What is insensible water loss?","o":["Loss of water as a result of sweating but not cooling in humid conditions","Large losses of water due to excessive sweating","Loss of water from the body that is not noticeable","All of the above"],"a":2,"e":""},{"q":"Which accounts for the largest amount of water loss in a sedentary individual?","o":["Feces","Lungs","Insensible perspiration","Urine"],"a":3,"e":""},{"q":"Which accounts for the largest amount of water loss in an athlete exercising in the heat?","o":["Feces","Lungs","Skin","Urine"],"a":2,"e":""},{"q":"Hypohydration initially occurs in:","o":["extracellular fluid.","intracellular fluid."],"a":0,"e":""},{"q":"The Dietary Reference Intake (DRI) for sodium is 1,500 mg daily, however, these recommendations do NOT apply to:","o":["men and women under the age of 50.","sedentary individuals.","lightly active individuals.","highly active individuals who sweat heavily."],"a":3,"e":""},{"q":"Which of the following is a true statement regarding sodium excretion?","o":["Urinary sodium excretion is precisely controlled by the kidneys.","If sodium intake is high, most of the excess sodium is excreted via sweat.","If sodium intake is high, most of the excess sodium is excreted via the feces.","Excess sodium intake is difficult to excrete and any excess is stored in the liver."],"a":0,"e":""},{"q":"Which of the following foods has a high potassium content?","o":["Banana","Orange juice","Avocado","All of the above"],"a":3,"e":""},{"q":"To avoid a moderate potassium deficiency, it is recommended that individuals, including athletes, should:","o":["use a salt substitute (potassium chloride) daily.","avoid exercising in the heat.","consume a variety of fruits and vegetables daily.","all of the above"],"a":2,"e":""},{"q":"When environmental conditions are more humid, sweating is:","o":["a more effective means of regulating body temperature.","a less effective means of regulating body temperature.","not affected by the change."],"a":1,"e":""},{"q":"Wearing uniforms and protective gear while exercising in the heat typically:","o":["keeps the sun off the skin and prevents body temperature from rising.","restricts the evaporation of sweat and results in body temperature rising.","has little effect on body temperature."],"a":1,"e":""},{"q":"Approximately how much sweat can an athlete lose each hour when exercising in a hot and humid environment?","o":["1 to 2 milliliter per hour","1 to 2 liters per hour","1 to 2 gallons per hour","2 to 5 cups per hour"],"a":1,"e":""},{"q":"When an athlete is hypohydrated:","o":["core temperature during exercise is higher than when euhydrated.","blood volume is lower than when euhydrated.","endurance exercise performance is lower than when euhydrated.","all of the above"],"a":3,"e":""},{"q":"The compound present in the largest amount in sweat is:","o":["ammonia.","sodium.","calcium.","lactate."],"a":1,"e":""},{"q":"Athletes participating in which sport need to be the most concerned about consuming fluids that contain sodium to offset the amount being lost in sweat?","o":["Sprint swimming","Field events (e.g., shot putting, high jumping)","10 km running","Marathon running"],"a":3,"e":""},{"q":"Scientific studies of exercise-associated muscle cramping (EAMC) have concluded that this condition is:","o":["almost always a result of dehydration.","almost always a result of electrolyte imbalance.","almost always a result of a combination of dehydration and electrolyte imbalance.","not typically a result of dehydration or electrolyte imbalance."],"a":3,"e":""},{"q":"Heat cramps (total body cramping when exercising in the heat) in athletes who are “salty sweaters” appear to be caused by:","o":["dehydration.","sodium depletion.","large losses of fluid and sodium.","non-nutritional factors."],"a":2,"e":""},{"q":"The least accurate but most practical method of monitoring hydration status in athletes is:","o":["24-hour urine volume.","urine color.","plasma osmolarity.","isotope dilution."],"a":1,"e":""},{"q":"When comparing urine to a color chart, it is recommended that athletes use urine obtained from:","o":["the first void (urination) of the day.","the second void (urination) of the day.","the last void (urination) before going to bed for the night.","any void (urination) during the day."],"a":0,"e":""},{"q":"One liter of water weighs approximately:","o":["one pound.","one kilogram.","two pounds.","two kilograms."],"a":1,"e":""},{"q":"An athlete’s pre-exercise weight is 163 pounds. His post-exercise weight is 161 pounds. What does this two (2) pound weight loss represent?","o":["Fat loss","Loss of muscle mass","Fluid loss"],"a":2,"e":""},{"q":"The term voluntary dehydration refers to athletes engaged in exercise who are:","o":["assigned to the control group in research studies examining fluid intake.","not within five pounds of their pre-exercise weight.","testing the precision of their thirst mechanism.","unable or unwilling to consume sufficient fluid to offset fluid loss."],"a":3,"e":""},{"q":"The current American College of Sports Medicine recommendation for fluid intake during exercise is:","o":["50-150 ml every 15 to 20 minutes.","5-10 ml/kg each hour.","to drink as frequently and as much as possible.","to develop a customized fluid plan that considers sweat rate."],"a":3,"e":""},{"q":"As a rule of thumb, athletes who sweat heavily and lose large amounts of sodium should consume approximately _____ g of sodium per hour.","o":["0.25","0.5","1","1.5"],"a":1,"e":""},{"q":"Darker urine color generally indicates that the athlete is hypohydrated.","o":["True","False"],"a":0,"e":""},{"q":"Good advice to athletes who exercise in hot, humid conditions is to drink as much as possible before and during exercise.","o":["True","False"],"a":1,"e":""},{"q":"It is unsafe to make a blanket recommendation for fluid intake during exercise for all members of the same team.","o":["True","False"],"a":0,"e":""},{"q":"As a rule of thumb, “a pint a pound” is enough to replace water losses in athletes who exercise in the heat.","o":["True","False"],"a":1,"e":""}]},{"n":8,"title":"Vitamins","kicker":"Classify vitamins by solubility and function, connect them to energy metabolism and blood formation, and judge food and supplement sources by need, safety and evidence.","steps":[{"id":"sf8-0","chapter":"How vitamins differ from energy nutrients","title":"How vitamins differ from energy nutrients","html":"<h3>How vitamins differ from energy nutrients</h3><p>Vitamins are organic compounds needed in small amounts for normal metabolism. They do not provide calories, but many act as coenzymes that help release or transfer energy from carbohydrate, fat, and protein. Requirements can rise when food intake and metabolic work rise, yet athletes who eat enough varied food usually obtain adequate amounts without high-dose supplements.</p>","visual":null,"blocksHtml":["<p>Most vitamins work as <b>coenzymes</b>: small helper molecules that attach to an enzyme and let it do its job, often by carrying electrons, hydrogen atoms, or small chemical groups from one reaction to the next. Without the coenzyme, the enzyme it partners with is inactive even if every other ingredient for the reaction is present. This is why a true vitamin deficiency can slow down energy metabolism, red blood cell production, or tissue repair without the vitamin itself ever being “burned” for fuel.</p>","<div class=\"callout\">The practical divide that runs through this whole unit is <b>solubility</b>: fat-soluble vitamins travel and store with body fat, so they build up and pose a real overdose risk; water-soluble vitamins mostly do not store well and are usually excreted in urine when intake exceeds need, so daily or near-daily intake matters more for most of them.</div>","<div class=\"mn-html\"><span>Remember it</span><b>“All Dogs Eat Kibble.”</b> A, D, E, K, the four fat-soluble vitamins, and nothing else. Everything not on that four-letter list (all the Bs and C) is water soluble by default.</div>"]},{"id":"sf8-0-s0","title":"Fat soluble or water soluble?","teach":[],"act":{"type":"sort","prompt":"Fat soluble or water soluble?","categories":["Fat soluble","Water soluble"],"items":[{"label":"Vitamin A","category":0,"feedback":"A, D, E and K are fat soluble."},{"label":"Vitamin D","category":0,"feedback":"Fat soluble."},{"label":"Vitamin E","category":0,"feedback":"Fat soluble."},{"label":"Vitamin K","category":0,"feedback":"Fat soluble."},{"label":"Vitamin C","category":1,"feedback":"Water soluble."},{"label":"Thiamin (B1)","category":1,"feedback":"B vitamins are water soluble."},{"label":"Vitamin B12","category":1,"feedback":"Water soluble, though it can be stored."}]}},{"id":"sf8-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The amount of energy provided by a B-complex vitamin is:","options":[{"label":"4 kcal","correct":false,"feedback":"Vitamins provide no calories. B vitamins act as coenzymes."},{"label":"7 kcal","correct":false,"feedback":"Vitamins provide no calories. B vitamins act as coenzymes."},{"label":"0 kcal","correct":true,"feedback":"Vitamins provide no calories. B vitamins act as coenzymes."}]}},{"id":"sf8-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The vitamin that acts like a hormone is:","options":[{"label":"Vitamin A","correct":false,"feedback":"Vitamin D regulates calcium and bone metabolism much like a hormone."},{"label":"Vitamin C","correct":false,"feedback":"Vitamin D regulates calcium and bone metabolism much like a hormone."},{"label":"Vitamin D","correct":true,"feedback":"Vitamin D regulates calcium and bone metabolism much like a hormone."},{"label":"Vitamin E","correct":false,"feedback":"Vitamin D regulates calcium and bone metabolism much like a hormone."}]}},{"id":"sf8-1","chapter":"Fat-soluble vitamins","title":"Fat-soluble vitamins","html":"<h3>Fat-soluble vitamins</h3><p>Vitamins A, D, E, and K are absorbed with dietary fat and can be stored. Vitamin A supports vision, epithelial tissue, immunity, and cell differentiation. Vitamin D regulates calcium and bone metabolism and has broader physiological roles. Vitamin E protects lipid membranes from oxidation. Vitamin K is required for blood-clotting proteins and participates in bone metabolism. Storage increases the risk of toxicity from excessive supplements.</p>","visual":{"title":"Fat-soluble vitamins","kind":"sequence","items":[{"label":"Eaten with fat","detail":"Fat-soluble vitamins are released from food and mix into fat droplets in the small intestine, alongside dietary fat."},{"label":"Packaged for absorption","detail":"Bile emulsifies the fat droplets into micelles, which carry the vitamins to the intestinal wall for absorption, the same process fat digestion uses (covered in Unit 6)."},{"label":"Transported like fat","detail":"Absorbed vitamins travel in chylomicrons through the lymphatic system before reaching the blood, just as dietary fat does."},{"label":"Stored, not flushed","detail":"Excess is stored mainly in the liver (A) or fatty tissue (D, E), rather than excreted in urine. This storage is exactly what allows toxicity to build up gradually from chronic high-dose supplementation."}]},"blocksHtml":["<div class=\"callout\">Fat-soluble vitamins are absorbed with dietary fat and can be stored, which raises the risk of toxicity from excessive supplements.</div>"]},{"id":"sf8-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The main function of vitamin E is to act as a(n):","options":[{"label":"Coenzyme","correct":false,"feedback":"Vitamin E protects membranes from oxidation."},{"label":"Free radical","correct":false,"feedback":"Vitamin E protects membranes from oxidation."},{"label":"Fat","correct":false,"feedback":"Vitamin E protects membranes from oxidation."},{"label":"Antioxidant","correct":true,"feedback":"Vitamin E protects membranes from oxidation."}]}},{"id":"sf8-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Night blindness is associated with a subclinical deficiency of:","options":[{"label":"Vitamin E","correct":false,"feedback":"Vitamin A supports vision."},{"label":"Vitamin A","correct":true,"feedback":"Vitamin A supports vision."},{"label":"Thiamin","correct":false,"feedback":"Vitamin A supports vision."},{"label":"Folic acid","correct":false,"feedback":"Vitamin A supports vision."}]}},{"id":"sf8-2","chapter":"Water-soluble vitamins","title":"Water-soluble vitamins","html":"<h3>Water-soluble vitamins</h3><p>The B vitamins participate in energy metabolism, red-blood-cell formation, amino-acid metabolism, and DNA synthesis. Thiamin, riboflavin, niacin, pantothenic acid, biotin, vitamin B6, folate, and vitamin B12 have distinct roles. Vitamin C supports collagen synthesis, antioxidant systems, immune function, and nonheme-iron absorption. Most water-soluble vitamins have limited storage, although vitamin B12 is an important exception.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Vitamin</th><th>Major role</th></tr></thead><tbody><tr><td>Thiamin (B1)</td><td>Part of TPP/TDP enzymes that release energy from macronutrients</td></tr><tr><td>Riboflavin (B2)</td><td>Forms FMN and FAD for oxidation-reduction reactions</td></tr><tr><td>Niacin (B3)</td><td>Forms NAD and NADP</td></tr><tr><td>Vitamin B6</td><td>Amino acid metabolism, gluconeogenesis, glycogen breakdown</td></tr><tr><td>Pantothenic acid</td><td>Part of coenzyme A</td></tr><tr><td>Biotin</td><td>Supports numerous energy reactions</td></tr></tbody></table></div>","<p>Vitamin C supports collagen synthesis, antioxidant systems, immune function and nonheme-iron absorption. Vitamin B12 absorption needs intrinsic factor, and natural sources are animal foods.</p>"]},{"id":"sf8-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which vitamin forms part of NAD and NADP?","options":[{"label":"Thiamin","correct":false,"feedback":"Niacin (B3) forms NAD and NADP."},{"label":"Riboflavin","correct":false,"feedback":"Niacin (B3) forms NAD and NADP."},{"label":"Niacin","correct":true,"feedback":"Niacin (B3) forms NAD and NADP."},{"label":"Pantothenic acid","correct":false,"feedback":"Niacin (B3) forms NAD and NADP."}]}},{"id":"sf8-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which vitamin forms part of coenzyme A?","options":[{"label":"Thiamin","correct":false,"feedback":"Pantothenic acid is part of coenzyme A."},{"label":"Riboflavin","correct":false,"feedback":"Pantothenic acid is part of coenzyme A."},{"label":"Folate","correct":false,"feedback":"Pantothenic acid is part of coenzyme A."},{"label":"Pantothenic acid","correct":true,"feedback":"Pantothenic acid is part of coenzyme A."}]}},{"id":"sf8-3","chapter":"Deficiency, performance, and antioxidants","title":"Deficiency, performance, and antioxidants","html":"<h3>Deficiency and performance</h3><p>A true deficiency can impair performance by disrupting energy metabolism, oxygen transport, bone health, immunity, or tissue repair. Correcting the deficiency can restore function. When status is already adequate, additional vitamins do not create extra energy or automatically improve performance. Symptoms such as fatigue are nonspecific and should not be self-diagnosed as a vitamin deficiency.</p><h3>Antioxidants and exercise adaptation</h3><p>Exercise increases reactive oxygen species, which can damage tissue at high levels but also act as signals for adaptation. Food-based antioxidant systems include vitamins C and E, carotenoids, selenium-dependent enzymes, and many phytochemicals. Very large antioxidant doses may interfere with some training signals and do not replace recovery, sleep, and adequate energy.</p>","visual":null,"blocksHtml":["<div class=\"callout\">A true deficiency can impair performance. Correcting it can restore function. When status is already adequate, extra vitamins do not create extra energy. Low B-vitamin intake commonly reflects low total energy intake.</div>","<div class=\"tabblk\"><b>Free radicals</b><p>Exercise increases reactive oxygen species. High levels can damage tissue, but they also act as signals for adaptation.</p></div><div class=\"tabblk\"><b>Antioxidant systems</b><p>Vitamins C and E, carotenoids and selenium-dependent enzymes. Vitamin C can regenerate vitamin E.</p></div><div class=\"tabblk\"><b>Megadoses</b><p>Very large antioxidant doses may interfere with training signals and can act as pro-oxidants. The chapter favours food sources.</p></div>"]},{"id":"sf8-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Why can a severe B-vitamin deficiency lead to fatigue?","options":[{"label":"B vitamins are a source of calories","correct":false,"feedback":"B vitamins are coenzymes rather than energy sources."},{"label":"Carbohydrate absorption stops","correct":false,"feedback":"B vitamins are coenzymes rather than energy sources."},{"label":"Oxygen cannot be transported","correct":false,"feedback":"B vitamins are coenzymes rather than energy sources."},{"label":"Coenzymes for energy metabolism are produced in insufficient amounts","correct":true,"feedback":"B vitamins are coenzymes rather than energy sources."}]}},{"id":"sf8-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"High-dose antioxidant supplements may:","options":[{"label":"Always improve adaptation","correct":false,"feedback":"Reactive oxygen species also signal adaptation, and megadoses can blunt that signal."},{"label":"Interfere with some training signals","correct":true,"feedback":"Reactive oxygen species also signal adaptation, and megadoses can blunt that signal."},{"label":"Replace sleep and recovery","correct":false,"feedback":"Reactive oxygen species also signal adaptation, and megadoses can blunt that signal."},{"label":"Provide energy","correct":false,"feedback":"Reactive oxygen species also signal adaptation, and megadoses can blunt that signal."}]}},{"id":"sf8-4","chapter":"Athletes at risk and supplement safety","title":"Athletes at risk and supplement safety","html":"<h3>Athletes at greater risk</h3><p>Risk rises with low energy availability, restrictive diets, food allergies without replacement foods, vegan diets without vitamin B12 planning, limited sun exposure, malabsorption, illness, and some medications. Indoor athletes and people living at northern latitudes may need vitamin D assessment. Pregnant athletes and adolescents have additional life-stage needs.</p><h3>Supplement safety</h3><p>Compare the amount per serving with the RDA or AI and the UL, account for fortified foods and multiple products, and avoid assuming that “natural” means safe. Fat-soluble vitamins and high-dose B6, niacin, folic acid, or vitamin C can cause harm. Targeted supplementation should respond to assessed intake, laboratory findings, or a recognized life-stage recommendation.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Higher risk</dt><dd>Low energy availability, restrictive diets, vegan diets without B12 planning, limited sun exposure, malabsorption, some medications.</dd></div><div><dt>Vitamin D</dt><dd>Indoor athletes and northern latitudes may need assessment.</dd></div><div><dt>Toxicity</dt><dd>Fat-soluble vitamins, and high-dose B6, niacin, folic acid or vitamin C, can cause harm.</dd></div></dl>"]},{"id":"sf8-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Overconsumption of which vitamin is most likely to result in toxicity?","options":[{"label":"Vitamin A (retinol)","correct":true,"feedback":"Fat-soluble vitamins are stored, and vitamin A is the classic toxicity risk from high-dose supplements."},{"label":"Vitamin E (alpha-tocopherol)","correct":false,"feedback":"Fat-soluble vitamins are stored, and vitamin A is the classic toxicity risk from high-dose supplements."},{"label":"Vitamin B1 (thiamin)","correct":false,"feedback":"Fat-soluble vitamins are stored, and vitamin A is the classic toxicity risk from high-dose supplements."},{"label":"Vitamin B12 (cobalamin)","correct":false,"feedback":"Fat-soluble vitamins are stored, and vitamin A is the classic toxicity risk from high-dose supplements."}]}},{"id":"sf8-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The athlete most likely to develop a clinical vitamin B12 deficiency is one who:","options":[{"label":"Is vegetarian or vegan without planning","correct":true,"feedback":"B12 comes naturally from animal foods, so vegans need fortified foods or supplements."},{"label":"Is lactose intolerant","correct":false,"feedback":"B12 comes naturally from animal foods, so vegans need fortified foods or supplements."},{"label":"Has low UV exposure","correct":false,"feedback":"B12 comes naturally from animal foods, so vegans need fortified foods or supplements."},{"label":"Is a bodybuilder","correct":false,"feedback":"B12 comes naturally from animal foods, so vegans need fortified foods or supplements."}]}},{"id":"sf8-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A distance runner wants to take a high-dose multivitamin to “boost energy.” What is the evidence-based response?","text":"Vitamins do not provide energy. If intake is adequate, extra vitamins do not improve performance. Screen intake and risk factors, compare doses with the DRI and UL, and supplement only for a defined reason."},{"label":"A vegan athlete feels tired. What vitamin should be checked first?","text":"Vitamin B12, since natural sources come from animal foods. Fatigue is nonspecific, so use assessment rather than self-diagnosis."}]}}],"flashcards":[{"front":"Fat-soluble vitamins","back":"A, D, E and K."},{"front":"Vitamin A","back":"Vision, epithelial tissue, immunity."},{"front":"Vitamin D","back":"Calcium regulation and bone; hormone-like."},{"front":"Vitamin E","back":"Antioxidant for lipid membranes."},{"front":"Vitamin K","back":"Clotting proteins and bone metabolism."},{"front":"Thiamin (B1)","back":"TPP/TDP; releases energy from macronutrients."},{"front":"Riboflavin (B2)","back":"FMN and FAD."},{"front":"Niacin (B3)","back":"NAD and NADP."},{"front":"Vitamin B6","back":"Amino acid metabolism, gluconeogenesis, glycogen breakdown."},{"front":"Pantothenic acid","back":"Part of coenzyme A."},{"front":"Vitamin B12","back":"Red blood cell formation; needs intrinsic factor; animal foods."},{"front":"Vitamin C","back":"Collagen, antioxidant, immune, nonheme iron absorption."},{"front":"Energy from vitamins","back":"0 kcal."},{"front":"UL","back":"The upper limit above which adverse effects become more likely."}],"quiz":[{"q":"The vitamin associated with amino acid metabolism is:","o":["Vitamin B1.","Vitamin B2.","Vitamin B3.","Vitamin B6."],"a":3,"e":""},{"q":"The vitamin contained in coenzymes necessary for oxidation-reduction reactions in the production of ATP is:","o":["thiamin.","riboflavin.","vitamin B6.","vitamin B12."],"a":1,"e":""},{"q":"The vitamin that acts like a hormone is:","o":["vitamin A.","vitamin C.","vitamin D.","vitamin E."],"a":2,"e":""},{"q":"The vitamin that is part of NAD and NADP is:","o":["pantothenic acid.","vitamin B1 (thiamin).","vitamin B2 (riboflavin).","vitamin B3 (niacin)."],"a":3,"e":""},{"q":"Which vitamin forms a part of coenzyme A?","o":["Thiamin","Riboflavin","Folic acid (folate)","Pantothenic acid"],"a":3,"e":""},{"q":"The main function of vitamin E is to act as a(n):","o":["coenzyme.","free radical.","fat.","antioxidant."],"a":3,"e":""},{"q":"Vitamin C is a?","o":["Water-soluble vitamin","Fat-soluble vitamin"],"a":0,"e":""},{"q":"_____ is a water-soluble vitamin.","o":["Vitamin A","Vitamin K","Vitamin D","None of the above"],"a":3,"e":""},{"q":"Which of the following functions is shared by beta-carotene and vitamin E?","o":["Prevention of anemia","Carbon dioxide removal","Inhibition of oxidation","Inhibition of bone calcium loss"],"a":2,"e":""},{"q":"Which question is best answered by using the Dietary Reference Intakes (DRI)?","o":["How much of a vitamin is too much?","Is the amount in this vitamin supplement safe?","Is the amount in this vitamin supplement effective?","How much of a certain vitamin do I need daily?"],"a":3,"e":""},{"q":"The need for which vitamin increases with age?","o":["Vitamin B1","Vitamin B2","Vitamin C","Vitamin D"],"a":3,"e":""},{"q":"According to the current body of scientific research, what effect does exercise have on an athlete’s vitamin requirements?","o":["Increases the need substantially, making vitamin supplementation necessary","Increases the need substantially, but supplementation not necessary","Increases the need slightly, but supplementation not necessary","Increases the need slightly, making vitamin supplementation necessary"],"a":2,"e":""},{"q":"Which of the following best describes average vitamin intakes by sedentary adults in the U.S.?","o":["Inadequate","Adequate","Excessive"],"a":0,"e":""},{"q":"The intake of which vitamin is likely to be low in both sedentary and athletic populations?","o":["Thiamin","Riboflavin","Niacin","Vitamin E"],"a":3,"e":""},{"q":"In general, when an athlete’s energy intake is adequate, vitamin intake is usually:","o":["inadequate.","adequate.","excessive."],"a":1,"e":""},{"q":"Night blindness is associated with a subclinical deficiency of:","o":["vitamin E.","vitamin A.","thiamin.","folic acid."],"a":1,"e":""},{"q":"The athlete who is most likely to manifest a clinical vitamin deficiency is:","o":["a body builder.","a wrestler.","one with a low percentage of body fat.","one with a severe eating disorder."],"a":3,"e":""},{"q":"The athlete who is most likely to manifest a clinical vitamin B12 deficiency is:","o":["one who is vegetarian.","one who is lactose intolerant.","one with no or low exposure to UV light.","one with hypervitaminosis A."],"a":0,"e":""},{"q":"Which of the following poses the greatest health risk when consumed as a high-dose supplement?","o":["Vitamin A","Vitamin C","Vitamin E","Niacin"],"a":0,"e":""},{"q":"Beta-carotene is a / an","o":["Water-soluble vitamin","Fat-soluble vitamin","Antioxidant","Both B and C"],"a":3,"e":""},{"q":"In general, how long does it take vitamin toxicities to develop?","o":["Several days to a few weeks","Several weeks to a few months","Several months to a few years","Many decades"],"a":2,"e":""},{"q":"Overconsumption of which vitamin is most likely to result in toxicity?","o":["Vitamin A (retinol)","Vitamin E (alpha-tocopherol)","Vitamin B1 (thiamin)","Vitamin B12 (cobalamin)"],"a":0,"e":""},{"q":"According to the current body of scientific research, what is known about vitamin A toxicity?","o":["No reports in industrialized countries","Number of cases is extremely small","Number of cases is moderate and increasing","Number of cases is large but effects are minor"],"a":2,"e":""},{"q":"When supplemented at high doses, the vitamin that may be toxic to nervous tissue is:","o":["thiamin.","riboflavin.","niacin.","vitamin B6."],"a":3,"e":""},{"q":"Which of the following describes the basic function of a coenzyme?","o":["Attaches to RNA to assist in the synthesis of an enzyme","Attaches to cell membranes to assist in the uptake of an enzyme","Attaches to an enzyme, which allows for the activation of the enzyme","Attaches to an enzyme, which allows for the transportation of the enzyme"],"a":2,"e":""},{"q":"At what point do enzymes and coenzymes function at maximum velocity?","o":["75% of tissue saturation","100% of tissue saturation","110% of tissue saturation","125% of tissue saturation"],"a":1,"e":""},{"q":"Which of the following statements is true about B-complex vitamins?","o":["These vitamins contain energy and are directly associated with fatigue.","These vitamins play an indirect role in energy production.","Studies show that sub-clinical deficiencies typically result in fatigue.","Athletes generally improve performance when they take a low-dose supplement."],"a":1,"e":""},{"q":"Which statement best explains why severe B vitamin deficiencies can lead to fatigue?","o":["B vitamins are a source of energy (calories).","Absorption of carbohydrate is decreased.","Oxygen needed for energy metabolism cannot be transported to the cells.","Coenzymes needed for energy metabolism are produced in insufficient amounts."],"a":3,"e":""},{"q":"Why is half of the thiamin (vitamin B1) found in the body found in skeletal muscle?","o":["Thiamin is needed to catalyze reactions involved in ATP production.","Thiamin is needed to release glucose from glycogen stores.","Thiamin is needed to store glucose as glycogen.","Thiamin is needed to transaminate amino acids."],"a":0,"e":""},{"q":"The amount of energy (kcal) provided by a B-complex vitamin is:","o":["4","7","0"],"a":2,"e":""},{"q":"Low thiamin intake in athletes is associated with:","o":["energy restriction.","high dietary fat intake.","high intake of low-fiber, high-sugar carbohydrates.","a and c","all of the above"],"a":3,"e":""},{"q":"Athletes generally consume sufficient thiamin, riboflavin, and niacin if they also consume sufficient:","o":["iron-containing foods.","fruits and vegetables.","fat.","energy."],"a":3,"e":""},{"q":"Vitamin B6 (pyridoxine) is found in coenzymes that are needed to:","o":["prevent oxidation of low-density lipoproteins.","release glucose from glycogen stores.","store glucose as glycogen.","reduce muscle soreness."],"a":1,"e":""},{"q":"Which of the following is true regarding athletes and the consumption of an adequate amount of vitamin C from food?","o":["Vitamin C is a difficult vitamin to obtain from food.","Low vitamin C intake from food is rare.","Vitamin C intake generally reflects fruit and vegetable intake.","Vitamin C intake generally reflects energy intake."],"a":2,"e":""},{"q":"Which of the following is true regarding athletes and the consumption of an adequate amount of vitamin A from food?","o":["Vitamin A is a difficult vitamin to obtain from food.","Low vitamin A intake from food is rare.","Vitamin A intake generally reflects fruit and vegetable intake.","Vitamin A intake generally reflects energy intake."],"a":2,"e":""},{"q":"The fat-soluble vitamins are vitamins A, D, E, and K.","o":["True","False"],"a":0,"e":""},{"q":"After tissues are saturated with water-soluble vitamins, any excess is excreted and no toxicity symptoms have been reported.","o":["True","False"],"a":1,"e":""},{"q":"The best way for athletes to offset any moderate losses of vitamins through sweat or urine is to take a multivitamin supplement.","o":["True","False"],"a":1,"e":""},{"q":"Distance runners often consume a low-fat diet, which is associated with a low vitamin E intake.","o":["True","False"],"a":0,"e":""},{"q":"Sedentary individuals can meet the recommended daily intake of vitamins through food alone, but most endurance athletes cannot because exercise accelerates the loss of vitamins.","o":["True","False"],"a":1,"e":""}]},{"n":9,"title":"Minerals","kicker":"Classify minerals, understand absorption and homeostasis, and focus on bone formation, iron status, immune function, food sources and supplement safety.","steps":[{"id":"sf9-0","chapter":"Classification and absorption","title":"Classification and absorption","html":"<h3>Classification and homeostasis</h3><p>Macrominerals are required in larger amounts and include calcium, phosphorus, magnesium, sodium, potassium, chloride, and sulfur. Trace minerals include iron, zinc, copper, selenium, iodine, chromium, manganese, molybdenum, and others. The body regulates absorption, transport, storage, and excretion to keep concentrations within a narrow range. More intake does not always produce more absorption.</p><h3>Factors that affect absorption</h3><p>Mineral form, dose, nutritional status, age, intestinal health, and meal composition all matter. Phytates and oxalates can bind minerals; large doses of one mineral can compete with another. Vitamin C improves nonheme-iron absorption, while heme iron is absorbed more efficiently. The body may trap iron in intestinal cells and lose it when those cells are shed.</p>","visual":null,"blocksHtml":["<p>Minerals differ from vitamins in one key way: they are elements, not built molecules, so the body cannot make, modify, or destroy them, only absorb, distribute, store, and excrete them. <b>Homeostasis</b> for a mineral means the body actively manages all four of those steps to hold blood and tissue concentrations in a narrow working range, mainly by adjusting how much is absorbed at the gut and how much is excreted by the kidneys, rather than by changing how much is “used up.”</p>"]},{"id":"sf9-0-s0","title":"Macromineral or trace mineral?","teach":[],"act":{"type":"sort","prompt":"Macromineral or trace mineral?","categories":["Macromineral","Trace mineral"],"items":[{"label":"Calcium","category":0,"feedback":"Required in larger amounts."},{"label":"Magnesium","category":0,"feedback":"Macromineral."},{"label":"Sodium","category":0,"feedback":"Macromineral."},{"label":"Iron","category":1,"feedback":"Trace mineral."},{"label":"Zinc","category":1,"feedback":"Trace mineral."},{"label":"Selenium","category":1,"feedback":"Trace mineral."}]}},{"id":"sf9-0-s1","title":"Effect on absorption","teach":[],"act":{"type":"sort","prompt":"Effect on absorption","categories":["Increases","Decreases"],"items":[{"label":"Vitamin C with nonheme iron","category":0,"feedback":"Ascorbic acid improves nonheme-iron absorption."},{"label":"Phytates and oxalates","category":1,"feedback":"They bind minerals."},{"label":"Insoluble fibre such as wheat fibre","category":1,"feedback":"It reduces absorption."},{"label":"Soluble fibre such as pectins or gums","category":1,"feedback":"It reduces absorption."},{"label":"Lactose (for calcium)","category":0,"feedback":"Sugars such as lactose increase calcium absorption."},{"label":"A single-mineral supplement such as iron alone","category":0,"feedback":"Without competing food components it increases absorption."}]}},{"id":"sf9-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Phytates and oxalates:","options":[{"label":"Increase absorption","correct":false,"feedback":"They bind minerals and reduce absorption."},{"label":"Decrease absorption","correct":true,"feedback":"They bind minerals and reduce absorption."},{"label":"Have no effect","correct":false,"feedback":"They bind minerals and reduce absorption."}]}},{"id":"sf9-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The nutrient that enhances iron absorption is:","options":[{"label":"Copper","correct":false,"feedback":"Vitamin C improves nonheme-iron absorption."},{"label":"Potassium","correct":false,"feedback":"Vitamin C improves nonheme-iron absorption."},{"label":"Sodium","correct":false,"feedback":"Vitamin C improves nonheme-iron absorption."},{"label":"Vitamin C","correct":true,"feedback":"Vitamin C improves nonheme-iron absorption."}]}},{"id":"sf9-1","chapter":"Bone and calcium regulation","title":"Bone and calcium regulation","html":"<h3>Calcium, phosphorus, magnesium, and bone</h3><p>Bone is both structural tissue and a mineral reservoir. Osteoblasts build bone, osteoclasts resorb it, and osteocytes help coordinate the response to loading. Trabecular bone turns over faster than cortical bone. Calcium and phosphorus form mineral crystals; magnesium contributes to structure and enzyme function. Vitamin D and parathyroid hormone help regulate blood calcium.</p>","visual":{"title":"Bone and calcium regulation","kind":"sequence","items":[{"label":"Blood calcium falls","detail":"Sensed by the parathyroid glands in the neck."},{"label":"Parathyroid hormone (PTH) rises","detail":"PTH signals bone to release calcium (via osteoclast activity), the kidneys to reabsorb more calcium and activate vitamin D, and the gut, through that activated vitamin D, to absorb more dietary calcium."},{"label":"Blood calcium is restored","detail":"Once the level normalizes, PTH secretion falls back down."},{"label":"Calcitonin, in the other direction","detail":"When blood calcium runs high, calcitonin from the thyroid gland opposes PTH, encouraging calcium to move back into bone. Its everyday role in adult calcium regulation is considered minor compared with PTH and vitamin D."}]},"blocksHtml":["<h3>What happens when blood calcium drops</h3>","<div class=\"tabblk\"><b>Osteoblasts</b><p>Bone-forming cells.</p></div><div class=\"tabblk\"><b>Osteoclasts</b><p>Resorb (break down) bone.</p></div><div class=\"tabblk\"><b>Osteocytes</b><p>Help coordinate the response to mechanical loading.</p></div>","<div class=\"mn-html\"><span>Remember it</span><b>“B” builds, “C” chews.</b> Osteo<b>b</b>lasts <b>b</b>uild bone. Osteo<b>c</b>lasts <b>c</b>hew bone away, think of the word “iconoclast,” someone who tears things down.</div>","<dl class=\"facts\"><div><dt>Trabecular bone</dt><dd>Higher turnover than cortical bone.</dd></div><div><dt>Fast calcium exchange</dt><dd>Draws on calcium in bone fluid.</dd></div><div><dt>Long-term low intake</dt><dd>Increases slow exchange, so bone dissolves.</dd></div><div><dt>Peak bone mineral density</dt><dd>Occurs at about 20 to 35 years with adequate calcium.</dd></div><div><dt>Hormones</dt><dd>Vitamin D and parathyroid hormone help regulate blood calcium.</dd></div></dl>","<div class=\"callout\"><b class=\"k\">Practical read.</b> Because PTH will pull calcium from bone to protect blood levels no matter what, a blood calcium test looking “normal” tells you almost nothing about bone health. Bone status is assessed separately, typically with a DEXA scan, not with a calcium blood test.</div>"]},{"id":"sf9-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Bone-forming cells are known as:","options":[{"label":"Osteoblasts","correct":true,"feedback":"Osteoblasts build bone. Osteoclasts resorb it."},{"label":"Osteoclasts","correct":false,"feedback":"Osteoblasts build bone. Osteoclasts resorb it."},{"label":"Osteocytes","correct":false,"feedback":"Osteoblasts build bone. Osteoclasts resorb it."},{"label":"Chondrocytes","correct":false,"feedback":"Osteoblasts build bone. Osteoclasts resorb it."}]}},{"id":"sf9-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The type of bone with the highest turnover is:","options":[{"label":"Cartilage","correct":false,"feedback":"Trabecular bone turns over faster than cortical bone."},{"label":"Cortical bone","correct":false,"feedback":"Trabecular bone turns over faster than cortical bone."},{"label":"Trabecular bone","correct":true,"feedback":"Trabecular bone turns over faster than cortical bone."}]}},{"id":"sf9-2","chapter":"Iron and oxygen transport","title":"Iron and oxygen transport","html":"<h3>Iron and oxygen transport</h3><p>Iron is part of hemoglobin, which carries oxygen in blood, and myoglobin, which stores and transfers oxygen in muscle. Ferritin reflects storage. Iron-deficiency anemia lowers hemoglobin and impairs oxygen transport, aerobic capacity, and endurance. Risk is greater with menstruation, endurance running, low energy intake, vegetarian diets without planning, gastrointestinal loss, and frequent blood donation.</p>","visual":{"title":"Iron and oxygen transport","kind":"sequence","items":[{"label":"Stage 1: iron depletion","detail":"Storage iron (ferritin) starts to fall while hemoglobin and functional iron are still normal. Usually no symptoms yet."},{"label":"Stage 2: iron-deficient erythropoiesis","detail":"Storage iron is low and red blood cell production starts to suffer, even though hemoglobin may still sit inside the “normal” range."},{"label":"Stage 3: iron-deficiency anemia","detail":"Hemoglobin drops below normal. Oxygen-carrying capacity, aerobic performance and endurance are measurably reduced at this stage."}]},"blocksHtml":["<div class=\"callout\"><b class=\"k\">Why this matters for testing.</b> An athlete can be in stage 1 or 2, with real performance and training consequences, while a basic hemoglobin test still reads normal. Ferritin is what catches the earlier stages, which is why it is checked alongside hemoglobin rather than instead of it.</div>","<div class=\"tbl\"><table><thead><tr><th>Source</th><th>Absorption</th><th>Examples</th></tr></thead><tbody><tr><td>Heme iron</td><td>Better absorbed</td><td>Meat, poultry, fish, shellfish</td></tr><tr><td>Nonheme iron</td><td>More variable; vitamin C helps</td><td>Legumes, leafy greens, fortified grains, tofu</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>Heme sounds like “him,” as in an animal.</b> Heme iron comes from animal flesh (meat, poultry, fish) and is absorbed well. Nonheme is everything else, mainly plant sources, and needs help (vitamin C) to absorb efficiently.</div>","<dl class=\"facts\"><div><dt>Hemoglobin</dt><dd>Carries oxygen in blood.</dd></div><div><dt>Myoglobin</dt><dd>Stores and gives oxygen to muscle immediately.</dd></div><div><dt>Ferritin</dt><dd>Reflects iron storage; the best test of storage.</dd></div><div><dt>Iron-deficiency anemia</dt><dd>Lowers aerobic and endurance capacity.</dd></div><div><dt>Hepcidin</dt><dd>A liver hormone that blocks iron absorption when iron stores are already adequate, or temporarily after hard exercise or with inflammation, which is one reason some endurance athletes absorb iron poorly despite eating enough.</dd></div></dl>","<div class=\"callout\">Do not self-prescribe iron. Fatigue has many causes, iron overload is harmful, and treatment depends on blood tests and the cause.</div>"]},{"id":"sf9-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The best test of iron storage is:","options":[{"label":"Hematocrit","correct":false,"feedback":"Ferritin reflects stored iron."},{"label":"Hemoglobin","correct":false,"feedback":"Ferritin reflects stored iron."},{"label":"Ferritin","correct":true,"feedback":"Ferritin reflects stored iron."},{"label":"None of the above","correct":false,"feedback":"Ferritin reflects stored iron."}]}},{"id":"sf9-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which form of iron is best absorbed?","options":[{"label":"Heme","correct":true,"feedback":"Heme iron from animal foods is absorbed more efficiently."},{"label":"Nonheme","correct":false,"feedback":"Heme iron from animal foods is absorbed more efficiently."},{"label":"Iron found in milk","correct":false,"feedback":"Heme iron from animal foods is absorbed more efficiently."},{"label":"Iron found in vegetables","correct":false,"feedback":"Heme iron from animal foods is absorbed more efficiently."}]}},{"id":"sf9-3","chapter":"Electrolytes and trace minerals","title":"Electrolytes and trace minerals","html":"<h3>Fluid and neuromuscular minerals</h3><p>Sodium and chloride dominate extracellular fluid; potassium is concentrated inside cells. Their gradients support fluid balance, nerve impulses, and muscle contraction. Sweat contains water and electrolytes, especially sodium. Most losses are replaced through food and beverages, but prolonged heavy sweating may require a targeted plan. Potassium supplements are rarely a substitute for fruit, vegetables, legumes, dairy, and other foods.</p><h3>Zinc, selenium, iodine, and chromium</h3><p>Zinc supports hundreds of enzymes, immunity, protein synthesis, and wound healing. Selenium forms part of antioxidant enzymes. Iodine is required for thyroid hormones. Chromium is associated with insulin action, but supplementation has not reliably increased muscle or improved performance. Both deficiency and excess can cause harm; high-dose zinc can impair copper and iron metabolism.</p>","visual":{"title":"Electrolytes and trace minerals","kind":"comparison","items":[{"label":"Sodium and chloride","detail":"Dominate extracellular fluid. Support fluid balance, nerves and muscle."},{"label":"Potassium","detail":"Concentrated inside cells. Best from fruit, vegetables, legumes and dairy."},{"label":"Zinc","detail":"Supports hundreds of enzymes, immunity, protein synthesis. Excess can impair copper and iron."},{"label":"Selenium","detail":"Part of antioxidant enzymes. Both low and high intake cause problems."},{"label":"Iodine","detail":"Required for thyroid hormones."},{"label":"Chromium","detail":"Associated with insulin action. Supplements have not reliably improved muscle or performance."}]},"blocksHtml":[]},{"id":"sf9-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"An important physiological role for chromium is that it:","options":[{"label":"Enhances oxygen transport","correct":false,"feedback":"Chromium is associated with insulin action."},{"label":"Enhances insulin sensitivity","correct":true,"feedback":"Chromium is associated with insulin action."},{"label":"Stabilizes blood calcium","correct":false,"feedback":"Chromium is associated with insulin action."},{"label":"Converts alcohol to fat","correct":false,"feedback":"Chromium is associated with insulin action."}]}},{"id":"sf9-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The main concern with excess supplemental zinc is:","options":[{"label":"It suppresses appetite","correct":false,"feedback":"High-dose zinc can impair copper and iron metabolism."},{"label":"Interference with iron (and copper) metabolism","correct":true,"feedback":"High-dose zinc can impair copper and iron metabolism."},{"label":"It raises urinary infections","correct":false,"feedback":"High-dose zinc can impair copper and iron metabolism."},{"label":"Excess bruising","correct":false,"feedback":"High-dose zinc can impair copper and iron metabolism."}]}},{"id":"sf9-4","chapter":"Food first and targeted testing","title":"Food first and targeted testing","html":"<h3>Food first and targeted testing</h3><p>Adequate energy and a varied diet usually cover mineral needs. Supplements are most appropriate when a deficiency, dietary gap, or medical indication has been identified. Iron should not be prescribed from symptoms alone because fatigue has many causes and iron overload is harmful. Calcium and vitamin D concerns should be considered alongside energy availability and bone-loading activity.</p>","visual":{"title":"Food first and targeted testing","kind":"comparison","items":[{"label":"Multimineral to offset sweat losses?","detail":"Not the best approach. Losses are small to moderate, so food with adequate energy is the answer."},{"label":"High-potency product","detail":"Can exceed a UL or interfere with another mineral."},{"label":"Calcium and vitamin D concerns","detail":"Consider energy availability and bone-loading activity alongside them."},{"label":"Iron from symptoms alone","detail":"Do not prescribe. Test first."}]},"blocksHtml":["<div class=\"callout\">A varied diet with adequate energy usually covers mineral needs. Supplement when a deficiency, dietary gap or medical indication has been identified. The most prevalent clinical mineral deficiencies in industrialized countries are iron and calcium. A 25-year-old adult needs about 1,000 mg of calcium daily.</div>"]},{"id":"sf9-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The best way to offset small to moderate mineral losses through sweat and urine is a multimineral supplement.","options":[{"label":"True","correct":false,"feedback":"Adequate energy and varied food are usually sufficient."},{"label":"False","correct":true,"feedback":"Adequate energy and varied food are usually sufficient."}]}},{"id":"sf9-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The most prevalent clinical mineral deficiencies in industrialized countries are:","options":[{"label":"Sodium and potassium","correct":false,"feedback":"Iron and calcium are the most common."},{"label":"Boron and selenium","correct":false,"feedback":"Iron and calcium are the most common."},{"label":"Iodine and zinc","correct":false,"feedback":"Iron and calcium are the most common."},{"label":"Iron and calcium","correct":true,"feedback":"Iron and calcium are the most common."}]}},{"id":"sf9-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"An endurance runner feels tired and wants to start iron tablets.","text":"Do not start from symptoms alone. Ask about intake, menstruation, training and diet, and arrange blood tests (including ferritin) so supplementation follows results."},{"label":"A client takes a high-dose zinc supplement for immunity. What is the risk?","text":"Excess zinc can impair copper and iron metabolism. Compare the dose with the DRI and UL and prefer food sources."}]}}],"flashcards":[{"front":"Macrominerals","back":"Calcium, phosphorus, magnesium, sodium, potassium, chloride, sulfur."},{"front":"Trace minerals","back":"Iron, zinc, copper, selenium, iodine, chromium, manganese, molybdenum."},{"front":"Mineral homeostasis","back":"Regulation of absorption, storage and excretion to keep concentrations in range."},{"front":"Phytates and oxalates","back":"Bind minerals and reduce absorption."},{"front":"Vitamin C and iron","back":"Improves nonheme iron absorption."},{"front":"Osteoblasts vs osteoclasts","back":"Build bone; resorb bone."},{"front":"Higher-turnover bone","back":"Trabecular bone."},{"front":"Heme vs nonheme iron","back":"Heme is better absorbed; nonheme is variable."},{"front":"Myoglobin","back":"Stores oxygen in muscle."},{"front":"Ferritin","back":"Marker of iron storage."},{"front":"Sodium and potassium locations","back":"Sodium extracellular; potassium intracellular."},{"front":"Zinc","back":"Enzymes, immunity, protein synthesis; excess impairs copper and iron."},{"front":"Selenium","back":"Part of antioxidant enzymes."},{"front":"Iodine","back":"Needed for thyroid hormones."}],"quiz":[{"q":"What is the role of myoglobin?","o":["Stores excess iron when iron storage in the liver reaches full capacity","Provides oxygen immediately to muscle","Binds excess iron in the GI tract to help prevent overconsumption","Facilitates the transfer of oxygen to the red blood cells"],"a":1,"e":""},{"q":"The best test of iron storage is:","o":["hematocrit.","hemoglobin.","ferritin.","none of the above"],"a":2,"e":""},{"q":"What is false anemia?","o":["Iron-deficiency anemia in athletes","Anemia associated with training at high altitudes","Temporary decrease in hemoglobin due to endurance training","Change in hematocrit due to blood doping"],"a":2,"e":""},{"q":"What effect does iron-deficiency anemia have on performance?","o":["Decline in aerobic capacity","Decline in endurance capacity","Decline in oxygen utilization","All of the above"],"a":3,"e":""},{"q":"What effect does iron-deficiency without anemia have on performance?","o":["Decline in aerobic capacity","Decline in endurance capacity","Decline in oxygen utilization","None of the above"],"a":3,"e":""},{"q":"The male athlete most likely to manifest iron-deficiency anemia is a:","o":["strength athlete engaging in high volume resistance training.","wrestler who “makes weight” by dehydrating.","“stop and go” athlete.","long-distance runner."],"a":3,"e":""},{"q":"The female athlete most likely to manifest iron-deficiency anemia is an athlete who:","o":["chronically restricts energy intake.","only eats three times per day.","is chronically dehydrated.","consumes a low-fiber diet."],"a":0,"e":""},{"q":"Which form of iron is best absorbed?","o":["Heme","Non-heme","Iron found in milk","Iron found in vegetables"],"a":0,"e":""},{"q":"The nutrient that enhances iron absorption is:","o":["copper.","potassium.","sodium.","vitamin C."],"a":3,"e":""},{"q":"Which of the following is true regarding athletes and upper respiratory tract infections (URTI)?","o":["Lack of exercise increases risk for URTI","Prolonged exercise decreases risk for URTI","Prolonged exercise increases risk for URTI","Any type of exercise decreases risks for URTI"],"a":2,"e":""},{"q":"How does the dietary intake of zinc by endurance athletes typically compare to the Dietary Reference Intake (DRI)?","o":["About 10 percent meet the DRI","About 40 percent meet the DRI","About 75 percent meet the DRI","About 90 percent meet the DRI"],"a":1,"e":""},{"q":"What is the recommended daily dose of supplemental zinc?","o":["10 mg","15 mg","30 mg","40 mg"],"a":1,"e":""},{"q":"What is the potential problem with consuming excess supplemental zinc?","o":["Anorexic (appetite suppressing) effect","Increase in urinary tract infections","Interference with iron absorption","Excessive bruising"],"a":2,"e":""},{"q":"The potential problem with mineral supplements that have high bioavailability is:","o":["excess absorption.","they bind a large percentage of the dietary fiber.","they result in too great an increase in transit time.","the potential for dehydration."],"a":0,"e":""},{"q":"An important physiological role for chromium is:","o":["it enhances oxygen uptake and transport.","it enhances insulin sensitivity.","it enhances calcium uptake and helps to stabilize blood calcium levels.","it enhances the conversion of alcohol to stored body fat."],"a":1,"e":""},{"q":"The two most likely sources of larger-than-normal mineral losses in athletes are:","o":["urine and sweat.","urine and feces.","sweat and feces.","sweat and gastrointestinal bleeding."],"a":0,"e":""},{"q":"Excretion of minerals is generally:","o":["zero.","low.","moderate.","high."],"a":1,"e":""},{"q":"Phytates and oxalates:","o":["increase absorption.","decrease absorption.","have no effect on absorption."],"a":1,"e":""},{"q":"Sugars such as lactose (for calcium):","o":["increase absorption.","decrease absorption.","have no effect on absorption."],"a":0,"e":""},{"q":"Insoluble fiber such as wheat fiber:","o":["increases absorption.","decreases absorption.","has no effect on absorption."],"a":1,"e":""},{"q":"Ascorbic acid (for iron):","o":["increases absorption.","decreases absorption.","has no effect on absorption."],"a":0,"e":""},{"q":"Soluble fiber such as pectins or gums:","o":["increases absorption.","decreases absorption.","has no effect on absorption."],"a":1,"e":""},{"q":"A supplement containing a single mineral such as iron:","o":["increases absorption.","decreases absorption.","has no effect on absorption."],"a":0,"e":""},{"q":"Which of the following describes average mineral intakes by sedentary adults in the U.S.?","o":["Inadequate","Adequate","Excessive"],"a":0,"e":""},{"q":"In general, when an athlete’s energy intake is adequate mineral intake is usually:","o":["inadequate.","adequate.","excessive."],"a":1,"e":""},{"q":"The most prevalent clinical mineral deficiencies in industrialized countries are:","o":["sodium and potassium.","boron and selenium.","iodine and zinc.","iron and calcium."],"a":3,"e":""},{"q":"Bone-forming cells are known as:","o":["osteoblasts.","osteoclasts.","osteocytes.","chondrocytes."],"a":0,"e":""},{"q":"The hormone that influences proper bone development is:","o":["insulin.","epinephrine (adrenaline).","norepinephrine (noradrenaline).","vitamin D."],"a":3,"e":""},{"q":"The type of bone that has the highest turnover is:","o":["cartilage.","cortical bone.","trabecular bone."],"a":2,"e":""},{"q":"The term homeostasis is defined as:","o":["a change within the internal environment.","the maintenance of a constant internal environment.","a constant metabolic demand placed on the body.","a low metabolic rate."],"a":1,"e":""},{"q":"The source of calcium during the process known as fast calcium exchange is:","o":["dissolution of bone.","blood plasma.","bone fluid.","liver calcium stores."],"a":2,"e":""},{"q":"If dietary calcium is inadequate over a long period of time, how does the body maintain calcium balance?","o":["Significantly increases absorption","Does not allow calcium to be lost from the body","Reabsorbs skeletal calcium","Adjusts to a lower blood calcium concentration"],"a":2,"e":""},{"q":"At what age does peak bone mineral density occur (assume adequate calcium intake)?","o":["10 to 20 years","20 to 35 years","35 to 60 years","After age 6"],"a":1,"e":""},{"q":"What effect does a low vitamin D concentration have on calcium absorption?","o":["Increases calcium absorption","Decreases calcium absorption","No effect on calcium absorption"],"a":1,"e":""},{"q":"How much calcium should a 25-year-old male or non-pregnant female consume daily?","o":["800 mg","1,000 mg","1,200 mg","1,500 mg"],"a":1,"e":""},{"q":"There is some evidence that mineral loss may be greater in athletes than in the sedentary population.","o":["True","False"],"a":0,"e":""},{"q":"The best way for athletes to offset any small to moderate losses of mineral through sweat or urine is to take a multimineral supplement.","o":["True","False"],"a":1,"e":""},{"q":"Excretion of minerals is usually low.","o":["True","False"],"a":0,"e":""},{"q":"When the body wants to limit iron absorption it may leave iron in mucosal cells and wait for them to be excreted.","o":["True","False"],"a":0,"e":""},{"q":"Mineral metabolism is typically uncomplicated and involves simple adjustments to absorption and excretion.","o":["True","False"],"a":1,"e":""}]},{"n":10,"title":"Diet Planning and Timing","kicker":"Build an athlete’s diet from energy needs outward, then match food, fluid and supplements to training, recovery, performance and health.","steps":[{"id":"sf10-0","chapter":"The planning sequence and energy","title":"The planning sequence and energy","html":"<h3>The diet-planning sequence</h3><p>The chapter defines diet as the food and beverages a person usually consumes. Planning starts with total energy because every nutrient target must fit inside that energy budget. Next establish carbohydrate according to training demand, then protein, and then use fat to complete the prescription. Alcohol supplies energy but is not an essential nutrient and is commonly reduced when an energy deficit is needed.</p><h3>Energy ranges and nutrient density</h3><p>Energy needs vary widely. The chapter’s table uses about 30 kcal/kg/day for a sedentary female, the same figure used elsewhere as a practical minimum for athletes. Nutrient density compares nutrients with calories: skim milk is more nutrient dense than whole milk because it provides similar vitamins, minerals, and protein for fewer calories. Nutrient-dense food becomes especially important when intake is restricted.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td>Nutrient density</td><td>Nutrients supplied relative to energy</td></tr><tr><td>Empty calories</td><td>Energy with few nutrients</td></tr><tr><td>Discretionary calories</td><td>Energy remaining after essential needs are met</td></tr></tbody></table></div>","<div class=\"mn-html\"><span>Remember it</span><b>“Every Coach Plans Fuel.”</b> The planning order is Energy, Carbohydrate, Protein, Fat, matching the sentence’s first letters. Fat is always last because it simply fills whatever energy space the other three leave behind.</div>"]},{"id":"sf10-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"After energy is established, the chapter plans the macronutrients in this order:","options":[{"label":"Carbohydrate, protein, fat","correct":true,"feedback":"Set carbohydrate by training demand, then protein, and use fat to complete the prescription."},{"label":"Protein, fat, carbohydrate","correct":false,"feedback":"Set carbohydrate by training demand, then protein, and use fat to complete the prescription."},{"label":"Fat, carbohydrate, protein","correct":false,"feedback":"Set carbohydrate by training demand, then protein, and use fat to complete the prescription."},{"label":"All at once","correct":false,"feedback":"Set carbohydrate by training demand, then protein, and use fat to complete the prescription."}]}},{"id":"sf10-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Skim milk is more nutrient dense than whole milk because it:","options":[{"label":"Has more protein per glass","correct":false,"feedback":"Nutrient density compares nutrients with calories."},{"label":"Provides similar nutrients for fewer calories","correct":true,"feedback":"Nutrient density compares nutrients with calories."},{"label":"Contains added vitamins only","correct":false,"feedback":"Nutrient density compares nutrients with calories."},{"label":"Is lower in calcium","correct":false,"feedback":"Nutrient density compares nutrients with calories."}]}},{"id":"sf10-1","chapter":"Food-pattern planning","title":"Food-pattern planning","html":"<h3>Food-pattern planning</h3><p>Healthy eating patterns translate calorie and nutrient targets into food-group amounts. They are educational frameworks, not individualized prescriptions. A useful athlete plan distributes grains or other carbohydrate foods, protein foods, dairy or fortified alternatives, vegetables, fruit, and fats across meals and snacks. Cooking ability, budget, culture, travel, and dining-out options determine whether the plan is usable.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Eating out</b><ul class=\"pl\"><li>Favour smaller portions.</li><li>Choose grilled foods, whole grains and vegetables.</li><li>Take sauces and dressings in moderate amounts.</li></ul></div><div class=\"tabblk\"><b>Making it usable</b><p>Cooking ability, budget, culture, travel and dining-out options decide whether a plan works. Distribute carbohydrate foods, protein foods, dairy or fortified alternatives, vegetables, fruit and fats across meals and snacks.</p></div>"]},{"id":"sf10-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Empty calories are best described as:","options":[{"label":"Energy with few nutrients","correct":true,"feedback":"They can crowd out foods that support recovery and health."},{"label":"Nutrients with no energy","correct":false,"feedback":"They can crowd out foods that support recovery and health."},{"label":"Calories from fat only","correct":false,"feedback":"They can crowd out foods that support recovery and health."},{"label":"Calories burned at rest","correct":false,"feedback":"They can crowd out foods that support recovery and health."}]}},{"id":"sf10-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Food-pattern tools are best described as:","options":[{"label":"Individualized prescriptions","correct":false,"feedback":"They translate targets into food-group amounts but are not individual prescriptions."},{"label":"Educational frameworks that are starting points","correct":true,"feedback":"They translate targets into food-group amounts but are not individual prescriptions."},{"label":"Legal requirements","correct":false,"feedback":"They translate targets into food-group amounts but are not individual prescriptions."},{"label":"Clinical diagnoses","correct":false,"feedback":"They translate targets into food-group amounts but are not individual prescriptions."}]}},{"id":"sf10-2","chapter":"Before and during exercise","title":"Before and during exercise","html":"<h3>Pre-exercise goals and tolerability</h3><p>The pre-exercise meal should provide carbohydrate, support hydration, prevent hunger, and minimize gastrointestinal distress. The chapter recommends about 1–4 g carbohydrate/kg in the one to four hours before exercise. Larger meals require more time. Moderate fat several hours before activity can improve satiety, but large amounts of fat, fibre, protein, or unfamiliar food close to exercise may slow gastric emptying or increase symptoms.</p><h3>During-exercise intake</h3><p>During prolonged endurance and intermittent high-intensity sport, carbohydrate helps maintain blood glucose, spare liver glycogen, and delay fatigue. The common target is 30–60 g/hour; ultraendurance activity may use up to 90 g/hour from multiple transportable carbohydrates. Fluid should follow an individualized plan based on sweat rate, weather, clothing, access, and tolerance. Long events may require sodium, but overdrinking must be avoided.</p>","visual":null,"blocksHtml":[]},{"id":"sf10-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The chapter’s pre-exercise carbohydrate guideline in the 1 to 4 hours before exercise is:","options":[{"label":"0.1 to 0.5 g/kg","correct":false,"feedback":"Adjust food volume and fluid to tolerance."},{"label":"1 to 4 g/kg","correct":true,"feedback":"Adjust food volume and fluid to tolerance."},{"label":"6 to 10 g/kg","correct":false,"feedback":"Adjust food volume and fluid to tolerance."},{"label":"No carbohydrate","correct":false,"feedback":"Adjust food volume and fluid to tolerance."}]}},{"id":"sf10-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The common target during prolonged endurance exercise is:","options":[{"label":"5 to 10 g/hour","correct":false,"feedback":"Ultraendurance exercise may use up to about 90 g/hour from multiple transportable carbohydrates."},{"label":"30 to 60 g/hour","correct":true,"feedback":"Ultraendurance exercise may use up to about 90 g/hour from multiple transportable carbohydrates."},{"label":"150 g/hour","correct":false,"feedback":"Ultraendurance exercise may use up to about 90 g/hour from multiple transportable carbohydrates."},{"label":"None","correct":false,"feedback":"Ultraendurance exercise may use up to about 90 g/hour from multiple transportable carbohydrates."}]}},{"id":"sf10-3","chapter":"Recovery nutrition","title":"Recovery nutrition","html":"<h3>Recovery nutrition</h3><p>After exercise, carbohydrate restores glycogen, protein supplies amino acids for repair, and fluid replaces losses. When rapid recovery is important, the chapter uses about 1.5 g carbohydrate/kg in the first hour and 0.75–1.5 g/kg/hour over the next several hours, plus about 15–25 g high-quality protein soon after. Rehydration begins promptly and continues with sodium-containing foods and drinks.</p>","visual":null,"blocksHtml":["<div class=\"callout\"><b class=\"k\">On the “anabolic window.”</b> Muscle protein synthesis is elevated for many hours after resistance exercise, not just the 30 to 60 minutes sometimes described as a narrow window. Eating soon after training is still useful, mainly because it starts refuelling sooner and because athletes training more than once a day have less margin for delay, but a client who eats a solid meal two hours later has not missed the opportunity.</div>"]},{"id":"sf10-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"In the first recovery hour, the chapter suggests about how much carbohydrate?","options":[{"label":"0.1 g/kg","correct":false,"feedback":"Plus 15 to 25 g protein to support repair."},{"label":"0.5 g/kg","correct":false,"feedback":"Plus 15 to 25 g protein to support repair."},{"label":"1.5 g/kg","correct":true,"feedback":"Plus 15 to 25 g protein to support repair."},{"label":"5 g/kg","correct":false,"feedback":"Plus 15 to 25 g protein to support repair."}]}},{"id":"sf10-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Rehydration should exceed the measured fluid deficit because:","options":[{"label":"Sweat is salty","correct":false,"feedback":"Aim for about 1.25 to 1.5 L per kg lost."},{"label":"Urine production continues during recovery","correct":true,"feedback":"Aim for about 1.25 to 1.5 L per kg lost."},{"label":"Thirst is exact","correct":false,"feedback":"Aim for about 1.25 to 1.5 L per kg lost."},{"label":"Fluids are never absorbed","correct":false,"feedback":"Aim for about 1.25 to 1.5 L per kg lost."}]}},{"id":"sf10-4","chapter":"Popular diets, caffeine, alcohol, and supplements","title":"Popular diets, caffeine, alcohol, and supplements","html":"<h3>Popular eating patterns</h3><p>Vegetarian patterns exclude meat; vegan patterns exclude all animal products. Both can support performance when energy, protein, iron, zinc, calcium, vitamin D, iodine, omega-3 fats, and vitamin B12 are planned. Other popular diets should be judged by nutritional adequacy, sustainability, training compatibility, GI tolerance, and evidence, not by the athlete testimonials used to market them.</p><h3>Caffeine, alcohol, and supplements</h3><p>Caffeine is a legal central-nervous-system stimulant that can improve alertness and reduce perceived effort, but dose and timing affect sleep, anxiety, heart rate, and blood pressure. Alcohol does not improve performance and can impair rehydration, glycogen restoration, muscle repair, and judgment. Supplements should be screened for legality, ethics, purity, safety, and effectiveness; training and an adequate diet remain the foundation.</p>","visual":{"title":"Popular diets, caffeine, alcohol, and supplements","kind":"comparison","items":[{"label":"Vegetarian vs vegan","detail":"Vegetarian excludes meat. Vegan excludes all animal products. Both can work when energy, protein, iron, zinc, calcium, vitamin D, iodine, omega-3 and B12 are planned."},{"label":"Caffeine","detail":"A legal CNS stimulant that can raise alertness and lower perceived effort. Dose and timing affect sleep, anxiety, heart rate and blood pressure."},{"label":"Alcohol","detail":"Does not improve performance. Can impair rehydration, glycogen restoration, muscle repair and judgment."},{"label":"Supplement screen","detail":"Legality, ethics, purity, safety, effectiveness. Training and an adequate diet are the foundation."}]},"blocksHtml":[]},{"id":"sf10-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"How should an athlete judge a popular diet?","options":[{"label":"By testimonials","correct":false,"feedback":"Marketing testimonials are not evidence."},{"label":"By adequacy, sustainability, training compatibility, GI tolerance and evidence","correct":true,"feedback":"Marketing testimonials are not evidence."},{"label":"By how restrictive it is","correct":false,"feedback":"Marketing testimonials are not evidence."},{"label":"By its price","correct":false,"feedback":"Marketing testimonials are not evidence."}]}},{"id":"sf10-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Alcohol and performance: alcohol","options":[{"label":"Improves recovery","correct":false,"feedback":"It also affects muscle repair and judgment."},{"label":"Does not improve performance and can impair rehydration and glycogen restoration","correct":true,"feedback":"It also affects muscle repair and judgment."},{"label":"Boosts glycogen","correct":false,"feedback":"It also affects muscle repair and judgment."},{"label":"Replaces carbohydrate","correct":false,"feedback":"It also affects muscle repair and judgment."}]}},{"id":"sf10-5","chapter":"Nutrition periodization","title":"Nutrition periodization","html":"<h3>Nutrition periodization</h3><p>A comprehensive plan changes with preparation, competition, travel, injury, and active recovery. Energy and carbohydrate usually rise with demanding training and fall when load drops; protein remains distributed to support repair; hydration and competition practice become more specific as events approach. The athlete should rehearse the plan during training and use monitoring data to refine it.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Phase</th><th>Energy and carbohydrate</th><th>Focus</th></tr></thead><tbody><tr><td>Active recovery</td><td>Usually lowest</td><td>Protein stays distributed; micronutrient adequacy</td></tr><tr><td>Demanding preparation</td><td>Rise with load</td><td>Fuel quality sessions and recovery</td></tr><tr><td>Competition</td><td>Match the event</td><td>Rehearsed timing, hydration and competition-day practice</td></tr></tbody></table></div>"]},{"id":"sf10-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Energy and carbohydrate intake are usually lowest during:","options":[{"label":"Peak competition","correct":false,"feedback":"They rise with demanding training."},{"label":"Demanding preparation","correct":false,"feedback":"They rise with demanding training."},{"label":"Active recovery","correct":true,"feedback":"They rise with demanding training."},{"label":"Travel","correct":false,"feedback":"They rise with demanding training."}]}},{"id":"sf10-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Nutrition periodization means:","options":[{"label":"Eating the same every day","correct":false,"feedback":"Rehearse the plan in training and refine it from monitoring."},{"label":"Matching energy, carbohydrate, protein, fluid and recovery strategies to changing training","correct":true,"feedback":"Rehearse the plan in training and refine it from monitoring."},{"label":"Fasting between events","correct":false,"feedback":"Rehearse the plan in training and refine it from monitoring."},{"label":"Avoiding carbohydrate","correct":false,"feedback":"Rehearse the plan in training and refine it from monitoring."}]}},{"id":"sf10-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A 70 kg athlete needs 2,800 kcal, with 6 g/kg carbohydrate and 1.6 g/kg protein. How much fat completes the prescription?","text":"Carbohydrate 420 g (1,680 kcal) and protein 112 g (448 kcal) total 2,128 kcal. The remaining 672 kcal is about 75 g fat, roughly 24% of energy."},{"label":"A 70 kg athlete loses 1.5 kg in a hot session and trains again tomorrow. What should recovery look like?","text":"About 105 g carbohydrate and 15 to 25 g protein in the first hour, then continued carbohydrate if the gap is short, and roughly 1.9 to 2.25 L fluid with sodium over the following hours."}]}}],"flashcards":[{"front":"Diet","back":"The food and beverages a person usually consumes."},{"front":"Planning sequence","back":"Energy, then carbohydrate, protein, and fat."},{"front":"Practical minimum energy for athletes","back":"About 30 kcal/kg/day."},{"front":"Nutrient density","back":"Nutrients relative to calories."},{"front":"Empty calories","back":"Energy with few nutrients."},{"front":"Pre-exercise carbohydrate","back":"1 to 4 g/kg in the 1 to 4 hours before."},{"front":"During prolonged exercise","back":"30 to 60 g carbohydrate/hour."},{"front":"Ultraendurance","back":"Up to about 90 g/hour from multiple transportable carbohydrates."},{"front":"First recovery hour","back":"About 1.5 g carbohydrate/kg plus 15 to 25 g protein."},{"front":"Rehydration","back":"About 1.25 to 1.5 L per kg lost."},{"front":"Caffeine","back":"Legal CNS stimulant that can lower perceived effort."},{"front":"Alcohol","back":"Does not improve performance and can impair recovery."},{"front":"Nutrition periodization","back":"Matching nutrition to training phases."}],"quiz":[{"q":"According to the textbook, the word diet should be defined as:","o":["a restriction of food and beverages in an effort to lose weight.","an increase or decrease in caloric intake to gain or lose weight.","a pattern of eating.","nutrition periodization."],"a":2,"e":"The chapter defines diet simply as the food and beverages a person usually consumes, not a restrictive plan."},{"q":"The first goal of dietary planning is to establish daily _____ intake.","o":["carbohydrate","protein","fat","energy"],"a":3,"e":"Every other nutrient target has to fit inside the total energy budget, so energy is set first."},{"q":"A female who is sedentary needs approximately _____ kcal/kg to maintain body weight:","o":["25","30","35","4"],"a":1,"e":"The course-confirmed answer here is 30 kcal/kg/day for a sedentary female. (This also matches the practical minimum given elsewhere in the course for an athlete, so treat 30 kcal/kg/day as the keyed baseline for both figures in this chapter.)"},{"q":"Which energy-containing compound is typically eliminated from the diet when one is trying to lose body fat?","o":["Carbohydrate","Protein","Fat","Alcohol"],"a":3,"e":"Alcohol is not an essential nutrient, so it is commonly the first source of energy reduced when a deficit is needed."},{"q":"Which of the following is the least nutrient dense?","o":["2% milk","Whole milk","Skim milk","all the above are nutrient dense"],"a":1,"e":"Whole milk supplies similar vitamins, minerals, and protein as skim milk but with more calories from fat, so it is the least nutrient dense of the three."},{"q":"Why is the intake of a minimum amount of carbohydrate recommended?","o":["This keeps protein and fat intake from being too high, which can be harmful.","Carbohydrate is the most appetite-suppressing nutrient.","Sufficient carbohydrate is needed to resynthesize muscle glycogen.","Carbohydrate intake results in a small diuretic effect."],"a":2,"e":"Glycogen resynthesis depends on adequate carbohydrate intake."},{"q":"The recommended minimum amount of energy that an athlete should consume daily is:","o":["20 kcal/kg of body weight.","25 kcal/kg of body weight.","30 kcal/kg of body weight.","35 kcal/kg of body weight."],"a":2,"e":"The chapter uses about 30 kcal/kg/day as a practical minimum for athletes."},{"q":"What does the term “discretionary calories” mean?","o":["Calories needed to maintain energy balance after meeting macronutrient needs","Calories obtained from fat and alcohol after meeting micronutrient needs","Energy (kcal) obtained from snacks but not meals","Energy (kcal) obtained from alcohol and sugar"],"a":0,"e":"Discretionary calories are the energy remaining once essential nutrient needs are already met, available to spend on additional foods, added sugar, extra fat, or alcohol."},{"q":"Nutrient density is a concept that is based on the relationship between:","o":["protein and vitamins/minerals.","essential and nonessential nutrients.","energy and nutrients.","fat and sugar."],"a":2,"e":"Nutrient density compares the nutrients a food supplies relative to its calories."},{"q":"Athletes who are reducing their energy (kcal) intake in an effort to lose weight should consume nutrient-dense foods so that:","o":["nutrient intake will remain adequate.","hormone levels will not be negatively affected.","hydration status will remain unaffected.","supplements will be better utilized by the body."],"a":0,"e":"Choosing nutrient-dense foods protects overall nutrient adequacy even when total calories are reduced."},{"q":"What does the term “empty calories” mean?","o":["High in calories","Devoid of calories","Contains artificial sweeteners","Contains calories but lack nutrients"],"a":3,"e":"Empty calories supply energy with few accompanying nutrients."},{"q":"Once an energy (kcal) goal has been established, in what order should the other nutrients be considered?","o":["Carbohydrate, fat, protein","Carbohydrate, protein, fat","Protein, carbohydrate, fat","Fat, carbohydrate, protein"],"a":1,"e":"After total energy, the planning sequence set carbohydrate according to training demand, then protein, then fat completes the prescription."},{"q":"Why does too large of a volume of food prior to exercise result in gastrointestinal (GI) distress?","o":["Hormones related to nausea and vomiting are released.","The autonomic nervous system is negatively affected.","Heart rate is reduced when the stomach is full.","Blood flow to the GI tract is decreased with the onset of exercise."],"a":3,"e":"Exercise shunts blood toward working muscle, so a large meal volume competes with reduced GI blood flow and can cause distress."},{"q":"The results of studies of pre-exercise food and fluid intake are most applicable to _____ athletes because the majority of studies have been conducted in this population.","o":["strength","endurance","female","adolescent"],"a":1,"e":"Most of this research has been conducted on endurance athletes."},{"q":"Why is some fat usually included in a pre-exercise meal that is consumed several hours before exercise?","o":["Supplies needed vitamins","Provides a feeling of satiety","Increases gastric emptying","Depresses insulin secretion"],"a":1,"e":"Moderate fat several hours before exercise can improve satiety; it actually slows rather than increases gastric emptying."},{"q":"An endurance athlete has been experiencing intestinal cramping and diarrhea and suspects that these symptoms are related to her pre-exercise meal. Which strategy should she try?","o":["Replace some solid food with semi-solid food or liquid.","Increase foods known to be constipating, such as fat.","Eliminate food and fluid intake prior to exercise.","Add a fructose-containing sports beverage."],"a":0,"e":"Semi-solid or liquid options are generally easier to tolerate and lower the risk of GI symptoms."},{"q":"During prolonged endurance exercise, why does the liver have difficulty maintaining blood glucose within the normal range?","o":["The blood insulin concentration is depressed.","Conversion of fructose to glucose does not take place.","The central nervous system response is delayed.","The rate of gluconeogenesis is limited."],"a":3,"e":"As liver glycogen falls, gluconeogenesis cannot fully keep pace with ongoing glucose use."},{"q":"What is the recommended intake of carbohydrate per hour during prolonged endurance (not ultra endurance) exercise?","o":["10 to 30 g","30 to 60 g","60 to 90 g","90 to 120 g"],"a":1,"e":"The common target during prolonged endurance exercise is 30 to 60 g carbohydrate per hour."},{"q":"What is the recommended intake of carbohydrate per hour during “stop and go” exercise (e.g. soccer, basketball, ice hockey)?","o":["10 to 30 g","30 to 60 g","60 to 90 g","90 to 120 g"],"a":1,"e":"Intermittent, stop-and-go sport follows the same general 30 to 60 g/hour guideline as other prolonged exercise."},{"q":"During prolonged endurance (not ultra endurance) exercise, what is the estimated maximum absorption of carbohydrate per hour?","o":["10 g","30 g","60 g","90 g"],"a":2,"e":"A single transportable carbohydrate source is generally limited to about 60 g/hour of absorption; higher rates require multiple transportable carbohydrates, as used in ultraendurance events."},{"q":"The Daily Food Plans developed for MyPlate are public domain and may be freely copied and distributed.","o":["True","False"],"a":0,"e":"As US government materials, MyPlate resources are public domain."},{"q":"Alcohol may be counterproductive as a rehydration strategy because alcohol has a diuretic effect","o":["True","False"],"a":0,"e":"Alcohol's diuretic effect works against rehydration goals."},{"q":"Why is it important to consume carbohydrate immediately after exercise?","o":["Rapid glycogen resynthesis","Stimulation of insulin secretion","Fat storage (adipose tissue) replenishment","a and b","a, b, and c"],"a":3,"e":"Immediate carbohydrate supports rapid glycogen resynthesis and stimulates the insulin response that helps drive it; replenishing fat stores is not a goal of recovery nutrition."},{"q":"Why is it important to consume high- to moderate-glycemic index carbohydrates immediately after exercise?","o":["Provides more carbohydrate per gram than low-glycemic index carbohydrate","Stimulates a more rapid insulin response","Prevents the athlete from going to sleep immediately after exercise","a and b","a, b, and c"],"a":1,"e":"Higher-GI carbohydrate is digested and absorbed quickly, producing a faster insulin response that supports glycogen resynthesis; it does not provide more carbohydrate per gram."},{"q":"How much carbohydrate should an athlete consume in the first hour after exercise?","o":["0.5 g/kg of body weight","1.0 g/kg of body weight","1.5 g/kg of body weight","2.0 g/kg of body weight"],"a":1,"e":"A practical first-hour target is about 1.0 g carbohydrate/kg."},{"q":"Nutrition periodization refers to:","o":["the number of meals that should be eaten each day.","the amount of “quality Calories” an athlete consumes each day.","the process of matching nutrient intake to training.","the timing of food and supplement intake."],"a":2,"e":"Periodization means matching energy, carbohydrate, protein, fluid, and recovery strategies to the changing demands of training."},{"q":"In which mesocycle is the athlete’s energy intake likely to be the lowest because the daily energy expenditure is likely to be lowest?","o":["Active recovery","Competition","Pre-competition","Intense training during the preparation period"],"a":0,"e":"Energy and carbohydrate intake are usually lowest during active recovery, when training load is lightest."},{"q":"What is the relationship between a vitamin deficiency and athletic performance?","o":["A daily multivitamin supplement improves performance.","There is no relationship between a daily multivitamin supplement and improved performance.","A daily multivitamin supplement has been shown to decrease performance.","If a severe deficiency exists, a supplement of the deficient vitamin can improve performance."],"a":3,"e":"Correcting a true, severe deficiency can restore function, but supplementing when status is already adequate does not improve performance."},{"q":"Which of the following is likely to have the greatest impact on improved performance?","o":["Anabolic steroid use","Carbohydrate loading","Caffeine use","Training"],"a":3,"e":"Training itself has a far greater effect on performance than any single nutritional or pharmacological strategy."},{"q":"According to scientific research, the dietary supplement most likely to improve performance is:","o":["chromium picolinate.","antioxidant vitamins.","creatine.","branched chained amino acids."],"a":2,"e":"Creatine has the strongest evidence base among commonly marketed performance supplements."},{"q":"As the time before the onset of exercise increases, the amount of carbohydrate the athlete can tolerate generally increases.","o":["True","False"],"a":0,"e":"More time before exercise allows a larger carbohydrate meal, consistent with guidelines scaling grams per kg to hours before exercise."},{"q":"Fat should never be part of a pre-exercise meal.","o":["True","False"],"a":1,"e":"Moderate fat can be appropriate in a pre-exercise meal eaten several hours ahead; it is large amounts of fat close to exercise that cause problems."},{"q":"A common response to stress is gastrointestinal upset.","o":["True","False"],"a":0,"e":"Stress is a well-recognized contributor to GI symptoms around competition."},{"q":"The wrong pre-competition meal can be more detrimental to performance than the right pre-competition meal can be beneficial to performance.","o":["True","False"],"a":0,"e":"A poorly chosen pre-competition meal can cause enough GI distress or discomfort to hurt performance more than an ideal meal helps it."},{"q":"It makes sense for athletes engaged in prolonged endurance exercise to consume carbohydrates to improve performance and delay fatigue, but there is little research to suggest that such a strategy is beneficial.","o":["True","False"],"a":1,"e":"This statement is false: there is substantial, well-established research supporting carbohydrate intake during prolonged endurance exercise to improve performance and delay fatigue."}]},{"n":11,"title":"Body Composition","kicker":"Learn how body composition is measured, how much error to expect, and how to plan muscle gain or fat loss without harming health or performance.","steps":[{"id":"sf11-0","chapter":"Terminology and methods","title":"Terminology and methods","html":"<h3>Body-composition terminology</h3><p>Body mass is the amount of matter; body weight is the force of gravity on that mass. Fat mass includes essential and storage fat. Fat-free mass includes muscle, bone, organs, connective tissue, and water. Lean body mass is often used similarly but can include essential lipid. Somatotypes describe tendencies (ectomorph, mesomorph, and endomorph) but do not dictate health or performance.</p><h3>Every field method is an estimate</h3><p>Only chemical analysis of a cadaver directly measures body composition. Hydrodensitometry estimates density from underwater weight; plethysmography uses displaced air; skinfolds estimate subcutaneous fat; bioelectrical impedance depends heavily on body water; DEXA separates bone mineral, lean tissue, and fat using low-energy X-rays. Hydration, meals, recent exercise, technician skill, equipment, and equations affect results.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Hydrodensitometry</b><p>Underwater weighing estimates body density.</p></div><div class=\"tabblk\"><b>Plethysmography</b><p>Uses displaced air.</p></div><div class=\"tabblk\"><b>Skinfolds</b><p>Assume subcutaneous fat at specific sites relates closely to total body fat.</p></div><div class=\"tabblk\"><b>BIA</b><p>Depends heavily on body water, so hydration changes results.</p></div><div class=\"tabblk\"><b>DEXA</b><p>Separates bone mineral, lean tissue and fat using low-energy X-rays.</p></div><div class=\"tabblk\"><b>Chemical analysis</b><p>Cadaver analysis is the only direct measure of body composition.</p></div>"]},{"id":"sf11-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which method measures body fat directly?","options":[{"label":"Bioelectrical impedance","correct":false,"feedback":"Every field and laboratory method used on the living is an estimate."},{"label":"Skinfold measurement","correct":false,"feedback":"Every field and laboratory method used on the living is an estimate."},{"label":"Underwater weighing","correct":false,"feedback":"Every field and laboratory method used on the living is an estimate."},{"label":"Chemical analysis of cadavers","correct":true,"feedback":"Every field and laboratory method used on the living is an estimate."}]}},{"id":"sf11-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Skinfold measurement rests on the assumption that:","options":[{"label":"Fatter people have thicker skin","correct":false,"feedback":"It estimates subcutaneous fat at defined sites."},{"label":"Fat under the skin at specific sites relates closely to total body fat","correct":true,"feedback":"It estimates subcutaneous fat at defined sites."},{"label":"Light is absorbed by muscle","correct":false,"feedback":"It estimates subcutaneous fat at defined sites."},{"label":"Fat is compressed more in fatter people","correct":false,"feedback":"It estimates subcutaneous fat at defined sites."}]}},{"id":"sf11-1","chapter":"Understanding the standard error of the estimate","title":"Understanding the standard error of the estimate","html":"<h3>Understanding the SEE</h3><p>The standard error of the estimate describes typical prediction error. If underwater weighing reports 13% body fat with an SEE of about 2.7 percentage points, a reasonable interpretation is approximately 10.3–15.7%, not exactly 13%. Small changes within measurement error should not drive major diet decisions. Use the same method and standardized conditions when tracking trends.</p>","visual":null,"blocksHtml":["<h3>Why this changes how you coach</h3>","<p>If you tell a client “you’re at 18% body fat” and next month a repeat measurement reads 19%, that one-point move is very likely inside the method’s own error and means nothing on its own. Reacting to it, whether by praising “progress” or pushing harder for “regression”, risks reinforcing noise as if it were a real trend. The fix is consistency (same method, same technician if possible, similar time of day and hydration) and patience (judge trend across several measurements spaced weeks apart, not the change between any two adjacent readings).</p>"]},{"id":"sf11-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Underwater weighing reports 13% body fat with an SEE of about 2.7. How should it be interpreted?","options":[{"label":"Exactly 13%","correct":false,"feedback":"The SEE describes typical prediction error."},{"label":"About 10.3% to 15.7%","correct":true,"feedback":"The SEE describes typical prediction error."},{"label":"No lower than 13%","correct":false,"feedback":"The SEE describes typical prediction error."},{"label":"No higher than 13%","correct":false,"feedback":"The SEE describes typical prediction error."}]}},{"id":"sf11-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The standard error of the estimate is a measure of:","options":[{"label":"The accuracy of predictions","correct":true,"feedback":"Smaller means more accurate predictions."},{"label":"Sampling error only","correct":false,"feedback":"Smaller means more accurate predictions."},{"label":"Percent of wrong values","correct":false,"feedback":"Smaller means more accurate predictions."},{"label":"Standard deviation from the norm","correct":false,"feedback":"Smaller means more accurate predictions."}]}},{"id":"sf11-2","chapter":"Sport performance and interpretation","title":"Sport performance and interpretation","html":"<h3>Sport performance and interpretation</h3><p>Size and composition matter differently by sport and position. A high power-to-weight ratio helps sports requiring acceleration, jumping, or climbing; larger mass may help collision or throwing roles. Published elite-athlete ranges describe successful groups but do not prove the optimal target for an individual. BMI can misclassify muscular athletes because it does not separate fat and lean tissue.</p>","visual":null,"blocksHtml":["<p>Elite-athlete ranges are observational: researchers measured the people who were already competing at a high level and reported what they found. That tells you what tends to accompany success in that population, but it says nothing about whether pushing an individual client toward that number would help them, and it ignores genetics, injury history, and the athletes who reached elite level with very different body composition. Treat these ranges as context for a conversation, never as a target to assign.</p>","<div class=\"mn-html\"><span>Remember it</span><b>Ecto, Meso, Endo: think outside-in.</b> <b>Ecto</b>morph, like “exterior,” is lean with a fast metabolism and struggles to gain. <b>Endo</b>morph, like “endo” meaning inside, carries more fat internally and gains weight easily. <b>Meso</b>morph sits in the “middle”: naturally muscular and athletic. Most real bodies are a blend of all three, not a pure type.</div>","<dl class=\"facts\"><div><dt>Elite ranges</dt><dd>Describe successful groups. They do not prove the optimal target for an individual.</dd></div><div><dt>BMI</dt><dd>Can misclassify muscular athletes because it does not separate fat and lean tissue.</dd></div><div><dt>Power-to-weight</dt><dd>Helps sports needing acceleration, jumping or climbing.</dd></div><div><dt>Mass</dt><dd>May help collision or throwing roles.</dd></div></dl>"]},{"id":"sf11-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which somatotype often has difficulty gaining weight?","options":[{"label":"Endomorph","correct":false,"feedback":"Somatotypes describe tendencies, not health or performance."},{"label":"Mesomorph","correct":false,"feedback":"Somatotypes describe tendencies, not health or performance."},{"label":"Ectomorph","correct":true,"feedback":"Somatotypes describe tendencies, not health or performance."},{"label":"None","correct":false,"feedback":"Somatotypes describe tendencies, not health or performance."}]}},{"id":"sf11-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Published body-fat ranges for elite male tennis players show:","options":[{"label":"What performance requires","correct":false,"feedback":"They describe a group, not an individual target."},{"label":"The body composition of elite players, but not the proven optimum","correct":true,"feedback":"They describe a group, not an individual target."},{"label":"What every player should aim for","correct":false,"feedback":"They describe a group, not an individual target."},{"label":"What female players need","correct":false,"feedback":"They describe a group, not an individual target."}]}},{"id":"sf11-3","chapter":"Target-weight calculations","title":"Target-weight calculations","html":"<h3>Target-weight calculations</h3><p>A target-weight calculation starts with fat-free mass. Estimated target weight equals current fat-free mass divided by one minus the desired body-fat fraction. For example, an athlete with 70 kg fat-free mass targeting 15% body fat would estimate 70 ÷ 0.85 = 82.4 kg. The answer is a planning estimate and depends on accurate assumptions about lean mass and a realistic healthy target.</p>","visual":null,"blocksHtml":["<p>The logic behind Target weight = FFM ÷ (1 − desired body-fat fraction) is simple once you see it: if fat-free mass stays the same and only fat changes, then at the target body-fat percentage, fat-free mass must make up exactly (1 − desired body-fat fraction) of the new total weight. Rearranging that relationship for total weight gives the formula. Every error in the fat-free mass estimate (which itself comes from a body-composition method with its own SEE) carries directly into the target-weight number.</p>"]},{"id":"sf11-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"An athlete has 70 kg of fat-free mass and wants 15% body fat. The estimated target weight is:","options":[{"label":"78.4 kg","correct":false,"feedback":"70 ÷ 0.85 = 82.4 kg."},{"label":"82.4 kg","correct":true,"feedback":"70 ÷ 0.85 = 82.4 kg."},{"label":"85 kg","correct":false,"feedback":"70 ÷ 0.85 = 82.4 kg."},{"label":"70 kg","correct":false,"feedback":"70 ÷ 0.85 = 82.4 kg."}]}},{"id":"sf11-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A target-weight calculation starts with:","options":[{"label":"Current body fat percentage only","correct":false,"feedback":"It divides fat-free mass by one minus the desired body-fat fraction."},{"label":"Fat-free mass","correct":true,"feedback":"It divides fat-free mass by one minus the desired body-fat fraction."},{"label":"BMI","correct":false,"feedback":"It divides fat-free mass by one minus the desired body-fat fraction."},{"label":"Height only","correct":false,"feedback":"It divides fat-free mass by one minus the desired body-fat fraction."}]}},{"id":"sf11-4","chapter":"Increasing muscle mass","title":"Increasing muscle mass","html":"<h3>Increasing muscle mass</h3><p>Hypertrophy requires progressive resistance training, adequate energy, and positive nitrogen balance. The chapter emphasizes moderate-load, higher-volume strength work. A starting energy increase is roughly 400–500 kcal/day for men and 300–400 kcal/day for women, adjusted from weight, training, appetite, and composition trends. The chapter’s rule of thumb adds about 14 g protein/day for one pound of weekly muscle gain, though real gain is rarely perfectly linear.</p>","visual":null,"blocksHtml":[]},{"id":"sf11-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A rule of thumb estimate is that one pound of muscle tissue requires about how many additional kcal?","options":[{"label":"1,000","correct":false,"feedback":"The course uses about 1,800 kcal."},{"label":"1,800","correct":true,"feedback":"The course uses about 1,800 kcal."},{"label":"2,300","correct":false,"feedback":"The course uses about 1,800 kcal."},{"label":"3,900","correct":false,"feedback":"The course uses about 1,800 kcal."}]}},{"id":"sf11-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"How much extra protein per day supports about one pound of muscle gain per week?","options":[{"label":"14 g","correct":true,"feedback":"Assuming enough energy and resistance training."},{"label":"40 g","correct":false,"feedback":"Assuming enough energy and resistance training."},{"label":"58 g","correct":false,"feedback":"Assuming enough energy and resistance training."},{"label":"65 g","correct":false,"feedback":"Assuming enough energy and resistance training."}]}},{"id":"sf11-5","chapter":"Reducing body fat and weight cycling","title":"Reducing body fat and weight cycling","html":"<h3>Reducing body fat</h3><p>Any exercise can contribute when it helps create an appropriate energy deficit. The chapter protects training with at least about 30 kcal/kg/day and 4 g carbohydrate/kg/day. Large changes belong in the off-season or active-recovery phase because aggressive restriction competes with training quality, recovery, immunity, hormonal function, and injury prevention. Aim for gradual change and monitor both performance and health.</p><h3>Weight cycling and lightweight sport</h3><p>Weight cycling is repeated loss and regain, often intensified by weigh-ins and dehydration. Research does not consistently show a permanent metabolic-rate reduction, but athletes may experience fatigue, anger, tension, poor training, dehydration, and impaired performance. Minimum-weight calculations should protect health rather than identify the lowest number an athlete can force temporarily.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Protect training</dt><dd>At least about 30 kcal/kg/day and 4 g carbohydrate/kg/day.</dd></div><div><dt>Timing</dt><dd>Large changes belong in the off-season or active recovery phase.</dd></div><div><dt>Any exercise</dt><dd>Can contribute when it helps create an appropriate energy deficit.</dd></div><div><dt>Weight cycling</dt><dd>Repeated loss and regain. Linked to fatigue, anger, tension and dehydration.</dd></div></dl>"]},{"id":"sf11-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"For an athlete trying to lose fat, the recommended minimum daily carbohydrate is:","options":[{"label":"4 g/kg","correct":true,"feedback":"This protects training quality."},{"label":"2 g/kg","correct":false,"feedback":"This protects training quality."},{"label":"1 g/kg","correct":false,"feedback":"This protects training quality."},{"label":"0.5 g/kg","correct":false,"feedback":"This protects training quality."}]}},{"id":"sf11-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Large amounts of body fat are best lost:","options":[{"label":"During the competitive season","correct":false,"feedback":"Aggressive restriction competes with training quality during heavy phases."},{"label":"During the off-season (active recovery)","correct":true,"feedback":"Aggressive restriction competes with training quality during heavy phases."},{"label":"At the end of pre-season","correct":false,"feedback":"Aggressive restriction competes with training quality during heavy phases."},{"label":"Mid pre-season","correct":false,"feedback":"Aggressive restriction competes with training quality during heavy phases."}]}},{"id":"sf11-6","chapter":"Drugs and supplements","title":"Drugs and supplements","html":"<h3>Drugs and supplements</h3><p>Anabolic steroids mimic testosterone and can increase muscle but are prohibited and carry cardiovascular, hepatic, reproductive, psychiatric, and other risks. Prohormones such as DHEA are marketed as testosterone precursors, yet effectiveness is weak and safety uncertain. Ephedrine has medical uses but stimulant combinations have caused serious adverse events. Human evidence for CLA and many “fat burners” remains inconsistent.</p>","visual":{"title":"Drugs and supplements","kind":"comparison","items":[{"label":"Anabolic steroids","detail":"Drugs that mimic testosterone. Prohibited, with cardiovascular, hepatic, reproductive and psychiatric risks."},{"label":"Prohormones","detail":"Precursors to testosterone. DHEA is the weakest. Effectiveness is weak and safety uncertain."},{"label":"Ephedra vs ephedrine","detail":"Ephedra is the plant. Ephedrine is the active ingredient. Stimulant combinations have caused serious adverse events."},{"label":"CLA","detail":"Animal studies were promising. Human evidence has been inconsistent."}]},"blocksHtml":[]},{"id":"sf11-6-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Anabolic steroids are drugs that mimic:","options":[{"label":"Testosterone","correct":true,"feedback":"They are prohibited and carry serious risks."},{"label":"Estrogen","correct":false,"feedback":"They are prohibited and carry serious risks."},{"label":"Growth hormone","correct":false,"feedback":"They are prohibited and carry serious risks."},{"label":"All of the above","correct":false,"feedback":"They are prohibited and carry serious risks."}]}},{"id":"sf11-6-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Is CLA an effective weight-loss supplement?","options":[{"label":"No, definitely ineffective","correct":false,"feedback":"Human evidence remains inconsistent."},{"label":"Animal studies were promising, but human results are inconsistent","correct":true,"feedback":"Human evidence remains inconsistent."},{"label":"Yes, established safe and effective","correct":false,"feedback":"Human evidence remains inconsistent."}]}},{"id":"sf11-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"An athlete with 70 kg fat-free mass wants 15% body fat. What is the estimated target weight?","text":"70 ÷ 0.85 = 82.4 kg. It is a planning estimate, not a guarantee."},{"label":"An athlete’s body fat drops from 13% to 12% by skinfolds. Should the plan change?","text":"A 1 point change is within typical error (SEE around 2 to 3 points). Track trends with the same method and standardized conditions rather than reacting to one reading."}]}}],"flashcards":[{"front":"Body mass vs body weight","back":"Mass is matter; weight is the force of gravity on it."},{"front":"Fat-free mass","back":"Muscle, bone, organs, connective tissue and water."},{"front":"Only direct measure of body composition","back":"Chemical analysis of a cadaver."},{"front":"Skinfold assumption","back":"Fat under the skin at set sites relates closely to total fat."},{"front":"SEE","back":"Standard error of the estimate: typical prediction error."},{"front":"Target weight formula","back":"FFM ÷ (1 − desired body-fat fraction)."},{"front":"1 lb of muscle","back":"About 1,800 additional kcal."},{"front":"Extra protein for 1 lb/week gain","back":"About 14 g/day."},{"front":"Energy surplus to start","back":"About 400 to 500 kcal/day for men; 300 to 400 for women."},{"front":"Minimum energy and carbohydrate while cutting","back":"30 kcal/kg/day and 4 g carbohydrate/kg/day."},{"front":"Best time for large fat loss","back":"Off-season or active recovery."},{"front":"Weight cycling","back":"Repeated weight loss and regain."},{"front":"Anabolic steroids","back":"Drugs that mimic testosterone."},{"front":"Ectomorph","back":"Somatotype that often has difficulty gaining weight."}],"quiz":[{"q":"Which method measures body fat directly?","o":["Bioelectrical impedance","Skinfold measurement","Underwater weighing","Chemical analysis of cadavers"],"a":3,"e":""},{"q":"What is the Standard Error of the Estimate (SEE)?","o":["A measure of the accuracy of predictions","A measure of the sampling error","The standard deviation from the norm","The percentage of values that are considered incorrect"],"a":0,"e":""},{"q":"An athlete is weighed underwater and is told that he is 13% body fat. How should he interpret this information?","o":["His percentage of body fat is 16% (13% storage fat + 3% essential fat).","His percentage of body fat is between 10.3% and 15.7%.","His percentage of body fat is not higher than 13% but it may be lower.","His percentage of body fat is not lower than 13% but it may be higher."],"a":1,"e":""},{"q":"To increase muscle mass, an athlete must","o":["engage in strength training","consume a sufficient amount of energy","be in a positive nitrogen balance to support tissue growth","Both A and B","all of the above"],"a":4,"e":""},{"q":"Determination of body composition by skinfold measurements is based upon the assumption that:","o":["people with more body fat have thicker skin.","the amount of fat under the skin in specific locations is closely related to total body fat.","skinfold thickness in people with more body fat will be lower because fat is compressed more when pinched.","skinfold calipers measure the amount of light absorbed and reflected by body tissues such as fat and muscle."],"a":1,"e":""},{"q":"In which sport does body composition play a relatively minor role in the performance of elite athletes?","o":["Cross country running","Gymnastics","Basketball","Golf"],"a":3,"e":""},{"q":"The total amount of all tissues in the body exclusive of fat, including muscle, bone, fluids, and organs is known as:","o":["body mass","bone mass","fat-free mass","lean body mass","none of the above"],"a":2,"e":""},{"q":"What is the correct interpretation of a body composition chart that shows that professional male tennis players have approximately 11-15% body fat?","o":["Research studies have shown that male tennis players should fall within this range for best performance.","These figures reflect the body composition of elite players but it is not known if this range is best for performance.","Aspiring male professional tennis players should try to achieve this range because performance will be improved.","Female tennis players should strive for this range of body fat to improve their performance."],"a":1,"e":""},{"q":"Which of the following somatotypes often have difficulty gaining weight?","o":["endomorphs","nesinirogs","ectomorphs","none have difficulty gaining weight"],"a":2,"e":""},{"q":"Of the following, which type of exercise training is most beneficial for increasing muscle mass?","o":["Repeated sprint intervals","Very high-intensity strength training","Moderate-intensity, high-volume strength training","Long-distance running"],"a":2,"e":""},{"q":"A “rule of thumb” estimate is that a one-pound increase in muscle tissue requires approximately _____ additional kcal.","o":["1,000","1,800","2,300","3,900"],"a":2,"e":"Course-confirmed answer: approximately 2,300 additional kcal are needed per pound of muscle gained."},{"q":"As a “rule of thumb” estimate, male athletes who wish to increase muscle mass should increase daily energy intake by approximately _____ kcal.","o":["100-200","400-500","800-1,000","more than 1,000 kcal"],"a":1,"e":""},{"q":"Approximately how much additional protein is needed per day to support the growth of one pound of muscle tissue per week (assume sufficient kcal and resistance exercise)?","o":["14 g","40 g","58 g","65 g"],"a":0,"e":""},{"q":"Body fat is decreased most effectively by:","o":["repeated high-intensity, short-duration exercise.","low-intensity, long-duration exercise.","moderate-intensity, moderate-duration exercise.","any exercise that results in an appropriate caloric deficit."],"a":3,"e":""},{"q":"For an athlete trying to lose body fat, what is the recommended minimum amount of carbohydrate that should be consumed each day?","o":["4 g/kg","5 g/kg","6 g/kg","7 g/kg"],"a":1,"e":"Course-confirmed answer: the recommended minimum carbohydrate intake while losing body fat is 5 g/kg/day."},{"q":"What is the recommended minimum amount of energy that an athlete should consume daily?","o":["20 kcal/kg of body weight","25 kcal/kg of body weight","30 kcal/kg of body weight","35 kcal/kg of body weight"],"a":2,"e":""},{"q":"For most athletes, the recommended time during the yearly training cycle to begin restriction of energy intake to lose large amounts of stored body fat is:","o":["the middle of the pre-season.","the end of the pre-season.","during the competitive season.","during the off-season (active recovery)."],"a":3,"e":""},{"q":"Weight cycling is defined as:","o":["large and rapid weight loss.","repeated weight loss and gain.","weight fluctuations due to fluid loss or gain.","the inability to maintain a low body weight."],"a":1,"e":""},{"q":"Based on the results of research studies, which of the following would be expected to occur with weight cycling?","o":["A decrease in metabolic rate","A decrease in short-term, high-intensity exercise performance","An increase in sprinting, jump height, and anaerobic exercise performance","An increase in anger, tension, and fatigue"],"a":3,"e":""},{"q":"What are anabolic steroids?","o":["Drugs that mimic testosterone","Drugs that mimic estrogen","Drugs that mimic human growth hormone","All of the above"],"a":0,"e":""},{"q":"What are prohormones?","o":["Compounds that change the hormonal balance in the body","Compounds that are precursors to human growth hormone","Compounds that are precursors to testosterone","Compounds that directly increase the synthesis of muscle proteins"],"a":2,"e":""},{"q":"The weakest prohormone is:","o":["androstenedione (“andro”).","androstenediol.","dehydroepiandrosterone (DHEA).","testosterone."],"a":2,"e":""},{"q":"Why is DHEA sometimes referred to as the fountain of youth?","o":["It is typically taken by younger rather than older athletes.","It has been shown to be effective for increasing speed.","It has been shown to slow the aging process at the cellular level.","It is found in high concentrations in young people but declines with aging."],"a":3,"e":""},{"q":"Scale weight should be taken","o":["as soon as an individual is awake, before emptying the bladder or consuming any food or drink","as soon as an individual is awake, after emptying the bladder and before consuming any food or drink","just before going to bed, after emptying the bladder","any time of day is fine"],"a":1,"e":""},{"q":"What do the majority of studies conclude about the safety of DHEA supplements?","o":["DHEA is safe for younger but not older adults.","DHEA is safe for older but not younger adults.","DHEA is not safe for adults.","The safety profile of DHEA is not known."],"a":3,"e":""},{"q":"How do the terms ephedra and ephedrine compare?","o":["Ephedrine is a botanical term for a plant and ephedra is an active ingredient.","Ephedra is a botanical term for a plant and ephedrine is an active ingredient.","Ephedrine is the brand name used for non-herbal sources of ephedra.","Both terms are technically and commercially similar."],"a":1,"e":""},{"q":"What is ma huang?","o":["An herb that contains ephedrine","Ephedrine that is synthesized in the laboratory","Name of the most popular ephedrine-containing dietary supplement in the U.S.","Name of the most popular ephedrine-containing over-the-counter medication in the U.S."],"a":0,"e":""},{"q":"Ephedrine is known to be effective for:","o":["weight loss in athletes.","weight loss in sedentary but not obese adults.","asthma and nasal decongestion.","lowering blood cholesterol."],"a":2,"e":""},{"q":"Why is caffeine added to ephedrine-containing compounds?","o":["It enhances the effectiveness of ephedrine.","It reduces the side effects associated with ephedrine.","It helps to make the ephedrine a more stable compound.","It helps to reduce the potential for addiction."],"a":0,"e":""},{"q":"Is conjugated linoleic acid (CLA) considered to be effective for use as a weight-loss supplement?","o":["No, the current body of research has determined it is ineffective.","Studies in animals were promising, but results of human studies have been inconsistent.","Yes, the current body of research has established its safety and effectiveness."],"a":1,"e":""},{"q":"It is generally recommended that athletes decrease body fat before increasing muscle mass because reducing body fat will provide a greater performance benefit than increasing muscle mass.","o":["True","False"],"a":1,"e":""},{"q":"An athlete who wants to lose a large amount of body fat should begin the process during the off-season.","o":["True","False"],"a":0,"e":""},{"q":"The purpose of calculating a minimum body weight is to determine the lowest percentage of body fat consistent with good health.","o":["True","False"],"a":0,"e":""},{"q":"Most athletes who compete in lightweight sports are naturally light in weight.","o":["True","False"],"a":1,"e":"Course-confirmed answer: False — many athletes in lightweight sports are not naturally light and instead cut weight to compete in a lower category."},{"q":"The majority of research studies conclude that weight cycling results in a decrease in metabolic rate over the course of the season.","o":["True","False"],"a":1,"e":""}]},{"n":12,"title":"Disordered Eating and RED-S","kicker":"Recognize the continuum from normal to disordered eating, understand energy availability, and learn how to respond with care and refer promptly. This chapter is education, not diagnosis.","steps":[{"id":"sf12-0","chapter":"Normal eating, disordered eating, and eating disorders","title":"Normal eating, disordered eating, and eating disorders","html":"<h3>Normal eating, disordered eating, and eating disorders</h3><p>Normal eating is flexible, varied, and responsive to hunger, fullness, schedule, culture, and enjoyment. Disordered eating describes harmful restriction, bingeing, purging, rigid rules, or compensatory exercise that may not meet a formal diagnosis. Eating disorders meet clinical criteria and are serious psychiatric illnesses. People can move along this continuum, making early recognition important.</p><h3>Major clinical patterns</h3><p>Anorexia nervosa involves restriction, significantly low weight, and intense fear of weight gain or behaviours that prevent restoration. Bulimia nervosa includes recurrent binge episodes and compensatory behaviours. Binge-eating disorder includes recurrent binges without regular compensation. Other specified disorders can be equally serious even when every classic criterion is not present. Diagnosis belongs to qualified clinicians.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Normal eating</b><p>Flexible, varied, and responsive to hunger, fullness, schedule, culture and enjoyment.</p></div><div class=\"tabblk\"><b>Disordered eating</b><p>Harmful restriction, bingeing, purging, rigid rules or compensatory exercise that may not meet a formal diagnosis.</p></div><div class=\"tabblk\"><b>Eating disorders</b><p>Meet clinical criteria and are serious psychiatric illnesses. Diagnosis belongs to qualified clinicians.</p></div>","<div class=\"tbl\"><table><thead><tr><th>Pattern</th><th>Key features</th></tr></thead><tbody><tr><td>Anorexia nervosa</td><td>Restriction, significantly low weight, intense fear of weight gain or behaviours that prevent restoration</td></tr><tr><td>Bulimia nervosa</td><td>Recurrent binge episodes and compensatory behaviours</td></tr><tr><td>Binge-eating disorder</td><td>Recurrent binges without regular compensation</td></tr><tr><td>Other specified</td><td>Can be equally serious even when not every classic criterion is present</td></tr></tbody></table></div>"]},{"id":"sf12-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The best description of “normal” eating is:","options":[{"label":"Unplanned","correct":false,"feedback":"Normal eating responds to hunger, fullness, schedule, culture and enjoyment."},{"label":"Systematic","correct":false,"feedback":"Normal eating responds to hunger, fullness, schedule, culture and enjoyment."},{"label":"Flexible","correct":true,"feedback":"Normal eating responds to hunger, fullness, schedule, culture and enjoyment."},{"label":"Ritualistic","correct":false,"feedback":"Normal eating responds to hunger, fullness, schedule, culture and enjoyment."}]}},{"id":"sf12-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Binge-eating disorder includes:","options":[{"label":"Recurrent binges with regular purging","correct":false,"feedback":"The difference from bulimia nervosa is the lack of regular compensatory behaviour."},{"label":"Recurrent binges without regular compensation","correct":true,"feedback":"The difference from bulimia nervosa is the lack of regular compensatory behaviour."},{"label":"Only restriction","correct":false,"feedback":"The difference from bulimia nervosa is the lack of regular compensatory behaviour."},{"label":"Only excessive exercise","correct":false,"feedback":"The difference from bulimia nervosa is the lack of regular compensatory behaviour."}]}},{"id":"sf12-1","chapter":"Athlete-specific presentations","title":"Athlete-specific presentations","html":"<h3>Athlete-specific presentations</h3><p>Anorexia athletica describes sport-related restriction, excessive exercise, and weight cycling but is not a DSM-5 diagnosis. Muscle dysmorphia involves persistent belief that the body is insufficiently muscular. Exercise dependence is defined by compulsion, distress, injury, and impaired functioning, not a universal mileage threshold. Seasonal “making weight” behaviours can still be medically dangerous even when they do not reflect a persistent eating disorder.</p><h3>Higher-risk sport environments</h3><p>Risk is elevated when leanness is believed to improve performance, appearance is judged, revealing uniforms increase body scrutiny, or weight classes require certification. Examples include gymnastics, ballet, figure skating, distance running, cycling, bodybuilding, combat sports, jockeying, and lightweight rowing. Athletes of all genders can be affected; male presentations are under-recognized.</p>","visual":{"title":"Athlete-specific presentations","kind":"comparison","items":[{"label":"Anorexia athletica","detail":"Sport-related restriction, excessive exercise and weight cycling. Not a DSM-5 diagnosis."},{"label":"Muscle dysmorphia","detail":"Persistent belief that the body is insufficiently muscular; preoccupation with muscle size."},{"label":"Exercise dependence","detail":"Compulsion, distress, injury and impaired functioning. There is no universal mileage threshold."},{"label":"Making weight","detail":"Seasonal weight-cutting can be medically dangerous even without a persistent eating disorder."}]},"blocksHtml":[]},{"id":"sf12-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which best describes muscle dysmorphia?","options":[{"label":"Excess protein synthesis","correct":false,"feedback":"It centres on a belief that the body is not muscular enough."},{"label":"Distress when unable to exercise","correct":false,"feedback":"It centres on a belief that the body is not muscular enough."},{"label":"Lack of muscle gain despite training","correct":false,"feedback":"It centres on a belief that the body is not muscular enough."},{"label":"Preoccupation and dissatisfaction with muscle size","correct":true,"feedback":"It centres on a belief that the body is not muscular enough."}]}},{"id":"sf12-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Diagnosing exercise dependence is easy because it is defined by a set weekly amount of exercise.","options":[{"label":"True","correct":false,"feedback":"It is defined by compulsion, distress and impaired functioning, not a mileage number."},{"label":"False","correct":true,"feedback":"It is defined by compulsion, distress and impaired functioning, not a mileage number."}]}},{"id":"sf12-2","chapter":"Warning signs and higher-risk environments","title":"Warning signs and higher-risk environments","html":"<h3>Healthy discipline versus dysfunction</h3><p>Both healthy and disordered athletes may meal-plan, train consistently, or avoid some foods. Warning signs include escalating rigidity, fear, secrecy, guilt, bingeing, purging, compulsive exercise, social withdrawal, frequent weighing, injury, declining performance, delayed recovery, menstrual disruption, low libido, and distress when routines change. A stable body weight does not rule out low energy availability.</p>","visual":null,"blocksHtml":["<div class=\"callout\">Risk is higher where leanness is believed to improve performance, appearance is judged, or weight classes require certification. Examples include gymnastics, ballet, figure skating, distance running, cycling, bodybuilding, combat sports, jockeying and lightweight rowing. All genders can be affected, and male presentations are under-recognized.</div>"]},{"id":"sf12-2-s0","title":"Healthy discipline or warning sign?","teach":[],"act":{"type":"sort","prompt":"Healthy discipline or warning sign?","categories":["Can be healthy","Warning sign"],"items":[{"label":"Planning meals for training","category":0,"feedback":"Both healthy and disordered athletes may meal-plan."},{"label":"Training consistently","category":0,"feedback":"Consistency alone is not a warning sign."},{"label":"Avoiding a food for allergy or ethical reasons","category":0,"feedback":"Some avoidance is normal."},{"label":"Growing fear and guilt around eating","category":1,"feedback":"Escalating rigidity, fear and guilt are warning signs."},{"label":"Secrecy, bingeing or purging","category":1,"feedback":"Warning signs."},{"label":"Exercising through injury and distress when routines change","category":1,"feedback":"Compulsive exercise is a warning sign."},{"label":"Menstrual disruption","category":1,"feedback":"Amenorrhea is a warning sign, not a normal result of hard training."}]}},{"id":"sf12-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A stable body weight rules out low energy availability.","options":[{"label":"True","correct":false,"feedback":"An athlete can hold weight while under-fuelling because the body reduces other functions."},{"label":"False","correct":true,"feedback":"An athlete can hold weight while under-fuelling because the body reduces other functions."}]}},{"id":"sf12-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Sports considered high risk for disordered eating include bodybuilding, lightweight rowing and distance running.","options":[{"label":"True","correct":true,"feedback":"Leanness and weight-class pressures raise risk."},{"label":"False","correct":false,"feedback":"Leanness and weight-class pressures raise risk."}]}},{"id":"sf12-3","chapter":"Energy availability and its effects","title":"Energy availability and its effects","html":"<h3>Energy availability and physiological effects</h3><p>Energy availability is dietary energy remaining for normal body functions after exercise energy expenditure, relative to fat-free mass. Chronic low availability can suppress resting metabolism, reproductive hormones, bone formation, immunity, protein synthesis, gastrointestinal function, and cardiovascular health. Consequences include fatigue, illness, mood change, reduced adaptation, stress injuries, and poorer long-term performance.</p>","visual":null,"blocksHtml":["<div class=\"callout\">Chronic low availability can suppress resting metabolism, reproductive hormones, bone formation, immunity, protein synthesis, gastrointestinal function and cardiovascular health. Consequences include fatigue, illness, mood change, reduced adaptation, stress injuries and poorer long-term performance.</div>"]},{"id":"sf12-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Low energy availability is defined as:","options":[{"label":"Energy expenditure that routinely exceeds energy intake","correct":true,"feedback":"It can occur with or without an eating disorder."},{"label":"Low intake caused only by an eating disorder","correct":false,"feedback":"It can occur with or without an eating disorder."},{"label":"A hormone problem","correct":false,"feedback":"It can occur with or without an eating disorder."},{"label":"Self-imposed starvation only","correct":false,"feedback":"It can occur with or without an eating disorder."}]}},{"id":"sf12-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Energy availability is expressed relative to:","options":[{"label":"Body weight","correct":false,"feedback":"It is the energy left for normal function after exercise, relative to fat-free mass."},{"label":"Fat-free mass","correct":true,"feedback":"It is the energy left for normal function after exercise, relative to fat-free mass."},{"label":"Height","correct":false,"feedback":"It is the energy left for normal function after exercise, relative to fat-free mass."},{"label":"Age","correct":false,"feedback":"It is the energy left for normal function after exercise, relative to fat-free mass."}]}},{"id":"sf12-4","chapter":"Female Athlete Triad and RED-S","title":"Female Athlete Triad and RED-S","html":"<h3>Female Athlete Triad and RED-S</h3><p>The Triad links energy availability, menstrual function, and bone mineral density along three continua. Amenorrhea is a warning sign, not a normal consequence of hard training. Reduced estrogen and nutrient inadequacy accelerate bone loss and stress-fracture risk. RED-S broadens the model to athletes of all genders and includes many health and performance systems affected by low energy availability.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Energy availability</b><p>From optimal to low, with or without disordered eating.</p></div><div class=\"tabblk\"><b>Menstrual function</b><p>From regular cycles to amenorrhea. Amenorrhea is the absence or suppression of menstruation and is a warning sign.</p></div><div class=\"tabblk\"><b>Bone mineral density</b><p>From healthy bone to osteoporosis. Reduced estrogen and inadequate nutrients accelerate bone loss and raise stress-fracture risk.</p></div>","<div class=\"mn-html\"><span>Remember it</span><b>A three-legged stool.</b> Energy availability, menstrual function, and bone mineral density each act as one leg. Weaken one leg (usually energy availability, since it drives the other two) and the whole stool starts to wobble, even if the other two legs look fine for now.</div>","<div class=\"callout\">RED-S broadens the Triad to athletes of all genders and to many health and performance systems affected by low energy availability.</div>","<dl class=\"facts\"><div><dt>Performance effects of RED-S</dt><dd>Decreased training response, impaired judgement, decreased coordination, decreased concentration, irritability, depression, decreased endurance performance, increased injury risk, decreased glycogen stores, decreased muscle strength.</dd></div><div><dt>Health effects of RED-S</dt><dd>Menstrual dysfunction, impaired bone health, endocrine disruption, metabolic rate reduction, impaired growth and development, cardiovascular and immune consequences, and gastrointestinal and psychological effects.</dd></div></dl>"]},{"id":"sf12-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The three interrelated factors of the Female Athlete Triad are:","options":[{"label":"Health, fitness and longevity","correct":false,"feedback":"Each lies along its own continuum."},{"label":"Anorexia nervosa, bulimia nervosa and anorexia athletica","correct":false,"feedback":"Each lies along its own continuum."},{"label":"Energy availability, menstrual function and bone mineral density","correct":true,"feedback":"Each lies along its own continuum."},{"label":"Appearance, performance and body weight","correct":false,"feedback":"Each lies along its own continuum."}]}},{"id":"sf12-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Amenorrhea is defined as:","options":[{"label":"Abnormally high estrogen","correct":false,"feedback":"It is a warning sign, not a normal consequence of hard training."},{"label":"Absence or suppression of menstruation","correct":true,"feedback":"It is a warning sign, not a normal consequence of hard training."},{"label":"Excess testosterone in females","correct":false,"feedback":"It is a warning sign, not a normal consequence of hard training."},{"label":"Absent testosterone in males","correct":false,"feedback":"It is a warning sign, not a normal consequence of hard training."}]}},{"id":"sf12-5","chapter":"Approach, referral, and prevention","title":"Approach, referral, and prevention","html":"<h3>Approach, referral, and prevention</h3><p>Speak privately, use observed facts rather than labels or appearance, express concern, listen, and refer promptly. Coaches should not prescribe target weights or act as the treatment provider. Effective care may involve a physician, eating-disorder-informed dietitian, mental-health clinician, athletic therapist, and family. Prevention includes adequate fuelling, flexible eating, weight-neutral coaching language, confidential referral pathways, and policies that reduce unnecessary weigh-ins.</p>","visual":{"title":"Approach, referral, and prevention","kind":"sequence","items":[{"label":"Speak privately","detail":"Choose a private, calm moment."},{"label":"Use observed facts","detail":"Describe what you have seen rather than labels or appearance."},{"label":"Express concern and listen","detail":"Show care and let the athlete speak."},{"label":"Refer promptly","detail":"Refer to a qualified professional. Coaches should not prescribe target weights or act as the treatment provider."},{"label":"Coordinate and prevent","detail":"Care may involve a physician, eating-disorder-informed dietitian, mental-health clinician, athletic therapist and family. Prevention includes adequate fuelling, flexible eating, weight-neutral language and fewer unnecessary weigh-ins."}]},"blocksHtml":[]},{"id":"sf12-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"If an eating disorder is suspected, the most appropriate course of action for a coach is to:","options":[{"label":"Give the athlete time to resolve it alone","correct":false,"feedback":"Prompt referral is the priority."},{"label":"Ask a colleague to talk to the athlete","correct":false,"feedback":"Prompt referral is the priority."},{"label":"Casually discuss food intake","correct":false,"feedback":"Prompt referral is the priority."},{"label":"Immediately refer the athlete to a trained professional","correct":true,"feedback":"Prompt referral is the priority."}]}},{"id":"sf12-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Why does the IOC Medical Commission recommend that coaches not determine or evaluate weight or body composition?","options":[{"label":"Coaches always choose too low a weight","correct":false,"feedback":"That influence makes the role a conflict."},{"label":"Coaches typically have the most influence over an athlete’s behaviour","correct":true,"feedback":"That influence makes the role a conflict."},{"label":"Coaches lack time","correct":false,"feedback":"That influence makes the role a conflict."},{"label":"Coaches cause eating disorders","correct":false,"feedback":"That influence makes the role a conflict."}]}},{"id":"sf12-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"An athlete stays at a steady weight but has missed several periods and has a stress fracture. What might be going on?","text":"Steady weight does not rule out low energy availability. Missed periods and a stress injury are warning signs consistent with the Triad or RED-S. Refer promptly to a physician and an eating-disorder-informed team."},{"label":"A coach asks you to set a target weight for a gymnast. How do you respond?","text":"Coaches should not prescribe target weights or run the treatment. Suggest a weight-neutral approach, confidential referral pathways and a qualified professional to assess any concerns."}]}}],"flashcards":[{"front":"Normal eating","back":"Flexible, varied and responsive to hunger, fullness, schedule, culture and enjoyment."},{"front":"Disordered eating","back":"Harmful restriction, bingeing, purging, rigid rules or compensatory exercise short of a diagnosis."},{"front":"Anorexia nervosa","back":"Restriction, significantly low weight, intense fear of weight gain."},{"front":"Bulimia nervosa","back":"Recurrent binges with compensatory behaviours."},{"front":"Binge-eating disorder","back":"Recurrent binges without regular compensation."},{"front":"Anorexia athletica","back":"Sport-related restriction and excessive exercise. Not a DSM-5 diagnosis."},{"front":"Muscle dysmorphia","back":"Persistent belief that the body is insufficiently muscular."},{"front":"Exercise dependence","back":"Compulsion, distress and impaired functioning. No universal mileage threshold."},{"front":"Energy availability","back":"Dietary energy remaining after exercise expenditure, relative to fat-free mass."},{"front":"Female Athlete Triad","back":"Energy availability, menstrual function, bone mineral density."},{"front":"Amenorrhea","back":"Absence or suppression of menstruation."},{"front":"RED-S","back":"Relative energy deficiency in sport: broader model affecting all genders."},{"front":"Who should diagnose","back":"Qualified clinicians."},{"front":"Coach's role","back":"Refer promptly. Do not set target weights or treat."}],"quiz":[{"q":"The best description of “normal” eating is:","o":["unplanned.","systematic.","flexible.","ritualistic."],"a":2,"e":""},{"q":"Which of the following characteristics is NOT associated with anorexia athletica?","o":["Voluntary excessive exercise","Weight cycling","Losing body fat to improve performance","Lifelong struggle with abnormal eating patterns"],"a":3,"e":""},{"q":"In which sport are athletes likely to meet the criteria for anorexia athletica but rarely for anorexia nervosa or bulimia nervosa?","o":["Gymnastics","Wrestling","Ballet","Long-distance running"],"a":1,"e":""},{"q":"Amenorrhea is associated with:","o":["anorexia nervosa.","bulimia nervosa.","anorexia athletica.","a and c","all of the above"],"a":4,"e":""},{"q":"Why are wrestlers who restrict food and purge to “make weight” not considered to have an eating disorder not otherwise specified (EDNOS)?","o":["They only behave this way during wrestling season.","They do not base their self-esteem on weight.","They fall within the normal range on tests of eating attitudes.","a and b","All of the above"],"a":4,"e":""},{"q":"The best definition of excessive exercise is:","o":["exercise equivalent to running more than 50 miles/week.","exercise equivalent to running more than 100 miles/week.","exercise equivalent to running more than 150 miles/week.","none of the above"],"a":3,"e":""},{"q":"The following episodes are associated with binge eating:","o":["eating much more rapidly than normal","eating until feeling uncomfortably full","Feeling disgusted with oneself, depressed or very guilty afterwards.","All of the above are episodes associated with binge eating"],"a":3,"e":""},{"q":"Which condition listed below is the most prevalent in athletes?","o":["Anorexia nervosa","Bulimia nervosa","Disordered eating","All of the above have approximately the same prevalence"],"a":2,"e":""},{"q":"Which of the following is true regarding male athletes and eating disorders?","o":["Eating disorders have only been documented in female athletes.","Eating disorders have been documented in males but only in wrestlers and bodybuilders.","Eating disorders in male athletes have been reported but the prevalence is low.","The prevalence of eating disorders in males appears to be on a rapid rise."],"a":2,"e":""},{"q":"Which of the following best describes the condition known as muscle dysmorphia?","o":["Excessive protein synthesis in skeletal muscles","Severe psychological distress if not able to exercise","Lack of increase in muscle mass despite appropriate eating and exercise","Preoccupation and dissatisfaction with muscle size"],"a":3,"e":""},{"q":"What is the expected impact on muscle mass when disordered eating or an eating disorder is present over many years?","o":["Likely to decline","Likely to increase","Not likely to be affected"],"a":0,"e":""},{"q":"What is the expected impact on bone density when disordered eating or an eating disorder is present over many years?","o":["Likely to decline","Likely to increase","Not likely to be affected"],"a":0,"e":""},{"q":"What is the expected impact on metabolic rate when disordered eating or an eating disorder is present over many years?","o":["Likely to decline","Likely to increase","Not likely to be affected"],"a":0,"e":""},{"q":"What is the expected impact on long-term performance when disordered eating or an eating disorder is present over many years?","o":["Likely to decline","Likely to increase","Not likely to be affected"],"a":0,"e":""},{"q":"If the presence of an eating disorder is suspected, which is the most appropriate course of action for a coach to take?","o":["Give the athlete time to resolve the issue before taking any action.","Ask an assistant coach or athletic trainer to talk directly to the athlete.","Meet with the athlete and casually discuss his or her food intake.","Immediately refer the athlete to a trained professional for further evaluation."],"a":3,"e":""},{"q":"Why does the International Olympic Committee Medical Commission recommend that coaches not be involved in determining or evaluating an athlete’s weight or body composition?","o":["Coaches always choose a weight that is too low.","Coaches typically have the most influence over an athlete’s behavior.","Coaches do not have the time to closely monitor the athlete’s diet.","Coaches cause eating disorders."],"a":1,"e":""},{"q":"What are the three distinct but interrelated factors associated with the Female Athlete Triad?","o":["Health, fitness, and longevity","Anorexia nervosa, bulimia nervosa, and anorexia athletica","Appearance, performance, and optimal body weight","Energy availability, menstrual function, and bone mineral density"],"a":3,"e":""},{"q":"Muscle dysmorphia is more prevalent in females than males.","o":["True","False"],"a":1,"e":""},{"q":"Low energy availability is defined as a(n):","o":["energy expenditure that routinely exceeds energy intake.","low energy intake caused by an eating disorder.","hormonal disruption that results in the delayed uptake of glucose.","reduced metabolic rate due to self-imposed starvation."],"a":0,"e":""},{"q":"Amenorrhea is defined as an:","o":["abnormally high concentration of estrogen-related hormones.","absence or suppression of menstruation.","excess production of testosterone in females.","absence of normal testosterone production in males."],"a":1,"e":""},{"q":"Diagnosing exercise dependence or voluntary excessive exercise is relatively easy because the diagnostic criterion is specific for the maximum amount of exercise that should be performed in a week.","o":["True","False"],"a":1,"e":""},{"q":"Most wrestlers that use self-induced vomiting and laxatives to “cut” weight also have eating disorders.","o":["True","False"],"a":1,"e":""},{"q":"Sports considered at high risk for development of disordered eating include bodybuilding, lightweight rowing, and distance running.","o":["True","False"],"a":0,"e":""},{"q":"Less is known about eating disorders and disordered eating in males than females.","o":["True","False"],"a":0,"e":""},{"q":"Athletes with and without disordered eating patterns share many features of their diet and exercise patterns but differ in their actions and perspectives.","o":["True","False"],"a":0,"e":""}]},{"n":13,"title":"Lifelong Health","kicker":"Look beyond competition: how activity, food, body weight and behaviour shape long-term health and chronic disease risk.","steps":[{"id":"sf13-0","chapter":"From competitive athlete to lifelong activity","title":"From competitive athlete to lifelong activity","html":"<h3>From competitive athlete to lifelong activity</h3><p>Training often declines after school or competitive sport, but weight gain is not inevitable. Energy intake may remain matched to a former workload while daily movement falls. Lifelong health benefits from aerobic activity, resistance training, flexibility, balance, and reduced sedentary time. Former athletes may need a new identity and routine rather than an attempt to recreate peak training.</p><h3>Common diet and activity recommendations</h3><p>Healthy patterns converge on vegetables, fruit, whole grains, legumes, nuts, lean or plant proteins, fish, and unsaturated fats while limiting trans fat, excess saturated fat, sodium, refined grains, added sugars, and heavy alcohol use. Adults commonly aim for at least 150 minutes of moderate aerobic activity or an equivalent amount of vigorous activity each week, plus muscle-strengthening activity on two or more days.</p>","visual":null,"blocksHtml":[]},{"id":"sf13-0-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"It is inevitable that former athletes gain weight as body fat as they age.","options":[{"label":"True","correct":false,"feedback":"Weight gain often reflects unchanged intake with falling movement, so it is not inevitable."},{"label":"False","correct":true,"feedback":"Weight gain often reflects unchanged intake with falling movement, so it is not inevitable."}]}},{"id":"sf13-0-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Adults commonly aim for at least how much moderate aerobic activity per week?","options":[{"label":"30 minutes","correct":false,"feedback":"Or an equivalent amount of vigorous activity, plus muscle strengthening on two or more days."},{"label":"75 minutes","correct":false,"feedback":"Or an equivalent amount of vigorous activity, plus muscle strengthening on two or more days."},{"label":"150 minutes","correct":true,"feedback":"Or an equivalent amount of vigorous activity, plus muscle strengthening on two or more days."},{"label":"500 minutes","correct":false,"feedback":"Or an equivalent amount of vigorous activity, plus muscle strengthening on two or more days."}]}},{"id":"sf13-1","chapter":"Body weight regulation","title":"Body weight regulation","html":"<h3>Body weight regulation</h3><p>Long-term weight reflects energy intake and expenditure interacting with genetics, appetite, sleep, stress, medications, food availability, and environment. Leptin is produced by fat cells and participates in long-term energy regulation. Ghrelin is produced mainly in the stomach and stimulates appetite. Weight loss triggers compensatory hunger and lower expenditure, which helps explain why maintenance is difficult and requires continued support.</p>","visual":{"title":"Body weight regulation","kind":"sequence","items":[{"label":"Fat stores send a signal","detail":"Leptin is released roughly in proportion to body fat; more fat generally means more circulating leptin."},{"label":"The hypothalamus reads the signal","detail":"Higher leptin normally signals “stores are adequate,” which should reduce hunger and support energy expenditure."},{"label":"Weight loss lowers leptin","detail":"As fat mass falls, leptin falls too, and the brain interprets that as a shortage, driving hunger up and expenditure down, this is a core reason weight regains so easily after dieting."},{"label":"Ghrelin adds a second push","detail":"Ghrelin rises before meals and with energy restriction, further stimulating appetite alongside falling leptin."}]},"blocksHtml":[]},{"id":"sf13-1-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which hormone is produced by fat cells and plays a role in long-term energy balance?","options":[{"label":"Leptin","correct":true,"feedback":"Leptin is released by fat cells in proportion to fat stores and signals the brain about long-term energy reserves. Ghrelin, from the stomach, works in the opposite direction and stimulates appetite."},{"label":"Adrenaline","correct":false,"feedback":"Leptin is released by fat cells in proportion to fat stores and signals the brain about long-term energy reserves. Ghrelin, from the stomach, works in the opposite direction and stimulates appetite."},{"label":"Ghrelin","correct":false,"feedback":"Leptin is released by fat cells in proportion to fat stores and signals the brain about long-term energy reserves. Ghrelin, from the stomach, works in the opposite direction and stimulates appetite."},{"label":"Serotonin","correct":false,"feedback":"Leptin is released by fat cells in proportion to fat stores and signals the brain about long-term energy reserves. Ghrelin, from the stomach, works in the opposite direction and stimulates appetite."}]}},{"id":"sf13-1-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Ghrelin’s primary role is to:","options":[{"label":"Decrease appetite","correct":false,"feedback":"It is made mainly in the stomach."},{"label":"Stimulate appetite","correct":true,"feedback":"It is made mainly in the stomach."},{"label":"Induce satiety","correct":false,"feedback":"It is made mainly in the stomach."},{"label":"Store fat","correct":false,"feedback":"It is made mainly in the stomach."}]}},{"id":"sf13-2","chapter":"BMI and abdominal fat","title":"BMI and abdominal fat","html":"<h3>BMI and abdominal fat</h3><p>BMI is weight in kilograms divided by height in metres squared. It is a population screening tool, not a direct measure of fat or an individual diagnosis. A BMI of 30 or more is classified as obesity in the standard adult categories. Waist circumference adds information about abdominal fat and cardiometabolic risk. Muscularity, age, sex, ethnicity, and clinical measures affect interpretation.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Why waist circumference helps</dt><dd>It is a simple proxy for visceral fat that BMI cannot see, so two people with the same BMI can carry very different cardiometabolic risk depending on where that weight sits.</dd></div><div><dt>Apple vs pear pattern</dt><dd>Abdominal (“apple”) fat distribution generally carries more risk than hip-and-thigh (“pear”) distribution at the same total body fat.</dd></div><div><dt>Using BMI and waist together</dt><dd>A raised waist circumference adds concern at any BMI, including in the “healthy” BMI range, which is why the two measures are usually read alongside each other rather than either alone.</dd></div></dl>"]},{"id":"sf13-2-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"A 30-year-old sedentary male has a BMI of 31. This places him in the category of:","options":[{"label":"Low BMI","correct":false,"feedback":"A BMI of 30 or more is classified as obesity in the standard adult categories."},{"label":"Healthy range","correct":false,"feedback":"A BMI of 30 or more is classified as obesity in the standard adult categories."},{"label":"Overweight","correct":false,"feedback":"A BMI of 30 or more is classified as obesity in the standard adult categories."},{"label":"Obesity","correct":true,"feedback":"A BMI of 30 or more is classified as obesity in the standard adult categories."}]}},{"id":"sf13-2-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"BMI is best described as:","options":[{"label":"A measure of muscle mass","correct":false,"feedback":"Its best use is estimating health risk in the general population."},{"label":"A method of measuring body composition","correct":false,"feedback":"Its best use is estimating health risk in the general population."},{"label":"A number representing a weight-to-height ratio","correct":true,"feedback":"Its best use is estimating health risk in the general population."},{"label":"A performance predictor","correct":false,"feedback":"Its best use is estimating health risk in the general population."}]}},{"id":"sf13-3","chapter":"Comparing popular weight-loss plans","title":"Comparing popular weight-loss plans","html":"<h3>Comparing popular weight-loss plans</h3><p>Atkins is very low in carbohydrate and may induce ketosis. Ornish is very low in fat. Zone uses approximately 40% carbohydrate, 30% protein, and 30% fat. Weight Watchers emphasizes portion and energy control. Research discussed in the chapter finds similar short-term losses across different plans and no clear named-plan winner for substantial long-term loss over two years or more. Adherence and sustainability dominate.</p>","visual":null,"blocksHtml":["<div class=\"tbl\"><table><thead><tr><th>Plan</th><th>Emphasis</th></tr></thead><tbody><tr><td>Atkins</td><td>Very low carbohydrate; may induce ketosis</td></tr><tr><td>Ornish</td><td>Very low fat</td></tr><tr><td>Zone</td><td>About 40% carbohydrate, 30% protein, 30% fat (40-30-30)</td></tr><tr><td>Weight Watchers</td><td>Portion and energy control</td></tr></tbody></table></div>","<div class=\"callout\">Research finds similar short-term losses across plans and no clear named-plan winner for substantial long-term loss over two years or more. Adherence and sustainability dominate.</div>"]},{"id":"sf13-3-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which weight-loss plan is also known as the 40-30-30 diet?","options":[{"label":"Atkins","correct":false,"feedback":"40% carbohydrate, 30% protein, 30% fat."},{"label":"Ornish","correct":false,"feedback":"40% carbohydrate, 30% protein, 30% fat."},{"label":"Weight Watchers","correct":false,"feedback":"40% carbohydrate, 30% protein, 30% fat."},{"label":"Zone","correct":true,"feedback":"40% carbohydrate, 30% protein, 30% fat."}]}},{"id":"sf13-3-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which plan induces ketosis?","options":[{"label":"Atkins","correct":true,"feedback":"Its very low carbohydrate intake can induce ketosis."},{"label":"Ornish","correct":false,"feedback":"Its very low carbohydrate intake can induce ketosis."},{"label":"Weight Watchers","correct":false,"feedback":"Its very low carbohydrate intake can induce ketosis."},{"label":"Zone","correct":false,"feedback":"Its very low carbohydrate intake can induce ketosis."}]}},{"id":"sf13-4","chapter":"Type 2 diabetes and metabolic syndrome","title":"Type 2 diabetes and metabolic syndrome","html":"<h3>Type 2 diabetes and metabolic syndrome</h3><p>Type 2 diabetes is characterized primarily by insulin resistance. Early in the condition, blood glucose and insulin may both be high because the pancreas compensates. Exercise has an insulin-like effect on muscle glucose uptake and improves sensitivity. Metabolic syndrome is a cluster involving abdominal obesity, high triglycerides, low HDL, high blood pressure, and elevated glucose; three of five criteria establish the diagnosis.</p>","visual":{"title":"Type 2 diabetes and metabolic syndrome","kind":"sequence","items":[{"label":"Insulin resistance","detail":"Tissues respond less effectively to insulin. This is the primary characteristic of type 2 diabetes."},{"label":"The pancreas compensates","detail":"Early on, insulin output rises, so blood glucose and insulin can both be high."},{"label":"Exercise helps","detail":"Exercise has an insulin-like effect on muscle glucose uptake and improves sensitivity."}]},"blocksHtml":["<div class=\"mn-html\"><span>Remember it</span><b>“A Terribly High Blood Glucose.”</b> Abdominal obesity, Triglycerides high, HDL low, Blood pressure high, Glucose high, five criteria, three needed for the diagnosis.</div>"]},{"id":"sf13-4-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The primary characteristic of type 2 diabetes is:","options":[{"label":"Lack of insulin production","correct":false,"feedback":"The pancreas secretes insulin but tissues respond less effectively."},{"label":"Insulin resistance","correct":true,"feedback":"The pancreas secretes insulin but tissues respond less effectively."},{"label":"Overproduction of glucagon","correct":false,"feedback":"The pancreas secretes insulin but tissues respond less effectively."},{"label":"Hypoglycemia","correct":false,"feedback":"The pancreas secretes insulin but tissues respond less effectively."}]}},{"id":"sf13-4-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Exercise is effective for type 2 diabetes because it:","options":[{"label":"Stimulates the pancreas to secrete more insulin","correct":false,"feedback":"It also improves insulin sensitivity."},{"label":"Has an insulin-like effect and stimulates glucose uptake into muscle","correct":true,"feedback":"It also improves insulin sensitivity."},{"label":"Repairs alpha cells","correct":false,"feedback":"It also improves insulin sensitivity."},{"label":"Lowers appetite","correct":false,"feedback":"It also improves insulin sensitivity."}]}},{"id":"sf13-5","chapter":"Cardiovascular disease, bone, and cancer prevention","title":"Cardiovascular disease, bone, and cancer prevention","html":"<h3>Cardiovascular disease and hypertension</h3><p>Atherosclerosis begins early with fatty streaks and develops over decades. Major modifiable risks include smoking, hypertension, high LDL, low HDL, diabetes, inactivity, and excess body fat. Trans fat increases risk; replacing saturated and trans fats with monounsaturated, polyunsaturated, and omega-3-rich foods can help. Total cholesterol, LDL, HDL, triglycerides, blood pressure, and the complete risk profile must be interpreted together.</p><h3>Osteoporosis and cancer prevention</h3><p>Osteoporosis combines low bone mineral density with structural deterioration and fracture risk. Peak bone mass generally develops by the twenties or early thirties, and loss accelerates after menopause. Weight-bearing and resistance activity improve strength, stability, and bone outcomes. Lifestyle-related cancer recommendations largely overlap with other chronic-disease guidance: healthy weight, regular activity, plant-rich food patterns, limited alcohol, and no tobacco.</p>","visual":null,"blocksHtml":["<dl class=\"facts\"><div><dt>Fatty streaks</dt><dd>Begin in childhood and adolescence.</dd></div><div><dt>Major modifiable risks</dt><dd>Smoking, hypertension, high LDL, low HDL, diabetes, inactivity and excess body fat.</dd></div><div><dt>Trans fat</dt><dd>Increases heart disease risk.</dd></div><div><dt>Osteoporosis</dt><dd>Low bone mineral density with structural deterioration.</dd></div><div><dt>Fastest bone loss</dt><dd>The first several years after menopause.</dd></div></dl>"]},{"id":"sf13-5-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Fatty streaks, which begin the narrowing of arteries, typically start in:","options":[{"label":"Childhood and adolescence","correct":true,"feedback":"Chronic diseases can begin early in life."},{"label":"Early adulthood","correct":false,"feedback":"Chronic diseases can begin early in life."},{"label":"Middle adulthood","correct":false,"feedback":"Chronic diseases can begin early in life."},{"label":"Older adulthood","correct":false,"feedback":"Chronic diseases can begin early in life."}]}},{"id":"sf13-5-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Peak bone mineral density occurs at about:","options":[{"label":"10 to 20 years","correct":false,"feedback":"With adequate calcium intake."},{"label":"20 to 35 years","correct":true,"feedback":"With adequate calcium intake."},{"label":"35 to 60 years","correct":false,"feedback":"With adequate calcium intake."},{"label":"After 60","correct":false,"feedback":"With adequate calcium intake."}]}},{"id":"sf13-6","chapter":"Behaviour change and supportive environments","title":"Behaviour change and supportive environments","html":"<h3>Behaviour change and supportive environments</h3><p>Knowledge is rarely enough. The health-belief model focuses on perceived risk, severity, benefits, and barriers. Social cognitive theory emphasizes expected outcomes, skills, confidence, modelling, and environment. Sustainable counselling uses specific goals, self-monitoring, problem-solving, social support, and relapse planning. Community, school, workplace, and policy changes can make nutritious food and movement easier choices.</p>","visual":null,"blocksHtml":["<div class=\"tabblk\"><b>Health-belief model</b><p>Focuses on perceived risk, severity, benefits and barriers.</p></div><div class=\"tabblk\"><b>Social cognitive theory</b><p>Emphasizes expected outcomes, skills, confidence, modelling and environment.</p></div><div class=\"tabblk\"><b>Sustainable counselling</b><p>Specific goals, self-monitoring, problem-solving, social support and relapse planning. Community, school, workplace and policy changes make healthy choices easier.</p></div>"]},{"id":"sf13-6-q0","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"The health-belief model focuses on:","options":[{"label":"Perceived risk, severity, benefits and barriers","correct":true,"feedback":"Knowledge alone is rarely enough."},{"label":"Only genetics","correct":false,"feedback":"Knowledge alone is rarely enough."},{"label":"Only nutrition knowledge","correct":false,"feedback":"Knowledge alone is rarely enough."},{"label":"Environmental design only","correct":false,"feedback":"Knowledge alone is rarely enough."}]}},{"id":"sf13-6-q1","title":"Quick check","teach":[],"act":{"type":"choice","prompt":"Which is a feature of sustainable counselling?","options":[{"label":"One big goal","correct":false,"feedback":"Small specific steps with monitoring and planning last longer."},{"label":"Specific goals, self-monitoring and relapse planning","correct":true,"feedback":"Small specific steps with monitoring and planning last longer."},{"label":"Avoiding support","correct":false,"feedback":"Small specific steps with monitoring and planning last longer."},{"label":"Only information","correct":false,"feedback":"Small specific steps with monitoring and planning last longer."}]}},{"id":"sf13-cases","chapter":"Apply it","title":"Case questions","teach":[],"act":{"type":"explore","prompt":"Think through each case, then open it to compare.","panels":[{"label":"A former college rower has gained weight since graduating and feels ‘the metabolism is gone.’ How do you respond?","text":"Weight gain is not inevitable. Intake often stays matched to a former workload while daily movement falls. Build a new routine around aerobic, resistance and daily movement rather than trying to recreate peak training."},{"label":"A client is discouraged after losing only 10 lb of a 50 lb goal and has high blood pressure. What can you tell them?","text":"Even modest fat loss tends to lower blood pressure, so the 10 lb loss is meaningful progress."}]}}],"flashcards":[{"front":"Creeping obesity","back":"A slow gain of body fat as adults age."},{"front":"Weekly aerobic guideline","back":"At least 150 minutes moderate or equivalent vigorous."},{"front":"Strength guideline","back":"Muscle-strengthening on two or more days per week."},{"front":"Leptin","back":"Made by fat cells; long-term energy regulation."},{"front":"Ghrelin","back":"Made in the stomach; stimulates appetite."},{"front":"BMI","back":"Weight (kg) ÷ height (m)²."},{"front":"BMI of 30 or more","back":"Obesity in the standard adult categories."},{"front":"Zone diet","back":"40% carbohydrate, 30% protein, 30% fat."},{"front":"Atkins","back":"Very low carbohydrate; may induce ketosis."},{"front":"Ornish","back":"Very low fat."},{"front":"Type 2 diabetes","back":"Primarily insulin resistance."},{"front":"Metabolic syndrome","back":"Three of five: abdominal obesity, triglycerides, HDL, blood pressure, glucose."},{"front":"Peak bone mass","back":"About 20 to 35 years."},{"front":"Health-belief model","back":"Perceived risk, severity, benefits and barriers."}],"quiz":[{"q":"A client who is 50 lb overweight and has high blood pressure is discouraged because she has only lost 10 lb of body fat. What effect would a 10-pound loss of body fat likely have on her blood pressure?","o":["Raise blood pressure","Lower blood pressure","No effect because a 10 lb weight loss is not enough for a person who is 50 lb overweight"],"a":1,"e":""},{"q":"What is “creeping obesity”?","o":["A slow gain of body fat as adults age","The process of muscle turning to fat","Change in body fat distribution after menopause","A genetic predisposition to gain weight"],"a":0,"e":""},{"q":"A 30-year-old sedentary male has a body mass index (BMI) of 31. Which category does this place him in?","o":["Low BMI","Healthy range","Overweight","Obesity"],"a":3,"e":""},{"q":"According to recent scientific studies, which weight-loss plan has been proven to be effective for significant long-term (2 years or more) weight loss?","o":["Atkins diet","Ornish diet","Weight Watchers diet","Zone diet","None of the above"],"a":4,"e":""},{"q":"Which weight-loss plan contains the lowest amount of dietary fat?","o":["Atkins diet","Ornish diet","Weight Watchers diet","Zone diet"],"a":1,"e":""},{"q":"Which weight-loss plan contains the lowest amount of dietary carbohydrate?","o":["Atkins diet","Ornish diet","Weight Watchers diet","Zone diet"],"a":0,"e":""},{"q":"Which weight loss plan is also known as the 40-30-30 diet?","o":["Atkins diet","Ornish diet","Weight Watchers diet","Zone diet"],"a":3,"e":""},{"q":"What does 40-30-30 represent?","o":["40% carbohydrate (CHO) and 30% each protein and fat","40% fat and 30% each protein and CHO","40% protein and 30% each fat and CHO","40 lb lost in the 1st 6 months, 30 lb lost in subsequent 6-month periods"],"a":0,"e":""},{"q":"Which weight-loss plan induces ketosis?","o":["Atkins diet","Ornish diet","Weight Watchers diet","Zone diet"],"a":0,"e":""},{"q":"Which activity is most likely to result in appropriate weight loss?","o":["Daily physical activity meeting the Surgeon General’s recommendations","Strength training two days per week","Aerobic exercise of sufficient duration/intensity to expend > 2000 kcal per week","Exercise in heat and humidity to induce heavy sweating"],"a":2,"e":""},{"q":"The primary characteristic of type 2 diabetes is:","o":["lack of insulin production.","insulin resistance.","overproduction of glucagon.","hypoglycemia."],"a":1,"e":""},{"q":"The majority of people who have type 2 diabetes are:","o":["underweight.","at a healthy weight.","obese."],"a":2,"e":""},{"q":"Common symptoms in individuals with type 2 diabetes include:","o":["hypoglycemia and hypoinsulinemia.","hypoglycemia and hyperinsulinemia.","hyperglycemia and hypoinsulinemia.","hyperglycemia and hyperinsulinemia."],"a":3,"e":""},{"q":"Choose the best description of insulin resistance from among the following.","o":["The pancreas fails to produce insulin due to damage to alpha (α) cells.","The pancreas produces insulin but fails to secrete a sufficient amount when blood glucose is high.","The pancreas secretes insulin, but the insulin does not work as effectively on the tissue receptors.","The pancreas secretes glucagon instead of insulin in response to high blood glucose."],"a":2,"e":""},{"q":"Exercise is effective for those with type 2 diabetes because it:","o":["stimulates the pancreas to secrete more insulin.","has a strong insulin-like effect and stimulates glucose uptake into muscles.","helps repair the alpha (α) cells in the pancreas.","improves aerobic fitness."],"a":1,"e":""},{"q":"The development of fatty streaks, a change associated with eventual narrowing of the arteries, typically begins in:","o":["childhood and adolescence.","early adulthood (20s and 30s).","middle adulthood (40s and 50s).","older adulthood (60s and beyond)."],"a":0,"e":""},{"q":"Which of the following is NOT a major risk factor for heart disease?","o":["Cigarette smoking","Hypertension","Low total blood cholesterol concentration","Low concentration of high-density lipoprotein cholesterol"],"a":2,"e":""},{"q":"Which is/are of importance in the prediction of the risk of heart disease?","o":["Total cholesterol below 200 mg/dl","High-density lipoprotein cholesterol greater than 60 mg/dl","Low-density lipoprotein cholesterol less than 100 mg/dl","B and C only","all of the above"],"a":4,"e":""},{"q":"Low bone mineral density with structural deterioration is known as:","o":["osteomalacia.","osteopenia.","osteoporosis.","osteoarthritis."],"a":2,"e":""},{"q":"At what age does peak bone mineral density occur (assuming that calcium intake is adequate)?","o":["10 to 20 years","20 to 35 years","35 to 60 years","After age 6"],"a":1,"e":""},{"q":"The period of time associated with the most rapid loss of bone mass is:","o":["age 20 to 35 years.","age 35 to 50 years.","the first several years after menopause.","after males are 65 years or older."],"a":2,"e":""},{"q":"Strong scientific evidence exists which suggests that diets high in _____ increase heart disease risk.","o":["trans fatty acids","monounsaturated fats","polyunsaturated fats","all of the above"],"a":0,"e":""},{"q":"What are the known benefits of strength training and weight bearing activities for post-menopausal women?","o":["Increases leg muscle strength","Increases stability","Increases bone density","a and b","all of the above"],"a":4,"e":""},{"q":"On average, the bone density of men and African American women is approximately _____ greater than that of Caucasian women.","o":["5%","20%","35%","65%"],"a":1,"e":""},{"q":"When compared to recommendations made for other chronic diseases, the diet and exercise recommendations made for preventing lifestyle-related cancers are:","o":["similar.","different in many respects.","substantially different.","in opposition to other recommendations."],"a":0,"e":""},{"q":"What is body mass index (BMI)?","o":["A measure of how much muscle mass an athlete should have","A method of measuring body composition","A formula that predicts the best weight for performance and health","A number that represents a weight-to-height ratio"],"a":3,"e":""},{"q":"The most appropriate use of body mass index (BMI) is to determine:","o":["potential health risks in the general population","potential health risks in the athletic population.","ideal weight for adults.","ideal weight for athletes."],"a":0,"e":""},{"q":"_____ is a hormone produced by fat cells and plays an important role in long-term energy balance and weight maintenance.","o":["Leptin","Adrenaline","Ghrelin","Serotonin"],"a":0,"e":""},{"q":"Ghrelin is a hormone synthesized by cells in the stomach and its primary role in the body is to:","o":["decrease appetite.","stimulate appetite.","induce a feeling of satiety.","a and c"],"a":1,"e":""},{"q":"It is inevitable that former athletes gain weight as body fat as they age.","o":["True","False"],"a":1,"e":""},{"q":"There is a steady decline in physical activity as people age.","o":["True","False"],"a":0,"e":""},{"q":"There is a strong inverse relationship between physical activity and premature mortality.","o":["True","False"],"a":0,"e":""},{"q":"Chronic diseases can begin in infancy, childhood, adolescence, and young adulthood.","o":["True","False"],"a":0,"e":""}]}]};
